import { unzipSync, zipSync, type Zippable } from "fflate";

const EPOCH = new Date("1980-01-01T00:00:00.000Z");
// ZIP stores a timezone-free DOS timestamp. fflate reads local Date fields, so
// shift the required UTC epoch to local midnight to emit the same bytes in
// every host timezone (and avoid treating it as 1979 west of UTC).
const ZIP_EPOCH = new Date(EPOCH.getTime() + EPOCH.getTimezoneOffset() * 60_000);
const FIXED_FILE_OPTIONS = { level: 9 as const, mtime: ZIP_EPOCH, os: 0, attrs: 0 };
const FIXED_DIRECTORY_OPTIONS = { ...FIXED_FILE_OPTIONS, attrs: 0x10 };

export function normalizeOoxmlPackage(bytes: Uint8Array): Buffer {
  let entries: Record<string, Uint8Array>;
  try {
    entries = unzipSync(bytes);
  } catch {
    throw new Error("invalid_ooxml_zip");
  }

  return normalizeOoxmlEntries(entries);
}

export function normalizeOoxmlEntries(entries: Record<string, Uint8Array>): Buffer {
  const sorted: Zippable = {};
  for (const name of Object.keys(entries).sort()) {
    sorted[name] = [
      entries[name]!,
      name.endsWith("/") ? FIXED_DIRECTORY_OPTIONS : FIXED_FILE_OPTIONS,
    ];
  }

  try {
    return Buffer.from(zipSync(sorted, FIXED_FILE_OPTIONS));
  } catch {
    throw new Error("invalid_ooxml_zip");
  }
}
