import type {
  RedlineBlock,
  RedlineDocument,
  RedlinePriority,
  RedlineSegment,
} from "./contracts.js";

export type RedlineErrorCode =
  | "unbalanced_tag"
  | "nested_change"
  | "missing_annotation"
  | "invalid_priority"
  | "unsafe_html";

export class RedlineParseError extends Error {
  constructor(readonly code: RedlineErrorCode) {
    super(code);
    this.name = "RedlineParseError";
  }
}

function appendKeep(segments: RedlineSegment[], text: string): void {
  if (!text) return;
  const previous = segments.at(-1);
  if (previous?.kind === "keep") {
    previous.text += text;
    return;
  }
  segments.push({ kind: "keep", text });
}

function parseAnnotation(source: string): {
  length: number;
  reason: string;
  priority: RedlinePriority;
} {
  const annotation = /^(?: )?\[([^\]\r\n]*)\]/u.exec(source);
  if (!annotation) throw new RedlineParseError("missing_annotation");

  const fields = /^(.+?)\s+·\s+(\S+)$/u.exec(annotation[1]!.trim());
  if (!fields) throw new RedlineParseError("missing_annotation");
  const priority = fields[2]!;
  if (priority !== "P0" && priority !== "P1" && priority !== "P2") {
    throw new RedlineParseError("invalid_priority");
  }
  return { length: annotation[0].length, reason: fields[1]!.trim(), priority };
}

function parseSegments(source: string): RedlineSegment[] {
  const segments: RedlineSegment[] = [];
  let cursor = 0;
  let keepStart = 0;
  let active: { kind: "insert" | "delete"; contentStart: number } | undefined;
  let pendingReplacement: { kind: "delete"; text: string } | undefined;

  while (cursor < source.length) {
    if (source[cursor] !== "<") {
      cursor += 1;
      continue;
    }

    const tagEnd = source.indexOf(">", cursor);
    if (tagEnd === -1) throw new RedlineParseError("unsafe_html");
    const rawTag = source.slice(cursor, tagEnd + 1);
    const tag = /^<(\/)?(ins|del)>$/u.exec(rawTag);
    if (!tag) throw new RedlineParseError("unsafe_html");

    const closing = tag[1] === "/";
    const kind = tag[2] === "ins" ? "insert" : "delete";
    if (!closing) {
      if (active) throw new RedlineParseError("nested_change");
      if (pendingReplacement && kind !== "insert") {
        throw new RedlineParseError("nested_change");
      }
      appendKeep(segments, source.slice(keepStart, cursor));
      active = { kind, contentStart: tagEnd + 1 };
      cursor = tagEnd + 1;
      keepStart = cursor;
      continue;
    }

    if (!active) throw new RedlineParseError("unbalanced_tag");
    if (active.kind !== kind) throw new RedlineParseError("nested_change");

    const changed = { kind: active.kind, text: source.slice(active.contentStart, cursor) };
    const afterClosingTag = source.slice(tagEnd + 1);
    if (active.kind === "delete" && !pendingReplacement && afterClosingTag.startsWith("<ins>")) {
      pendingReplacement = changed as { kind: "delete"; text: string };
      cursor = tagEnd + 1;
      keepStart = cursor;
      active = undefined;
      continue;
    }

    const annotation = parseAnnotation(afterClosingTag);
    if (pendingReplacement) {
      if (active.kind !== "insert") throw new RedlineParseError("nested_change");
      segments.push({
        ...pendingReplacement,
        reason: annotation.reason,
        priority: annotation.priority,
      });
      pendingReplacement = undefined;
    }
    segments.push({ ...changed, reason: annotation.reason, priority: annotation.priority });
    cursor = tagEnd + 1 + annotation.length;
    keepStart = cursor;
    active = undefined;
  }

  if (active) throw new RedlineParseError("unbalanced_tag");
  if (pendingReplacement) throw new RedlineParseError("missing_annotation");
  appendKeep(segments, source.slice(keepStart));
  return segments;
}

export function parseRedlineMarkdown(markdownBody: string): RedlineDocument {
  const blocks: RedlineBlock[] = [];
  const paragraph: string[] = [];

  const flushParagraph = (): void => {
    if (paragraph.length === 0) return;
    blocks.push({ kind: "paragraph", segments: parseSegments(paragraph.join("\n")) });
    paragraph.length = 0;
  };

  for (const line of markdownBody.replace(/\r\n?/gu, "\n").split("\n")) {
    const heading = /^(#{1,6})[ \t]+(.*)$/u.exec(line);
    if (heading) {
      flushParagraph();
      if (heading[1]!.length > 3) throw new RedlineParseError("unsafe_html");
      blocks.push({
        kind: "heading",
        level: heading[1]!.length as 1 | 2 | 3,
        segments: parseSegments(heading[2]!),
      });
      continue;
    }
    if (line.trim() === "") {
      flushParagraph();
      continue;
    }
    paragraph.push(line);
  }
  flushParagraph();
  return { blocks };
}
