/**
 * `brain.glossario` collection — preferred and forbidden terms.
 */

import { z } from "zod";

import { IsoDateTimeSchema } from "./_common.js";

export const BRAIN_GLOSSARIO_TYPE = "brain.glossario" as const;
export const BRAIN_GLOSSARIO_CONVENTIONAL_PATH = "brain/glossario.md" as const;

export const BrainGlossarioFrontmatterSchema = z
  .object({
    title: z.string().min(1).max(300).default("Glossário"),
    type: z.literal(BRAIN_GLOSSARIO_TYPE),
    updated_at: IsoDateTimeSchema,
    sources: z.array(z.string().min(1).max(300)).optional(),
  })
  .strict();

export type BrainGlossarioFrontmatter = z.infer<
  typeof BrainGlossarioFrontmatterSchema
>;
