/**
 * Tool: `proxy_serper` — Google SERP via Serper.dev.
 *
 * Thin passthrough to `POST /api/v1/apis/serper`. No caching: SERPs are
 * volatile and the backend applies its own rate limiting.
 */
import {
  authenticatedJson,
  BackendError,
  NetworkError,
  NotAuthenticatedError,
  RateLimitedError,
  SessionExpiredError,
} from "../lib/api.js";

export const PROXY_SERPER_INPUT_SCHEMA = {
  type: "object",
  properties: {
    q: { type: "string", description: "Search query." },
    gl: { type: "string", description: "Country code (default: 'br')." },
    hl: { type: "string", description: "Language code (default: 'pt-br')." },
    num: {
      type: "integer",
      description: "Number of results (1-100, default 10).",
      minimum: 1,
      maximum: 100,
    },
  },
  required: ["q"],
  additionalProperties: true,
} as const;

export interface ProxySerperInput {
  q: string;
  gl?: string;
  hl?: string;
  num?: number;
  [k: string]: unknown;
}

export type ProxySerperOutput =
  | { ok: true; data: unknown }
  | { ok: false; error: string; hint?: string; retry_after_sec?: number };

export async function runProxySerper(input: ProxySerperInput): Promise<ProxySerperOutput> {
  if (typeof input.q !== "string" || input.q.trim().length === 0) {
    return { ok: false, error: "bad_input", hint: "Field 'q' is required." };
  }
  try {
    const data = await authenticatedJson<unknown>("/api/v1/apis/serper", {
      method: "POST",
      body: JSON.stringify(input),
    });
    return { ok: true, data };
  } catch (err) {
    return mapProxyError(err);
  }
}

export function mapProxyError(err: unknown): {
  ok: false;
  error: string;
  hint?: string;
  retry_after_sec?: number;
} {
  if (err instanceof NotAuthenticatedError) {
    return { ok: false, error: err.code, hint: "Use the `auth_login_start` MCP tool (then `auth_login_poll`) first." };
  }
  if (err instanceof SessionExpiredError) {
    return { ok: false, error: err.code, hint: "Use the `auth_login_start` MCP tool (then `auth_login_poll`) to renew." };
  }
  if (err instanceof RateLimitedError) {
    return {
      ok: false,
      error: err.code,
      hint: `Rate limit (${err.scope}). Retry after ${err.retryAfterSec}s.`,
      retry_after_sec: err.retryAfterSec,
    };
  }
  if (err instanceof NetworkError) {
    return { ok: false, error: err.code, hint: err.detail };
  }
  if (err instanceof BackendError) {
    return {
      ok: false,
      error: err.code,
      hint: `HTTP ${err.status}: ${err.detail.slice(0, 200)}`,
    };
  }
  const detail = err instanceof Error ? err.message : String(err);
  return { ok: false, error: "unknown_error", hint: detail };
}
