/**
 * Tool: `get_content` (Rodada 21B, ADR-012 §3; Rodada 22F: hub + slugs).
 *
 * Fetches a single projected content entity by slug within the project
 * identified by `(ws_slug, proj_slug)`. Retorna frontmatter + body
 * preview (primeiros ~500 chars). Body completo: via a ferramenta
 * `materialize_project` + leitura local.
 */
import {
  authenticatedJson,
  authenticatedJsonAt,
  BackendError,
  NetworkError,
  NotAuthenticatedError,
  RateLimitedError,
  SessionExpiredError,
  SkillNotFoundError,
} from "../lib/api.js";
import {
  PROJECT_SCOPE_SCHEMA_FRAGMENT,
  resolveProjectScope,
} from "../lib/project-scope.js";

export interface GetContentInput {
  ws_slug: string;
  proj_slug: string;
  slug: string;
}

export interface ContentItem {
  path: string;
  type: string;
  slug: string;
  title: string | null;
  status: string | null;
  frontmatter: unknown;
  bodyPreview: string | null;
  updatedAt: string;
}

export type GetContentOutput =
  | { ok: true; item: ContentItem }
  | {
      ok: false;
      error:
        | "not_authenticated"
        | "session_expired"
        | "rate_limited"
        | "not_in_hub"
        | "project_not_in_hub"
        | "not_found"
        | "backend_error"
        | "network_error"
        | "bad_input"
        | "unknown_error";
      hint?: string;
      retry_after_sec?: number;
    };

const SLUG_REGEX = /^[a-z0-9][a-z0-9-]*$/u;

export const GET_CONTENT_INPUT_SCHEMA = {
  type: "object",
  properties: {
    ...PROJECT_SCOPE_SCHEMA_FRAGMENT,
    slug: {
      type: "string",
      description: "Slug of the entity to fetch.",
      pattern: "^[a-z0-9][a-z0-9-]*$",
    },
  },
  required: ["ws_slug", "proj_slug", "slug"],
  additionalProperties: false,
} as const;

export async function runGetContent(
  input: GetContentInput,
  cwd: string = process.cwd(),
  target: { backendUrl?: string; hubFile?: string; materializeTool?: string } = {},
): Promise<GetContentOutput> {
  if (!input || typeof input.slug !== "string") {
    return {
      ok: false,
      error: "bad_input",
      hint: "Field 'slug' is required (string).",
    };
  }
  const slug = input.slug.trim();
  if (!SLUG_REGEX.test(slug)) {
    return {
      ok: false,
      error: "bad_input",
      hint: `Invalid slug '${input.slug}'. Lowercase, alphanumerics and hyphens only.`,
    };
  }

  const scope = await resolveProjectScope(input, cwd, target.hubFile, target.materializeTool);
  if (!scope.ok) return scope;

  try {
    const path = `/api/v1/ws/${scope.ws_id}/projects/${scope.proj_id}/content/${encodeURIComponent(slug)}`;
    const body = target.backendUrl
      ? await authenticatedJsonAt<{ item: ContentItem }>(target.backendUrl, path, {
          method: "GET",
        })
      : await authenticatedJson<{ item: ContentItem }>(path, { method: "GET" });
    return { ok: true, item: body.item };
  } catch (err) {
    return mapError(err);
  }
}

function mapError(err: unknown): GetContentOutput {
  if (err instanceof NotAuthenticatedError) {
    return {
      ok: false,
      error: err.code,
      hint: "Use the `auth_login_start` MCP tool (then `auth_login_poll`) first.",
    };
  }
  if (err instanceof SessionExpiredError) {
    return { ok: false, error: err.code, hint: "Session expired." };
  }
  if (err instanceof RateLimitedError) {
    return {
      ok: false,
      error: err.code,
      hint: `Retry after ${err.retryAfterSec}s.`,
      retry_after_sec: err.retryAfterSec,
    };
  }
  if (err instanceof SkillNotFoundError) {
    return {
      ok: false,
      error: "not_found",
      hint: err.hint ?? "Slug not found in this project.",
    };
  }
  if (err instanceof NetworkError) {
    return { ok: false, error: err.code, hint: err.detail };
  }
  if (err instanceof BackendError) {
    return {
      ok: false,
      error: err.code,
      hint: `HTTP ${err.status}: ${err.detail.slice(0, 200)}`,
    };
  }
  return {
    ok: false,
    error: "unknown_error",
    hint: err instanceof Error ? err.message : String(err),
  };
}
