/**
 * `brain.provas` collection — durable proof vault for institutional and
 * product claims that recur across content.
 */

import { z } from "zod";

import { IsoDateTimeSchema } from "./_common.js";

export const BRAIN_PROVAS_TYPE = "brain.provas" as const;
export const BRAIN_PROVAS_CONVENTIONAL_PATH = "brain/provas.md" as const;

export const BrainProvasFrontmatterSchema = z
  .object({
    title: z.string().min(1).max(200),
    type: z.literal(BRAIN_PROVAS_TYPE),
    updated_at: IsoDateTimeSchema,
  })
  .strict();

export type BrainProvasFrontmatter = z.infer<
  typeof BrainProvasFrontmatterSchema
>;
