/**
 * Tiny in-memory TTL cache, process-local. Lives for the lifetime of the
 * MCP server process (which Claude Code keeps alive while the plugin is
 * enabled). No LRU, no persistence — the working set is dominated by a
 * handful of skill-context payloads per session.
 *
 * Never caches 4xx/5xx responses; callers only pass successful values.
 */

interface Entry<V> {
  value: V;
  /** Epoch ms when this entry stops being valid. */
  expiresAt: number;
}

export class TtlCache<V> {
  private readonly store: Map<string, Entry<V>> = new Map();

  constructor(
    private readonly defaultTtlMs: number,
    private readonly now: () => number = Date.now,
  ) {
    if (defaultTtlMs <= 0) {
      throw new Error("TtlCache: defaultTtlMs must be positive");
    }
  }

  /** Returns the cached value or `undefined` when absent/expired. */
  get(key: string): V | undefined {
    const entry = this.store.get(key);
    if (!entry) return undefined;
    if (this.now() >= entry.expiresAt) {
      this.store.delete(key);
      return undefined;
    }
    return entry.value;
  }

  set(key: string, value: V, ttlMs: number = this.defaultTtlMs): void {
    this.store.set(key, { value, expiresAt: this.now() + ttlMs });
  }

  delete(key: string): void {
    this.store.delete(key);
  }

  /** Current number of entries, including expired ones still in the map. */
  size(): number {
    return this.store.size;
  }

  clear(): void {
    this.store.clear();
  }
}

/**
 * Build a deterministic cache key from an arbitrary params object. Keys are
 * stable across equal-value objects with different insertion order.
 */
export function cacheKey(prefix: string, params: Record<string, unknown>): string {
  const keys = Object.keys(params).sort();
  const normalised: Record<string, unknown> = {};
  for (const k of keys) normalised[k] = params[k];
  return `${prefix}:${JSON.stringify(normalised)}`;
}
