import { randomBytes } from "node:crypto";

import { BACKEND_URL, backendProtectionHeaders } from "../lib/config.js";
import { getToken, savePluginAuth } from "../lib/keychain.js";

export type AuthStatusInput = Record<string, never>;
export interface AuthLoginStartInput {
  email: string;
  callback_url?: string;
}
export interface AuthLoginPollInput {
  email: string;
  state: string;
}

export const AUTH_STATUS_INPUT_SCHEMA = {
  type: "object",
  properties: {},
  additionalProperties: false,
} as const;

export const AUTH_LOGIN_START_INPUT_SCHEMA = {
  type: "object",
  properties: {
    email: { type: "string", minLength: 3 },
    callback_url: {
      type: "string",
      description:
        "Optional callback URL. Defaults to the Conversion Agent web callback; localhost is only for legacy CLI flows.",
    },
  },
  required: ["email"],
  additionalProperties: false,
} as const;

export const AUTH_LOGIN_POLL_INPUT_SCHEMA = {
  type: "object",
  properties: {
    email: { type: "string", minLength: 3 },
    state: { type: "string", minLength: 8 },
  },
  required: ["email", "state"],
  additionalProperties: false,
} as const;

export async function runAuthStatus(_input?: AuthStatusInput): Promise<{
  ok: true;
  authenticated: boolean;
  email: string | null;
  source: string | null;
  expires_at?: string;
}> {
  const cred = await getToken();
  return {
    ok: true,
    authenticated: cred !== null,
    email: cred?.email ?? null,
    source: cred?.source ?? null,
    ...(cred?.expiresAt ? { expires_at: cred.expiresAt } : {}),
  };
}

export async function runAuthLoginStart(input: AuthLoginStartInput): Promise<
  | { ok: true; email: string; state: string; expires_in: number }
  | { ok: false; error: "bad_input" | "backend_error" | "network_error"; hint?: string }
> {
  if (!input || typeof input.email !== "string") {
    return { ok: false, error: "bad_input", hint: "Field 'email' is required." };
  }
  const state = randomBytes(18).toString("base64url");
  try {
    const callbackUrl = input.callback_url ?? defaultWebCallbackUrl();
    const res = await fetch(`${BACKEND_URL}/api/auth/magic-link`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        accept: "application/json",
        ...backendProtectionHeaders(),
      },
      body: JSON.stringify({
        email: input.email,
        callback_url: callbackUrl,
        state,
      }),
    });
    const body = (await res.json().catch(() => ({}))) as {
      expires_in?: number;
      error?: string;
      hint?: string;
    };
    if (!res.ok) {
      return {
        ok: false,
        error: "backend_error",
        hint: body.hint ?? body.error ?? `HTTP ${res.status}`,
      };
    }
    return {
      ok: true,
      email: input.email.trim().toLowerCase(),
      state,
      expires_in: body.expires_in ?? 600,
    };
  } catch (err) {
    return {
      ok: false,
      error: "network_error",
      hint: err instanceof Error ? err.message : String(err),
    };
  }
}

function defaultWebCallbackUrl(): string {
  const url = new URL(`${BACKEND_URL}/auth/callback`);
  url.searchParams.set("source", "claude-plugin");
  return url.toString();
}

export async function runAuthLoginPoll(input: AuthLoginPollInput): Promise<
  | {
      ok: true;
      pending: boolean;
      authenticated: boolean;
      email?: string;
      expires_at?: string;
    }
  | { ok: false; error: "bad_input" | "backend_error" | "network_error"; hint?: string }
> {
  if (
    !input ||
    typeof input.email !== "string" ||
    typeof input.state !== "string"
  ) {
    return {
      ok: false,
      error: "bad_input",
      hint: "Fields 'email' and 'state' are required.",
    };
  }
  try {
    const res = await fetch(`${BACKEND_URL}/api/auth/poll`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        accept: "application/json",
        ...backendProtectionHeaders(),
      },
      body: JSON.stringify({ email: input.email, state: input.state }),
    });
    if (res.status === 202) {
      return { ok: true, pending: true, authenticated: false };
    }
    const body = (await res.json().catch(() => ({}))) as {
      access_token?: string;
      expires_at?: string;
      email?: string;
      error?: string;
      hint?: string;
    };
    if (!res.ok || !body.access_token || !body.email) {
      return {
        ok: false,
        error: "backend_error",
        hint: body.hint ?? body.error ?? `HTTP ${res.status}`,
      };
    }
    await savePluginAuth({
      email: body.email,
      token: body.access_token,
      expiresAt: body.expires_at,
    });
    return {
      ok: true,
      pending: false,
      authenticated: true,
      email: body.email,
      expires_at: body.expires_at,
    };
  } catch (err) {
    return {
      ok: false,
      error: "network_error",
      hint: err instanceof Error ? err.message : String(err),
    };
  }
}
