// ---------------------------------------------------------------------------
// Frontmatter parsing
// ---------------------------------------------------------------------------

/**
 * Matches a YAML frontmatter block at the very start of a document:
 * three dashes, newline, body, three dashes on a line by themselves.
 * The body capture is `[^]` to include newlines (ES2018 `s` flag is widely
 * supported but we stay portable).
 */
const FRONTMATTER_REGEX = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/u;

export interface ParseFrontmatterResult {
  ok: boolean;
  frontmatter?: Record<string, unknown>;
  body?: string;
  error?: string;
}

/**
 * Parse a markdown document's YAML frontmatter.
 *
 * When `expectedType` is supplied the parsed object is validated against
 * the corresponding schema. On failure `ok` is false and `error` has a
 * human-readable message; on success `frontmatter` is the raw parsed
 * object (not the schema's inferred type) so callers can round-trip
 * unknown keys if the schema is `passthrough`.
 */
export function parseFrontmatter(
  content: string,
  expectedType?: CollectionType,
): ParseFrontmatterResult {
  if (typeof content !== "string") {
    return { ok: false, error: "content_not_a_string" };
  }
  const match = FRONTMATTER_REGEX.exec(content);
  if (!match) {
    return { ok: false, error: "missing_frontmatter" };
  }
  const yamlBody = match[1] ?? "";
  const body = match[2] ?? "";

  // Use JSON_SCHEMA so ISO-8601 timestamps stay as strings (the default
  // CORE_SCHEMA eagerly converts `2026-04-23T10:00:00Z` into a Date, which
  // then fails Zod's `.datetime()` string check). JSON_SCHEMA also avoids
  // magic conversions to undefined/NaN for values like `~` or `.nan`.
  let parsed: unknown;
  try {
    parsed = yaml.load(yamlBody, { schema: yaml.JSON_SCHEMA });
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return { ok: false, error: `invalid_yaml: ${message}` };
  }

  if (parsed === null || parsed === undefined) {
    return { ok: false, error: "empty_frontmatter" };
  }
  if (typeof parsed !== "object" || Array.isArray(parsed)) {
    return { ok: false, error: "frontmatter_not_an_object" };
  }

  const frontmatter = parsed as Record<string, unknown>;

  if (expectedType) {
    const entry = COLLECTION_REGISTRY[expectedType];
    if (!entry) {
      return { ok: false, error: `unknown_collection_type: ${expectedType}` };
    }
    const result = entry.schema.safeParse(frontmatter);
    if (!result.success) {
      const first = result.error.issues[0];
      const where = first?.path?.join(".") ?? "";
      const message = first?.message ?? "validation_failed";
      return {
        ok: false,
        error: where
          ? `invalid_frontmatter: ${where}: ${message}`
          : `invalid_frontmatter: ${message}`,
      };
    }
    // The schema succeeded — return both the validated (parsed) object and
    // the body. We keep `frontmatter` pointing at the raw object so callers
    // can still see any extras if the schema was non-strict.
    return { ok: true, frontmatter, body };
  }

  return { ok: true, frontmatter, body };
}

/**
 * Serialize a frontmatter object back to a YAML block (without the `---`
 * fences). Mirrors the JSON_SCHEMA mode used by `parseFrontmatter` so ISO
 * timestamps survive the round-trip as strings.
 *
 * Unset / undefined keys are dropped entirely. The order of keys follows
 * insertion order of the input object — js-yaml preserves it.
 */
export function serializeFrontmatter(fm: Record<string, unknown>): string {
  // js-yaml's `dump` strips undefined keys when `skipInvalid: true`.
  return yaml.dump(fm, {
    schema: yaml.JSON_SCHEMA,
    skipInvalid: true,
    lineWidth: 120,
    noRefs: true,
    sortKeys: false,
  });
}

/**
 * Build a full markdown document from a frontmatter object + body.
 * Reverse of `parseFrontmatter`. Always emits a trailing newline at the
 * end of both the YAML block and the body.
 */
export function buildMarkdown(frontmatter: Record<string, unknown>, body: string): string {
  const yamlBlock = serializeFrontmatter(frontmatter).replace(/\s+$/, "");
  const trimmedBody = body.startsWith("\n") ? body.slice(1) : body;
  return `---\n${yamlBlock}\n---\n${trimmedBody}`;
}

/**
 * Apply a partial patch to a frontmatter object and return a new object —
 * the original is not mutated. Patch keys with `undefined` are removed
 * (allowing callers to drop fields cleanly).
 */
export function mergeFrontmatter(
  base: Record<string, unknown>,
  patch: Record<string, unknown>,
): Record<string, unknown> {
  const out: Record<string, unknown> = { ...base };
  for (const [key, value] of Object.entries(patch)) {
    if (value === undefined) {
      delete out[key];
    } else {
      out[key] = value;
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// Wikilinks
// ---------------------------------------------------------------------------

const WIKILINK_REGEX = /\[\[([a-z0-9][a-z0-9-]*)\]\]/gu;

/**
 * Return the unique slugs referenced in `body` via `[[slug]]` wikilinks.
 *
 * Order is insertion order (first appearance wins). Invalid slugs (uppercase,
 * unicode, spaces) are skipped silently — this matches the regex above.
 */
export function extractWikilinks(body: string): string[] {
  if (typeof body !== "string" || body.length === 0) return [];
  const seen = new Set<string>();
  const out: string[] = [];
  WIKILINK_REGEX.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = WIKILINK_REGEX.exec(body)) !== null) {
    const slug = match[1];
    if (slug && !seen.has(slug)) {
      seen.add(slug);
      out.push(slug);
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// Type inference from path
// ---------------------------------------------------------------------------

/**
 * Heuristic fallback when the frontmatter doesn't carry `type:`.
 *
 * Priority order:
 *   1. Exact full-path matches (brain files).
 *   2. Directory-prefix matches (deliverables/...).
 *
 * Returns `null` when nothing matches — callers treat this as "unknown, skip".
 */
export function inferTypeFromPath(path: string): CollectionType | null {
  if (typeof path !== "string" || path.length === 0) return null;

  for (const [type, entry] of Object.entries(COLLECTION_REGISTRY) as [
    CollectionType,
    CollectionRegistryEntry,
  ][]) {
    const convPath = entry.conventional_path;
    if (convPath.endsWith("/")) continue; // prefix — handled below
    if (path === convPath) return type;
  }

  for (const [type, entry] of Object.entries(COLLECTION_REGISTRY) as [
    CollectionType,
    CollectionRegistryEntry,
  ][]) {
    const convPath = entry.conventional_path;
    if (!convPath.endsWith("/")) continue;
    if (path.startsWith(convPath)) return type;
  }

  return null;
}
