/**
 * Hub helpers — MCP server side (Rodada 22F; active-project na 22N).
 *
 * O MCP server precisa resolver `(ws_slug, proj_slug) → (ws_id, proj_id,
 * absolute_path)` a partir do `.conversion-hub.json` na pasta onde o
 * usuário abriu o Claude Code. Leitura é o caso comum; na Rodada 22N
 * ganhamos `setActiveProject` para que o Consultor (sessão) possa pinar
 * o project ativo via MCP tool.
 *
 * Este módulo é o dono do schema do hub no mundo plugin-first: a
 * materialização (`materialize_project`) escreve o `.conversion-hub.json`
 * com `ensureHub`, `addProjectToHub`, `writeHub`.
 */
import { randomUUID } from "node:crypto";
import { access, mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname, isAbsolute, join, parse as parsePath, resolve } from "node:path";

/** Canonical filename that marks a hub root. */
export const HUB_FILE = ".conversion-hub.json";
export const SEARCHHUB_HUB_FILE = ".conversion-searchhub-hub.json";

export interface HubProjectEntry {
  ws_slug: string;
  proj_slug: string;
  ws_id: string;
  proj_id: string;
  path: string;
}

export interface HubActiveProject {
  ws_slug: string;
  proj_slug: string;
}

export interface HubConfig {
  version: 1;
  created_at: string;
  updated_at: string;
  projects: HubProjectEntry[];
  active: HubActiveProject | null;
}

export class ProjectNotMaterializedError extends Error {
  public readonly ws_slug: string;
  public readonly proj_slug: string;
  constructor(ws_slug: string, proj_slug: string) {
    super(
      `Project '${ws_slug}/${proj_slug}' não está materializado neste hub. Use a ferramenta \`materialize_project\` primeiro.`,
    );
    this.name = "ProjectNotMaterializedError";
    this.ws_slug = ws_slug;
    this.proj_slug = proj_slug;
  }
}

async function fileExists(path: string): Promise<boolean> {
  try {
    await access(path);
    return true;
  } catch {
    return false;
  }
}

/**
 * Walk upward from `cwd` looking for `.conversion-hub.json`.
 */
export async function findHubRoot(
  cwd: string,
  hubFile: string = HUB_FILE,
): Promise<string | null> {
  let current = resolve(cwd);
  const fsRoot = parsePath(current).root;
  for (let i = 0; i < 64; i += 1) {
    if (await fileExists(join(current, hubFile))) return current;
    const parent = dirname(current);
    if (parent === current || current === fsRoot) return null;
    current = parent;
  }
  return null;
}

function isHubShape(v: unknown): v is HubConfig {
  if (!v || typeof v !== "object") return false;
  const o = v as Record<string, unknown>;
  if (o["version"] !== 1) return false;
  if (typeof o["created_at"] !== "string") return false;
  if (typeof o["updated_at"] !== "string") return false;
  if (!Array.isArray(o["projects"])) return false;
  for (const p of o["projects"] as unknown[]) {
    if (!p || typeof p !== "object") return false;
    const entry = p as Record<string, unknown>;
    if (typeof entry["ws_slug"] !== "string") return false;
    if (typeof entry["proj_slug"] !== "string") return false;
    if (typeof entry["ws_id"] !== "string") return false;
    if (typeof entry["proj_id"] !== "string") return false;
    if (typeof entry["path"] !== "string") return false;
  }
  if ("active" in o) {
    const a = o["active"];
    if (a !== null && a !== undefined) {
      if (typeof a !== "object") return false;
      const active = a as Record<string, unknown>;
      if (typeof active["ws_slug"] !== "string") return false;
      if (typeof active["proj_slug"] !== "string") return false;
    }
  }
  return true;
}

function normalizeHubConfig(raw: HubConfig): HubConfig {
  const rawActive = (raw as { active?: HubActiveProject | null }).active;
  const active: HubActiveProject | null =
    rawActive && typeof rawActive === "object"
      ? { ws_slug: rawActive.ws_slug, proj_slug: rawActive.proj_slug }
      : null;
  return {
    version: raw.version,
    created_at: raw.created_at,
    updated_at: raw.updated_at,
    projects: raw.projects,
    active,
  };
}

/**
 * Read + shape-check the hub config. Returns `null` when absent or
 * malformed — the MCP tool handlers decide how to surface the error.
 */
export async function readHub(
  hubRoot: string,
  hubFile: string = HUB_FILE,
): Promise<HubConfig | null> {
  const path = join(hubRoot, hubFile);
  let raw: string;
  try {
    raw = await readFile(path, "utf8");
  } catch {
    return null;
  }
  try {
    const parsed = JSON.parse(raw) as unknown;
    return isHubShape(parsed) ? normalizeHubConfig(parsed) : null;
  } catch {
    return null;
  }
}

export interface ResolvedProject {
  ws_id: string;
  proj_id: string;
  path: string;
  absolute_path: string;
}

/**
 * Lookup `(ws_slug, proj_slug)` no hub. Retorna `null` se o project não
 * está registrado.
 */
export async function resolveProjectFromHub(
  hubRoot: string,
  ws_slug: string,
  proj_slug: string,
  hubFile: string = HUB_FILE,
): Promise<ResolvedProject | null> {
  const config = await readHub(hubRoot, hubFile);
  if (!config) return null;
  const entry = config.projects.find(
    (p) => p.ws_slug === ws_slug && p.proj_slug === proj_slug,
  );
  if (!entry) return null;
  return {
    ws_id: entry.ws_id,
    proj_id: entry.proj_id,
    path: entry.path,
    absolute_path: join(hubRoot, entry.path),
  };
}

// ---------------------------------------------------------------------------
// Active project (Rodada 22N)
// ---------------------------------------------------------------------------

export interface ResolvedActiveProject {
  ws_slug: string;
  proj_slug: string;
  ws_id: string;
  proj_id: string;
  path: string;
  absolute_path: string;
}

/**
 * Resolve o project ativo do hub. Retorna `null` quando:
 *  - Hub config inacessível ou inválido.
 *  - Campo `active` ausente / `null`.
 *  - Pair em `active` não bate com nenhuma entry em `projects[]`
 *    (project removido do hub mas o ponteiro ficou stale).
 */
export async function getActiveProject(
  hubRoot: string,
  hubFile: string = HUB_FILE,
): Promise<ResolvedActiveProject | null> {
  const config = await readHub(hubRoot, hubFile);
  if (!config) return null;
  if (!config.active) return null;
  const { ws_slug, proj_slug } = config.active;
  const entry = config.projects.find(
    (p) => p.ws_slug === ws_slug && p.proj_slug === proj_slug,
  );
  if (!entry) return null;
  return {
    ws_slug: entry.ws_slug,
    proj_slug: entry.proj_slug,
    ws_id: entry.ws_id,
    proj_id: entry.proj_id,
    path: entry.path,
    absolute_path: join(hubRoot, entry.path),
  };
}

/**
 * Define o project ativo do hub. Valida materialização contra
 * `projects[]`; se ausente, lança `ProjectNotMaterializedError`. Persiste
 * imediatamente, bumpa `updated_at`.
 */
export async function setActiveProject(
  hubRoot: string,
  ws_slug: string,
  proj_slug: string,
  hubFile: string = HUB_FILE,
): Promise<HubConfig> {
  if (!isAbsolute(hubRoot)) {
    throw new Error(`setActiveProject requer caminho absoluto, recebi: ${hubRoot}`);
  }
  const current = await readHub(hubRoot, hubFile);
  if (!current) {
    throw new Error(
      `Hub config inválido em ${hubRoot}. Use a ferramenta \`materialize_project\` primeiro.`,
    );
  }
  const exists = current.projects.some(
    (p) => p.ws_slug === ws_slug && p.proj_slug === proj_slug,
  );
  if (!exists) {
    throw new ProjectNotMaterializedError(ws_slug, proj_slug);
  }
  const next: HubConfig = {
    ...current,
    updated_at: new Date().toISOString(),
    active: { ws_slug, proj_slug },
  };
  const path = join(hubRoot, hubFile);
  await writeFile(path, JSON.stringify(next, null, 2) + "\n", "utf8");
  return next;
}

export async function upsertHubProject(
  hubRoot: string,
  entry: HubProjectEntry,
  hubFile: string = HUB_FILE,
): Promise<HubConfig> {
  const now = new Date().toISOString();
  const current = (await readHub(hubRoot, hubFile)) ?? {
    version: 1 as const,
    created_at: now,
    updated_at: now,
    projects: [],
    active: null,
  };
  const projects = current.projects.filter(
    (project) =>
      !(project.ws_slug === entry.ws_slug && project.proj_slug === entry.proj_slug),
  );
  projects.push(entry);
  projects.sort((a, b) =>
    `${a.ws_slug}/${a.proj_slug}`.localeCompare(`${b.ws_slug}/${b.proj_slug}`),
  );
  const next: HubConfig = { ...current, updated_at: now, projects };
  await mkdir(hubRoot, { recursive: true });
  const destination = join(hubRoot, hubFile);
  const temporary = `${destination}.${process.pid}.${randomUUID()}.tmp`;
  await writeFile(temporary, JSON.stringify(next, null, 2) + "\n", "utf8");
  await rename(temporary, destination);
  return next;
}
