import { Document, HeadingLevel, Packer, Paragraph, TextRun, UnderlineType } from "docx";
import { unzipSync } from "fflate";

import type { RedlineDocument, RedlineSegment } from "./contracts.js";
import { normalizeOoxmlEntries } from "./deterministic-zip.js";
import { parseSeoPlan } from "./render-xlsx.js";

const DEFAULT_CREATED_AT = "1980-01-01T00:00:00.000Z";

function normalizeDocxMetadata(bytes: Uint8Array, createdAt: string): Buffer {
  const entries = unzipSync(bytes);
  const core = entries["docProps/core.xml"];
  if (!core) throw new Error("invalid_ooxml_zip");
  const timestamp = new Date(createdAt).toISOString();
  const xml = new TextDecoder()
    .decode(core)
    .replace(
      /<dcterms:(created|modified)([^>]*)>[^<]*<\/dcterms:\1>/gu,
      (_match, name, attrs) => `<dcterms:${name}${attrs}>${timestamp}</dcterms:${name}>`,
    );
  entries["docProps/core.xml"] = new TextEncoder().encode(xml);
  return normalizeOoxmlEntries(entries);
}

function changedRun(segment: Exclude<RedlineSegment, { kind: "keep" }>): TextRun {
  return new TextRun({
    text: segment.text,
    ...(segment.kind === "insert"
      ? { highlight: "yellow", underline: { type: UnderlineType.SINGLE } }
      : { strike: true, color: "C00000" }),
  });
}

function annotationRun(segment: Exclude<RedlineSegment, { kind: "keep" }>): TextRun {
  return new TextRun({
    text: ` [${segment.reason} · ${segment.priority}]`,
    italics: true,
  });
}

function redlineRuns(segments: readonly RedlineSegment[]): TextRun[] {
  const runs: TextRun[] = [];
  for (let index = 0; index < segments.length; index += 1) {
    const segment = segments[index]!;
    if (segment.kind === "keep") {
      runs.push(new TextRun(segment.text));
      continue;
    }
    const next = segments[index + 1];
    if (
      segment.kind === "delete" &&
      next?.kind === "insert" &&
      next.reason === segment.reason &&
      next.priority === segment.priority
    ) {
      runs.push(changedRun(segment), changedRun(next), annotationRun(segment));
      index += 1;
      continue;
    }
    runs.push(changedRun(segment), annotationRun(segment));
  }
  return runs;
}

function paragraphForBlock(block: RedlineDocument["blocks"][number]): Paragraph {
  return new Paragraph({
    ...(block.kind === "heading"
      ? {
          heading: {
            1: HeadingLevel.HEADING_1,
            2: HeadingLevel.HEADING_2,
            3: HeadingLevel.HEADING_3,
          }[block.level],
        }
      : {}),
    children: redlineRuns(block.segments),
  });
}

export async function renderRedlineDocx(
  doc: RedlineDocument,
  createdAt = DEFAULT_CREATED_AT,
): Promise<Buffer> {
  const document = new Document({
    creator: "Conversion",
    lastModifiedBy: "Conversion",
    sections: [{ children: doc.blocks.map(paragraphForBlock) }],
  });
  return normalizeDocxMetadata(await Packer.toBuffer(document), createdAt);
}

const CLIENT_SECTION_SPECS = [
  { key: "h1", heading: "H1", level: 1 },
  { key: "meta title", heading: "Meta title", level: 2 },
  { key: "meta description", heading: "Meta description", level: 2 },
  { key: "canonical", heading: "Canonical", level: 2 },
  { key: "recomendações", heading: "Recomendações", level: 2 },
] as const;
type ClientSectionKey = (typeof CLIENT_SECTION_SPECS)[number]["key"];

interface ClientSection {
  key: ClientSectionKey;
  lines: string[];
}

function invalidClientDocument(): never {
  throw new Error("invalid_client_seo_document");
}

function clientSections(markdownBody: string): Map<ClientSectionKey, ClientSection> {
  const sections = new Map<ClientSectionKey, ClientSection>();
  let active: ClientSection | undefined;
  for (const line of markdownBody.replace(/\r\n?/gu, "\n").split("\n")) {
    const heading = /^(#{1,3})\s+(.+)$/u.exec(line);
    if (heading) {
      const key = heading[2]!.trim().toLocaleLowerCase("pt-BR") as ClientSectionKey;
      const spec = CLIENT_SECTION_SPECS.find((candidate) => candidate.key === key);
      active = undefined;
      if (spec) {
        if (heading[1]!.length !== spec.level || sections.has(spec.key)) invalidClientDocument();
        active = { key: spec.key, lines: [] };
        sections.set(spec.key, active);
      }
      continue;
    }
    active?.lines.push(line);
  }
  if (sections.size !== CLIENT_SECTION_SPECS.length) invalidClientDocument();
  return sections;
}

function scalarValue(section: ClientSection): string {
  const content = section.lines.filter((line) => line.trim() !== "");
  if (content.length !== 1) invalidClientDocument();
  const value = content[0]!.trim();
  if (section.key === "canonical") {
    try {
      const url = new URL(value);
      if (url.protocol !== "http:" && url.protocol !== "https:") invalidClientDocument();
    } catch {
      invalidClientDocument();
    }
  }
  return value;
}

function recommendationRows(section: ClientSection): ReturnType<typeof parseSeoPlan> {
  const content = section.lines.filter((line) => line.trim() !== "");
  if (content.length < 3 || content.some((line) => !line.trim().startsWith("|"))) {
    invalidClientDocument();
  }
  try {
    return parseSeoPlan(content.join("\n"));
  } catch {
    invalidClientDocument();
  }
}

function seoParagraphs(markdownBody: string): Paragraph[] {
  const paragraphs: Paragraph[] = [];
  const sections = clientSections(markdownBody);
  for (const spec of CLIENT_SECTION_SPECS) {
    const section = sections.get(spec.key)!;
    paragraphs.push(
      new Paragraph({
        heading: spec.level === 1 ? HeadingLevel.HEADING_1 : HeadingLevel.HEADING_2,
        children: [new TextRun(spec.heading)],
      }),
    );
    if (section.key === "recomendações") {
      const rows = recommendationRows(section);
      paragraphs.push(
        new Paragraph({
          children: [new TextRun("ID | Prioridade | Elemento | Recomendação | Motivo | Status")],
        }),
      );
      for (const row of rows) {
        paragraphs.push(
          new Paragraph({
            children: [
              new TextRun(
                [
                  row.id,
                  row.prioridade,
                  row.elemento,
                  row.recomendacao,
                  row.motivo,
                  row.status,
                ].join(" | "),
              ),
            ],
          }),
        );
      }
      continue;
    }
    paragraphs.push(new Paragraph({ children: [new TextRun(scalarValue(section))] }));
  }
  return paragraphs;
}

export async function renderSeoClientDocx(
  markdownBody: string,
  createdAt = DEFAULT_CREATED_AT,
): Promise<Buffer> {
  const document = new Document({
    creator: "Conversion",
    lastModifiedBy: "Conversion",
    sections: [{ children: seoParagraphs(markdownBody) }],
  });
  return normalizeDocxMetadata(await Packer.toBuffer(document), createdAt);
}
