import { BRAIN_VAULT_SEEDS } from "../lib/brain-vault.js";
import { requireSearchHubBackendUrl } from "../lib/config.js";
import {
  ProjectNotMaterializedError,
  SEARCHHUB_HUB_FILE,
  findHubRoot,
  getActiveProject,
  setActiveProject,
} from "../lib/hub.js";
import { resolveProjectScope } from "../lib/project-scope.js";
import { runProjectSave } from "../lib/project-save.js";
import type { GetActiveProjectInput, GetActiveProjectOutput } from "./get-active-project.js";
import type { EnsureBrainVaultInput, EnsureBrainVaultOutput } from "./ensure-brain-vault.js";
import type { ProjectSaveAndUrlInput, ProjectSaveAndUrlOutput } from "./project-save-and-url.js";
import {
  runPackageOnPageOptimization,
  type PackageOnPageOptimizationInput,
  type PackageOnPageOptimizationOutput,
} from "./package-on-page-optimization.js";
import {
  runProjectSaveBatch,
  type ProjectSaveBatchInput,
  type ProjectSaveBatchOutput,
} from "./project-save-batch.js";
import { runReadBrain } from "./read-brain.js";
import type { SetActiveProjectInput, SetActiveProjectOutput } from "./set-active-project.js";

function target() {
  return {
    backendUrl: requireSearchHubBackendUrl(),
    hubFile: SEARCHHUB_HUB_FILE,
    materializeTool: "searchhub_materialize_project",
    backendTarget: "searchhub" as const,
  };
}

export async function runSearchHubProjectSaveAndUrl(
  input: ProjectSaveAndUrlInput,
  cwd = process.cwd(),
): Promise<ProjectSaveAndUrlOutput> {
  let backendUrl: string;
  try {
    backendUrl = requireSearchHubBackendUrl();
  } catch (error) {
    return { ok: false, error: "bad_input", hint: String(error) };
  }
  const scope = await resolveProjectScope(
    input,
    cwd,
    SEARCHHUB_HUB_FILE,
    "searchhub_materialize_project",
  );
  if (!scope.ok) return scope;
  return runProjectSave(
    { path: input.path, content: input.content, message: input.message },
    {
      wsId: scope.ws_id,
      projId: scope.proj_id,
      wsSlug: input.ws_slug,
      projSlug: input.proj_slug,
      backendTarget: "searchhub",
      absoluteProjectRoot: scope.project_root,
      backendUrl,
    },
  );
}

export async function runSearchHubProjectSaveBatch(
  input: ProjectSaveBatchInput,
  cwd = process.cwd(),
): Promise<ProjectSaveBatchOutput> {
  try {
    return await runProjectSaveBatch(input, cwd, target());
  } catch (error) {
    return { ok: false, error: "bad_input", hint: String(error) };
  }
}

export async function runSearchHubPackageOnPageOptimization(
  input: PackageOnPageOptimizationInput,
  cwd = process.cwd(),
): Promise<PackageOnPageOptimizationOutput> {
  return runPackageOnPageOptimization(input, cwd, {
    backendUrl: requireSearchHubBackendUrl,
    hubFile: SEARCHHUB_HUB_FILE,
    materializeTool: "searchhub_materialize_project",
    backendTarget: "searchhub",
  });
}

export async function runSearchHubEnsureBrainVault(
  input: EnsureBrainVaultInput,
  cwd = process.cwd(),
): Promise<EnsureBrainVaultOutput> {
  if (!input || typeof input.ws_slug !== "string" || typeof input.proj_slug !== "string") {
    return { ok: false, error: "bad_input", hint: "ws_slug and proj_slug are required." };
  }
  let selectedTarget: ReturnType<typeof target>;
  try {
    selectedTarget = target();
  } catch (error) {
    return { ok: false, error: "bad_input", hint: String(error) };
  }
  const scope = { ws_slug: input.ws_slug, proj_slug: input.proj_slug };
  const brain = await runReadBrain(scope, cwd, selectedTarget);
  if (!brain.ok) return brain;
  const present = new Set(brain.items.map((item) => item.type));
  const missing = BRAIN_VAULT_SEEDS.filter((seed) => !present.has(seed.type));
  const already_present = BRAIN_VAULT_SEEDS.filter((seed) => present.has(seed.type)).map(
    (seed) => seed.type,
  );
  if (missing.length === 0) return { ok: true, seeded: [], already_present };
  const updatedAt = new Date().toISOString();
  const saved = await runProjectSaveBatch(
    {
      ...scope,
      files: missing.map((seed) => ({ path: seed.path, content: seed.build(updatedAt) })),
      message: `chore(brain): semeia ${missing.map((seed) => seed.path).join(", ")}`,
    },
    cwd,
    selectedTarget,
  );
  if (!saved.ok) return { ok: false, error: saved.error, hint: saved.hint };
  return {
    ok: true,
    seeded: missing.map((seed) => seed.type),
    already_present,
    commit_id: saved.commit_id,
    url: saved.url,
  };
}

export async function runSearchHubGetActiveProject(
  _input?: GetActiveProjectInput,
  cwd = process.cwd(),
): Promise<GetActiveProjectOutput> {
  const hubRoot = await findHubRoot(cwd, SEARCHHUB_HUB_FILE);
  if (!hubRoot) return { ok: true, active: null, hub_root: null };
  const active = await getActiveProject(hubRoot, SEARCHHUB_HUB_FILE);
  if (!active) return { ok: true, active: null, hub_root: hubRoot };
  return {
    ok: true,
    active: {
      ws_slug: active.ws_slug,
      proj_slug: active.proj_slug,
      ws_id: active.ws_id,
      proj_id: active.proj_id,
    },
    hub_root: hubRoot,
  };
}

export async function runSearchHubSetActiveProject(
  input: SetActiveProjectInput,
  cwd = process.cwd(),
): Promise<SetActiveProjectOutput> {
  if (!input || typeof input.ws_slug !== "string" || typeof input.proj_slug !== "string") {
    return { ok: false, error: "bad_input", hint: "ws_slug and proj_slug are required." };
  }
  const hubRoot = await findHubRoot(cwd, SEARCHHUB_HUB_FILE);
  if (!hubRoot) {
    return {
      ok: false,
      error: "not_in_hub",
      hint: `Não encontrei ${SEARCHHUB_HUB_FILE}. Use searchhub_materialize_project primeiro.`,
    };
  }
  try {
    await setActiveProject(hubRoot, input.ws_slug, input.proj_slug, SEARCHHUB_HUB_FILE);
    return {
      ok: true,
      active: { ws_slug: input.ws_slug, proj_slug: input.proj_slug },
      hub_root: hubRoot,
    };
  } catch (error) {
    if (error instanceof ProjectNotMaterializedError) {
      return { ok: false, error: "project_not_in_hub", hint: error.message };
    }
    return { ok: false, error: "unknown_error", hint: String(error) };
  }
}
