/**
 * Tool: `ensure_brain_vault`.
 *
 * Idempotently bootstraps the seeded brain files: the proof vault
 * (`brain/provas.md` + `brain/fontes.md`, the "cofre"/"tesouro") plus the
 * products/services catalog (`brain/produtos.md`). The orchestrator calls this
 * once when a project becomes active so the AI always starts work with them
 * wired — `read_brain` then returns these files and a human curates them via
 * the web editor.
 *
 * Mechanics:
 *   1. Read the backend brain (source of truth) to see which vault files exist.
 *   2. Commit ONLY the missing ones via `project_save_batch` (atomic).
 *   3. If both already exist, no commit happens (true no-op).
 *
 * Seeding NEVER enables fact-checking — the mode stays whatever the project
 * configured (`off` by default). The vault files just need to exist.
 *
 * Thin orchestration over `read_brain` + `project_save_batch`, so it inherits
 * their auth, hub-resolution and conflict handling for free.
 */
import { BRAIN_VAULT_SEEDS, type BrainVaultType } from "../lib/brain-vault.js";
import { PROJECT_SCOPE_SCHEMA_FRAGMENT } from "../lib/project-scope.js";
import { runProjectSaveBatch } from "./project-save-batch.js";
import { runReadBrain } from "./read-brain.js";

export interface EnsureBrainVaultInput {
  ws_slug: string;
  proj_slug: string;
}

export type EnsureBrainVaultError =
  | "bad_input"
  | "not_authenticated"
  | "session_expired"
  | "rate_limited"
  | "not_in_hub"
  | "project_not_in_hub"
  | "invalid_manifest"
  | "invalid_path"
  | "binary_not_supported"
  | "conflict"
  | "backend_error"
  | "network_error"
  | "unknown_error";

export type EnsureBrainVaultOutput =
  | {
      ok: true;
      /** Vault types committed in this call (empty when already present). */
      seeded: BrainVaultType[];
      /** Vault types that already existed on the backend. */
      already_present: BrainVaultType[];
      commit_id?: string;
      url?: string;
    }
  | {
      ok: false;
      error: EnsureBrainVaultError;
      hint?: string;
      retry_after_sec?: number;
    };

export const ENSURE_BRAIN_VAULT_INPUT_SCHEMA = {
  type: "object",
  properties: {
    ...PROJECT_SCOPE_SCHEMA_FRAGMENT,
  },
  required: ["ws_slug", "proj_slug"],
  additionalProperties: false,
} as const;

export async function runEnsureBrainVault(
  input: EnsureBrainVaultInput,
  cwd: string = process.cwd(),
): Promise<EnsureBrainVaultOutput> {
  if (!input || typeof input.ws_slug !== "string" || typeof input.proj_slug !== "string") {
    return {
      ok: false,
      error: "bad_input",
      hint: "ws_slug and proj_slug are required.",
    };
  }

  const scope = { ws_slug: input.ws_slug, proj_slug: input.proj_slug };

  // 1. Backend is the source of truth for which brain files exist.
  const brain = await runReadBrain(scope, cwd);
  if (!brain.ok) {
    return {
      ok: false,
      error: brain.error,
      hint: brain.hint,
      ...(brain.retry_after_sec !== undefined ? { retry_after_sec: brain.retry_after_sec } : {}),
    };
  }

  const presentTypes = new Set(brain.items.map((item) => item.type));
  const missing = BRAIN_VAULT_SEEDS.filter((seed) => !presentTypes.has(seed.type));
  const alreadyPresent = BRAIN_VAULT_SEEDS.filter((seed) => presentTypes.has(seed.type)).map(
    (seed) => seed.type,
  );

  // 2. Idempotent: nothing missing → no commit.
  if (missing.length === 0) {
    return { ok: true, seeded: [], already_present: alreadyPresent };
  }

  // 3. Seed only the missing files in one atomic commit.
  const updatedAtIso = new Date().toISOString();
  const files = missing.map((seed) => ({
    path: seed.path,
    content: seed.build(updatedAtIso),
  }));
  const message =
    missing.length === BRAIN_VAULT_SEEDS.length
      ? `chore(brain): semeia brain (${missing.map((seed) => seed.path).join(", ")})`
      : `chore(brain): semeia ${missing.map((seed) => seed.path).join(", ")}`;

  const saved = await runProjectSaveBatch({ ...scope, files, message }, cwd);
  if (!saved.ok) {
    return { ok: false, error: saved.error, hint: saved.hint };
  }

  return {
    ok: true,
    seeded: missing.map((seed) => seed.type),
    already_present: alreadyPresent,
    commit_id: saved.commit_id,
    url: saved.url,
  };
}
