interface SyncTarget {
  backendUrl: string;
  hubFile: string;
  projectPrefix: string | null;
  syncDir: string;
  logFile: string;
}

const LEGACY_TARGET: SyncTarget = {
  backendUrl: BACKEND_URL,
  hubFile: HUB_FILE,
  projectPrefix: null,
  syncDir: "sync",
  logFile: "sync-monitor.log",
};

function searchHubTarget(): SyncTarget {
  return {
    backendUrl: requireSearchHubBackendUrl(),
    hubFile: SEARCHHUB_HUB_FILE,
    projectPrefix: "searchhub",
    syncDir: "sync",
    logFile: "searchhub-sync-monitor.log",
  };
}

interface WorkspaceItem {
  id: string;
  slug: string;
  name: string;
  role?: string;
}

interface ProjectItem {
  id: string;
  slug: string;
  name: string;
}

interface ResolvedLocalProject {
  ws_slug: string;
  proj_slug: string;
  ws_id: string;
  proj_id: string;
  absolute_path: string;
  hub_root: string;
}

export interface ProjectScopeOptionalInput {
  ws_slug?: string;
  proj_slug?: string;
}

export interface MaterializeProjectInput {
  ws_slug: string;
  proj_slug: string;
  hub_root?: string;
  set_active?: boolean;
}

export interface SyncDoctorInput {
  include_logs?: boolean;
  include_remote_config?: boolean;
  lines?: number;
}

export const SYNC_STATUS_INPUT_SCHEMA = {
  type: "object",
  properties: {
    ws_slug: { type: "string" },
    proj_slug: { type: "string" },
  },
  additionalProperties: false,
} as const;

export const SYNC_PAUSE_INPUT_SCHEMA = {
  ...SYNC_STATUS_INPUT_SCHEMA,
  properties: {
    ...SYNC_STATUS_INPUT_SCHEMA.properties,
    reason: { type: "string" },
  },
} as const;

export const SYNC_RESUME_INPUT_SCHEMA = SYNC_STATUS_INPUT_SCHEMA;

export const SYNC_REPAIR_INPUT_SCHEMA = {
  type: "object",
  properties: {
    ws_slug: { type: "string" },
    proj_slug: { type: "string" },
    action: {
      type: "string",
      enum: ["status", "resume"],
      description: "Use 'resume' after resolving conflict snapshots locally.",
    },
  },
  additionalProperties: false,
} as const;

export const SYNC_DOCTOR_INPUT_SCHEMA = {
  type: "object",
  properties: {
    include_logs: { type: "boolean" },
    include_remote_config: { type: "boolean" },
    lines: { type: "number", minimum: 1, maximum: 200 },
  },
  additionalProperties: false,
} as const;

export const LIST_WORKSPACES_PROJECTS_INPUT_SCHEMA = {
  type: "object",
  properties: {},
  additionalProperties: false,
} as const;

export const MATERIALIZE_PROJECT_INPUT_SCHEMA = {
  type: "object",
  properties: {
    ws_slug: { type: "string", minLength: 1 },
    proj_slug: { type: "string", minLength: 1 },
    hub_root: {
      type: "string",
      description: "Optional absolute hub root. Defaults to current hub or cwd.",
    },
    set_active: { type: "boolean" },
  },
  required: ["ws_slug", "proj_slug"],
  additionalProperties: false,
} as const;

export async function runListWorkspacesProjects(target: SyncTarget = LEGACY_TARGET): Promise<
  | {
      ok: true;
      workspaces: Array<WorkspaceItem & { projects: ProjectItem[] }>;
    }
  | SyncToolError
> {
  try {
    const wsBody = await authenticatedJsonAt<{ workspaces: WorkspaceItem[] }>(
      target.backendUrl,
      "/api/v1/user/workspaces",
      { method: "GET" },
    );
    const workspaces = [];
    for (const ws of wsBody.workspaces) {
      const projectsBody = await authenticatedJsonAt<{ projects: ProjectItem[] }>(
        target.backendUrl,
        `/api/v1/ws/${ws.id}/projects`,
        { method: "GET" },
      );
      workspaces.push({ ...ws, projects: projectsBody.projects });
    }
    return { ok: true, workspaces };
  } catch (err) {
    return mapSyncError(err);
  }
}

export async function runSyncStatus(
  input: ProjectScopeOptionalInput,
  cwd = process.cwd(),
  target: SyncTarget = LEGACY_TARGET,
): Promise<
  | {
      ok: true;
      project: ResolvedLocalProject | null;
      status: ProjectSyncStatus | null;
    }
  | SyncToolError
> {
  const resolved = await resolveLocalProject(input, cwd, target);
  if (!resolved.ok) return resolved;
  if (!resolved.project) return { ok: true, project: null, status: null };
  return {
    ok: true,
    project: resolved.project,
    status: await readSyncStatus(resolved.project.absolute_path),
  };
}

export async function runSyncPause(
  input: ProjectScopeOptionalInput & { reason?: string },
  cwd = process.cwd(),
  target: SyncTarget = LEGACY_TARGET,
): Promise<{ ok: true; status: ProjectSyncStatus } | SyncToolError> {
  const resolved = await resolveLocalProject(input, cwd, target);
  if (!resolved.ok) return resolved;
  if (!resolved.project) {
    return { ok: false, error: "not_in_hub", hint: "No active project found." };
  }
  const status = await pauseSync(resolved.project.absolute_path, input.reason ?? "paused_by_user");
  return { ok: true, status };
}

export async function runSyncResume(
  input: ProjectScopeOptionalInput,
  cwd = process.cwd(),
  target: SyncTarget = LEGACY_TARGET,
): Promise<{ ok: true; status: ProjectSyncStatus } | SyncToolError> {
  const resolved = await resolveLocalProject(input, cwd, target);
  if (!resolved.ok) return resolved;
  if (!resolved.project) {
    return { ok: false, error: "not_in_hub", hint: "No active project found." };
  }
  const status = await resumeSync(resolved.project.absolute_path);
  return { ok: true, status };
}

export async function runSyncRepair(
  input: ProjectScopeOptionalInput & { action?: "status" | "resume" },
  cwd = process.cwd(),
  target: SyncTarget = LEGACY_TARGET,
): Promise<
  { ok: true; action: "status" | "resume"; status: ProjectSyncStatus | null } | SyncToolError
> {
  if (input.action === "resume") {
    const resumed = await runSyncResume(input, cwd, target);
    if (!resumed.ok) return resumed;
    return { ok: true, action: "resume", status: resumed.status };
  }
  const status = await runSyncStatus(input, cwd, target);
  if (!status.ok) return status;
  return { ok: true, action: "status", status: status.status };
}

export async function runSyncDoctor(
  input: SyncDoctorInput = {},
  cwd = process.cwd(),
  target: SyncTarget = LEGACY_TARGET,
): Promise<{ ok: true } & SyncDoctorReport> {
  const projectDir = resolve(process.env["CLAUDE_PROJECT_DIR"] ?? cwd);
  const hubRoot = await findHubRoot(projectDir, target.hubFile);
  const [plugin, auth] = await Promise.all([inspectPluginVersion(), getToken().catch(() => null)]);
  const hub = hubRoot ? await readHub(hubRoot, target.hubFile) : null;
  const activeProject = hub?.active ? `${hub.active.ws_slug}/${hub.active.proj_slug}` : null;
  const selected =
    hubRoot && hub
      ? selectDiagnosticProjects(hubRoot, hub.projects, activeProject, projectDir)
      : [];
  const projects = await Promise.all(
    selected.map(async (project) => {
      const [status, manifestExists, lock] = await Promise.all([
        readSyncStatus(project.absolute_path),
        fileExists(join(project.absolute_path, ".conversion", "manifest.json")),
        readJsonFile<Record<string, unknown>>(
          join(project.absolute_path, ".conversion", target.syncDir, "project.lock", "owner.json"),
        ),
      ]);
      return {
        key: project.key,
        path: project.absolute_path,
        manifest_exists: manifestExists,
        lock: lock
          ? {
              pid: lock["pid"] ?? null,
              version: lock["version"] ?? null,
              heartbeat_at: lock["heartbeatAt"] ?? null,
            }
          : null,
        status,
      };
    }),
  );
  const legacyHubLock =
    hubRoot &&
    (await fileExists(join(hubRoot, ".conversion", target.syncDir, "project.lock", "owner.json")))
      ? await readJsonFile<Record<string, unknown>>(
          join(hubRoot, ".conversion", target.syncDir, "project.lock", "owner.json"),
        )
      : null;
  const includeRemote = input.include_remote_config !== false;
  const remoteConfig =
    includeRemote && auth ? await fetchSyncConfig(auth.token, target.backendUrl) : null;
  const warnings = buildDoctorWarnings({
    hubRoot,
    projectCount: hub?.projects.length ?? 0,
    selectedCount: selected.length,
    plugin,
    legacyHubLock,
    remoteConfig,
    projects,
  });

  return {
    ok: true,
    cwd: projectDir,
    plugin,
    auth: {
      authenticated: auth !== null,
      email: auth?.email ?? null,
      source: auth?.source ?? null,
      expires_at: auth?.expiresAt ?? null,
    },
    hub: hubRoot
      ? {
          root: hubRoot,
          project_count: hub?.projects.length ?? 0,
          active_project: activeProject,
          selected_count: selected.length,
          selected_projects: selected.map((project) => project.key),
        }
      : null,
    remote_config: remoteConfig,
    projects,
    legacy_hub_lock: legacyHubLock,
    warnings,
    ...(input.include_logs
      ? {
          logs: await readLogLines(Math.min(Math.max(input.lines ?? 30, 1), 200), target.logFile),
        }
      : {}),
  };
}

export async function runMaterializeProject(
  input: MaterializeProjectInput,
  cwd = process.cwd(),
  target: SyncTarget = LEGACY_TARGET,
): Promise<
  | {
      ok: true;
      path: string;
      file_count: number;
      commit_id: string | null;
      tree_hash: string;
    }
  | SyncToolError
> {
  if (!input || typeof input.ws_slug !== "string" || typeof input.proj_slug !== "string") {
    return { ok: false, error: "bad_input", hint: "ws_slug and proj_slug are required." };
  }

  const listing = await runListWorkspacesProjects(target);
  if (!listing.ok) return listing;
  const workspace = listing.workspaces.find((ws) => ws.slug === input.ws_slug);
  const project = workspace?.projects.find((p) => p.slug === input.proj_slug);
  if (!workspace || !project) {
    return {
      ok: false,
      error: "backend_error",
      hint: `Project ${input.ws_slug}/${input.proj_slug} not found for this user.`,
    };
  }

  const hubRoot = input.hub_root ?? (await findHubRoot(cwd, target.hubFile)) ?? cwd;
  const projectPath = [target.projectPrefix, workspace.slug, project.slug]
    .filter(Boolean)
    .join("/");
  const absoluteProjectRoot = join(hubRoot, projectPath);

  try {
    const headBody = await authenticatedJsonAt<{
      head: {
        commitId: string;
        treeHash: string;
        treeJson: Record<string, string>;
      } | null;
    }>(target.backendUrl, `/api/v1/ws/${workspace.id}/projects/${project.id}/head`, {
      method: "GET",
    });
    const tree = headBody.head?.treeJson ?? {};
    const files: SyncManifest["files"] = {};

    for (const [path, sha] of Object.entries(tree)) {
      const reason = validateSyncPath(path);
      if (reason) {
        return { ok: false, error: "invalid_path", hint: `${path}: ${reason}` };
      }
      const blob = await authenticatedFetchAt(
        target.backendUrl,
        `/api/v1/ws/${workspace.id}/blobs/${sha}?variant=canonical-sync`,
        { method: "GET" },
      );
      const bytes = new Uint8Array(await blob.arrayBuffer());
      const targetPath = join(absoluteProjectRoot, path);
      await mkdir(dirname(targetPath), { recursive: true });
      await writeFile(targetPath, bytes);
      const mime = normalizeManifestMime(
        blob.headers.get("content-type") ?? "application/octet-stream",
      );
      if (!mime) {
        return { ok: false, error: "backend_error", hint: `${path}: invalid Content-Type` };
      }
      files[path] = {
        sha256: sha,
        size: bytes.length,
        mime,
      };
    }

    const manifest: SyncManifest & { backendTarget: "legacy" | "searchhub" } = {
      backendTarget: target === LEGACY_TARGET ? "legacy" : "searchhub",
      projectId: project.id,
      workspaceId: workspace.id,
      workspaceSlug: workspace.slug,
      projectSlug: project.slug,
      treeHash: headBody.head?.treeHash ?? "0".repeat(64),
      commitId: headBody.head?.commitId ?? null,
      updatedAt: new Date().toISOString(),
      files,
    };
    await writeManifest(absoluteProjectRoot, manifest);
    await upsertHubProject(
      hubRoot,
      {
        ws_slug: workspace.slug,
        proj_slug: project.slug,
        ws_id: workspace.id,
        proj_id: project.id,
        path: projectPath,
      },
      target.hubFile,
    );
    if (input.set_active) {
      await setActiveProject(hubRoot, workspace.slug, project.slug, target.hubFile);
    }

    return {
      ok: true,
      path: absoluteProjectRoot,
      file_count: Object.keys(files).length,
      commit_id: headBody.head?.commitId ?? null,
      tree_hash: headBody.head?.treeHash ?? "0".repeat(64),
    };
  } catch (err) {
    return mapSyncError(err);
  }
}

interface SyncDoctorReport {
  cwd: string;
  plugin: {
    root: string;
    installed_version: string | null;
    expected_version: string | null;
    stale: boolean;
  };
  auth: {
    authenticated: boolean;
    email: string | null;
    source: string | null;
    expires_at: string | null;
  };
  hub: {
    root: string;
    project_count: number;
    active_project: string | null;
    selected_count: number;
    selected_projects: string[];
  } | null;
  remote_config: { ok: boolean; status: number | null; body?: unknown; error?: string } | null;
  projects: Array<{
    key: string;
    path: string;
    manifest_exists: boolean;
    lock: { pid: unknown; version: unknown; heartbeat_at: unknown } | null;
    status: ProjectSyncStatus | null;
  }>;
  legacy_hub_lock: Record<string, unknown> | null;
  warnings: string[];
  logs?: string[];
}

type SyncToolError = {
  ok: false;
  error:
    | "bad_input"
    | "not_authenticated"
    | "session_expired"
    | "not_in_hub"
    | "project_not_in_hub"
    | "invalid_path"
    | "backend_error"
    | "network_error";
  hint?: string;
};

interface DiagnosticProject extends HubProjectEntry {
  key: string;
  absolute_path: string;
}

function runtimePluginRoot(): string {
  const explicit = process.env["CLAUDE_PLUGIN_ROOT"];
  if (explicit) return resolve(explicit);

  const here = dirname(fileURLToPath(import.meta.url));
  const candidates = [join(here, "..", ".."), join(here, "..", "..", "..")];
  return resolve(
    candidates.find((candidate) => existsSync(join(candidate, ".claude-plugin", "plugin.json"))) ??
      candidates[0]!,
  );
}

function conversionHome(): string {
  return join(homedir(), ".conversion");
}

async function fileExists(path: string): Promise<boolean> {
  try {
    await stat(path);
    return true;
  } catch {
    return false;
  }
}

async function readJsonFile<T>(path: string): Promise<T | null> {
  try {
    return JSON.parse(await readFile(path, "utf8")) as T;
  } catch {
    return null;
  }
}

function diagnosticPluginPath(): string {
  return join(runtimePluginRoot(), ".claude-plugin", "plugin.json");
}

async function inspectPluginVersion(): Promise<SyncDoctorReport["plugin"]> {
  const root = runtimePluginRoot();
  const installed = await readJsonFile<{ version?: unknown }>(diagnosticPluginPath());
  const expected = await findMarketplacePluginVersion();
  const installedVersion = typeof installed?.version === "string" ? installed.version : null;
  return {
    root,
    installed_version: installedVersion,
    expected_version: expected,
    stale: semverGreater(expected, installedVersion),
  };
}

async function findMarketplacePluginVersion(): Promise<string | null> {
  const explicitPath = process.env["CONVERSION_PLUGIN_MARKETPLACE_PATH"];
  if (explicitPath) return readMarketplacePluginVersion(explicitPath);

  let entries: string[];
  const marketplaceRoot = join(homedir(), ".claude", "plugins", "marketplaces");
  try {
    entries = await readdir(marketplaceRoot);
  } catch {
    return null;
  }
  for (const entry of entries) {
    const version = await readMarketplacePluginVersion(
      join(marketplaceRoot, entry, ".claude-plugin", "marketplace.json"),
    );
    if (version) return version;
  }
  return null;
}

async function readMarketplacePluginVersion(path: string): Promise<string | null> {
  const parsed = await readJsonFile<{
    plugins?: Array<{ name?: unknown; version?: unknown }>;
  }>(path);
  const entry = parsed?.plugins?.find((plugin) => plugin.name === "conversion-agent");
  return typeof entry?.version === "string" ? entry.version : null;
}

function parseSemver(value: string | null): [number, number, number] | null {
  const match = /^(\d+)\.(\d+)\.(\d+)(?:[-+].*)?$/u.exec(value ?? "");
  if (!match) return null;
  return [
    Number.parseInt(match[1]!, 10),
    Number.parseInt(match[2]!, 10),
    Number.parseInt(match[3]!, 10),
  ];
}

function semverGreater(a: string | null, b: string | null): boolean {
  const left = parseSemver(a);
  const right = parseSemver(b);
  if (!left || !right) return false;
  for (let index = 0; index < left.length; index += 1) {
    if (left[index]! > right[index]!) return true;
    if (left[index]! < right[index]!) return false;
  }
  return false;
}

function isWithinPath(candidate: string, parent: string): boolean {
  const rel = relative(parent, candidate);
  return rel === "" || (!rel.startsWith("..") && !isAbsolute(rel));
}

function selectDiagnosticProjects(
  hubRoot: string,
  projects: HubProjectEntry[],
  activeProject: string | null,
  projectDir: string,
): DiagnosticProject[] {
  const normalizedHub = resolve(hubRoot);
  const selected: DiagnosticProject[] = [];
  for (const project of projects) {
    const absolutePath = resolve(join(hubRoot, ...project.path.split("/")));
    const openedHub = projectDir === normalizedHub;
    const openedProject = isWithinPath(projectDir, absolutePath);
    if (!openedHub && !openedProject) continue;
    selected.push({
      ...project,
      key: `${project.ws_slug}/${project.proj_slug}`,
      absolute_path: absolutePath,
    });
  }
  selected.sort((a, b) => {
    const activeA = a.key === activeProject ? 0 : 1;
    const activeB = b.key === activeProject ? 0 : 1;
    return activeA - activeB || a.key.localeCompare(b.key);
  });
  return selected;
}

async function fetchSyncConfig(
  token: string,
  backendUrl: string,
): Promise<{ ok: boolean; status: number | null; body?: unknown; error?: string }> {
  try {
    const res = await fetch(`${backendUrl}/api/v1/sync/config`, {
      headers: {
        authorization: `Bearer ${token}`,
        accept: "application/json",
        ...backendProtectionHeaders(),
      },
    });
    return {
      ok: res.ok,
      status: res.status,
      body: await res.json().catch(() => null),
    };
  } catch (err) {
    return {
      ok: false,
      status: null,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

async function readLogLines(lines: number, logFile: string): Promise<string[]> {
  try {
    const raw = await readFile(join(conversionHome(), "logs", logFile), "utf8");
    return raw.trimEnd().split("\n").slice(-lines);
  } catch {
    return [];
  }
}

function buildDoctorWarnings(input: {
  hubRoot: string | null;
  projectCount: number;
  selectedCount: number;
  plugin: SyncDoctorReport["plugin"];
  legacyHubLock: Record<string, unknown> | null;
  remoteConfig: SyncDoctorReport["remote_config"];
  projects: SyncDoctorReport["projects"];
}): string[] {
  const warnings: string[] = [];
  if (!input.hubRoot) warnings.push("not_in_conversion_hub");
  if (input.hubRoot && input.projectCount > 0 && input.selectedCount === 0) {
    warnings.push("no_selected_project");
  }
  if (input.plugin.stale) warnings.push("stale_plugin");
  if (input.legacyHubLock) warnings.push("legacy_hub_lock_present");
  const mode = (input.remoteConfig?.body as { mode?: unknown } | null)?.mode;
  if (mode === "observe") warnings.push("remote_mode_observe");
  for (const project of input.projects) {
    if (!project.manifest_exists) warnings.push(`missing_manifest:${project.key}`);
    if (project.status?.paused) warnings.push(`paused:${project.key}`);
    if (project.status?.lastError) {
      warnings.push(`last_error:${project.key}:${project.status.lastError}`);
    }
  }
  return warnings;
}

async function resolveLocalProject(
  input: ProjectScopeOptionalInput,
  cwd: string,
  target: SyncTarget,
): Promise<{ ok: true; project: ResolvedLocalProject | null } | SyncToolError> {
  const hubRoot = await findHubRoot(cwd, target.hubFile);
  if (!hubRoot) return { ok: true, project: null };
  if (input.ws_slug && input.proj_slug) {
    const resolved = await resolveProjectFromHub(
      hubRoot,
      input.ws_slug,
      input.proj_slug,
      target.hubFile,
    );
    if (!resolved) {
      return {
        ok: false,
        error: "project_not_in_hub",
        hint: `Project ${input.ws_slug}/${input.proj_slug} is not materialized.`,
      };
    }
    return {
      ok: true,
      project: {
        ws_slug: input.ws_slug,
        proj_slug: input.proj_slug,
        ws_id: resolved.ws_id,
        proj_id: resolved.proj_id,
        absolute_path: resolved.absolute_path,
        hub_root: hubRoot,
      },
    };
  }
  const active = await getActiveProject(hubRoot, target.hubFile);
  if (!active) return { ok: true, project: null };
  return {
    ok: true,
    project: {
      ws_slug: active.ws_slug,
      proj_slug: active.proj_slug,
      ws_id: active.ws_id,
      proj_id: active.proj_id,
      absolute_path: active.absolute_path,
      hub_root: hubRoot,
    },
  };
}

function mapSyncError(err: unknown): SyncToolError {
  if (err instanceof NotAuthenticatedError) {
    return { ok: false, error: "not_authenticated", hint: err.message };
  }
  if (err instanceof SessionExpiredError) {
    return { ok: false, error: "session_expired", hint: err.message };
  }
  if (err instanceof NetworkError) {
    return { ok: false, error: "network_error", hint: err.message };
  }
  if (err instanceof BackendError) {
    return { ok: false, error: "backend_error", hint: err.message };
  }
  return {
    ok: false,
    error: "backend_error",
    hint: err instanceof Error ? err.message : String(err),
  };
}

function withSearchHubTarget<T>(
  run: (target: SyncTarget) => Promise<T>,
): Promise<T | SyncToolError> {
  try {
    return run(searchHubTarget());
  } catch (error) {
    return Promise.resolve({
      ok: false,
      error: "backend_error",
      hint: error instanceof Error ? error.message : String(error),
    });
  }
}

export function runSearchHubListWorkspacesProjects() {
  return withSearchHubTarget((target) => runListWorkspacesProjects(target));
}

