/**
 * Tool: `get_skill_context`
 *
 * Returns the rich, server-watermarked context for a Conversion skill. The
 * MCP server is a passthrough — all IP-protection logic (guardrail,
 * statistical/canary/zero-width watermarks) lives server-side (ADR-005).
 *
 * Cached in-process for 5 minutes keyed by (skill, params) so repeated
 * invocations inside one Claude Code session don't spam the backend.
 */
import type { SkillContextV1 } from "@agenciaconversion/shared";

import {
  authenticatedJson,
  BackendError,
  NetworkError,
  NotAuthenticatedError,
  RateLimitedError,
  SessionExpiredError,
  SkillNotFoundError,
} from "../lib/api.js";
import { cacheKey, TtlCache } from "../lib/cache.js";
import { CACHE_TTL_MS } from "../lib/config.js";

/** MCP-level input shape. Kept broad — server validates slug + params. */
export interface GetSkillContextInput {
  skill: string;
  params?: Record<string, string>;
}

/** Envelope returned through MCP. Success OR an error object, never both. */
export type GetSkillContextOutput =
  | { ok: true; data: SkillContextV1 }
  | { ok: false; error: string; hint?: string; retry_after_sec?: number };

export const GET_SKILL_CONTEXT_INPUT_SCHEMA = {
  type: "object",
  properties: {
    skill: {
      type: "string",
      description:
        "Slug of the skill to load. Fase 2b supports only 'briefing'.",
      pattern: "^[a-z][a-z0-9-]{0,30}[a-z0-9]$",
    },
    params: {
      type: "object",
      description:
        "Optional query-string parameters forwarded to the backend " +
        "(e.g. marca, input_hash). Values must be strings.",
      additionalProperties: { type: "string" },
    },
  },
  required: ["skill"],
  additionalProperties: false,
} as const;

const cache = new TtlCache<SkillContextV1>(CACHE_TTL_MS);

/** Exposed for tests — clears any cached contexts. */
export function __resetCache(): void {
  cache.clear();
}

function buildPath(skill: string, params?: Record<string, string>): string {
  const base = `/api/v1/skills/${encodeURIComponent(skill)}/context`;
  if (!params || Object.keys(params).length === 0) return base;
  const qs = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) {
    if (typeof v === "string" && v.length > 0) qs.set(k, v);
  }
  const query = qs.toString();
  return query ? `${base}?${query}` : base;
}

export async function runGetSkillContext(
  input: GetSkillContextInput,
): Promise<GetSkillContextOutput> {
  const skill = input.skill?.trim();
  if (!skill) {
    return { ok: false, error: "bad_input", hint: "Field 'skill' is required." };
  }

  const key = cacheKey("skill", { skill, params: input.params ?? {} });
  const cached = cache.get(key);
  if (cached) return { ok: true, data: cached };

  try {
    const data = await authenticatedJson<SkillContextV1>(
      buildPath(skill, input.params),
      { method: "GET" },
    );
    cache.set(key, data);
    return { ok: true, data };
  } catch (err) {
    return mapError(err, skill);
  }
}

function mapError(err: unknown, skill: string): GetSkillContextOutput {
  if (err instanceof NotAuthenticatedError) {
    return {
      ok: false,
      error: err.code,
      hint: "Use the `auth_login_start` MCP tool (then `auth_login_poll`) first.",
    };
  }
  if (err instanceof SessionExpiredError) {
    return {
      ok: false,
      error: err.code,
      hint: "Use the `auth_login_start` MCP tool (then `auth_login_poll`) to renew your session.",
    };
  }
  if (err instanceof RateLimitedError) {
    return {
      ok: false,
      error: err.code,
      hint: `Rate limit (${err.scope}) exceeded. Retry after ${err.retryAfterSec}s.`,
      retry_after_sec: err.retryAfterSec,
    };
  }
  if (err instanceof SkillNotFoundError) {
    return {
      ok: false,
      error: err.code,
      hint: err.hint ?? `Skill '${skill}' is not available in this phase.`,
    };
  }
  if (err instanceof NetworkError) {
    return {
      ok: false,
      error: err.code,
      hint: err.detail,
    };
  }
  if (err instanceof BackendError) {
    return {
      ok: false,
      error: err.code,
      hint: `HTTP ${err.status}: ${err.detail.slice(0, 200)}`,
    };
  }
  const detail = err instanceof Error ? err.message : String(err);
  return { ok: false, error: "unknown_error", hint: detail };
}
