/**
 * Thin authenticated HTTP client around the Conversion Agent backend.
 *
 * Uses Node 20's native `fetch`. Every tool handler either gets a success
 * body back or catches one of the typed errors exported below and maps it
 * to a structured MCP response.
 *
 * There is NO watermark, NO audit, NO retry logic here. The backend owns
 * all of that; the MCP server is a passthrough.
 *
 * Fase 12 (ADR-008): honors the sliding-renewal `x-renewed-token` header.
 * Plugin-first auth writes renewed tokens into `${CLAUDE_PLUGIN_DATA}/auth.json`;
 * keychain remains a fallback/migration source only.
 */

import {
  BACKEND_URL,
  backendProtectionHeaders,
  FETCH_TIMEOUT_MS,
} from "./config.js";
import { getToken, savePluginAuth } from "./keychain.js";

/** Raised when no credential is present in the OS keychain. */
export class NotAuthenticatedError extends Error {
  readonly code = "not_authenticated" as const;
  constructor() {
    super(
      "No Conversion credential found. Use the `auth_login_start` MCP tool (then `auth_login_poll`) first.",
    );
    this.name = "NotAuthenticatedError";
  }
}

/** Raised when the backend rejects the JWT (expired, revoked, or invalid). */
export class SessionExpiredError extends Error {
  readonly code = "session_expired" as const;
  constructor() {
    super("Session expired or revoked. Use the `auth_login_start` MCP tool (then `auth_login_poll`) to renew.");
    this.name = "SessionExpiredError";
  }
}

/** Raised when rate limited at the backend. */
export class RateLimitedError extends Error {
  readonly code = "rate_limited" as const;
  constructor(
    public readonly scope: "hourly" | "daily" | "unknown",
    public readonly retryAfterSec: number,
  ) {
    super(`Rate limited (${scope}). Retry in ${retryAfterSec}s.`);
    this.name = "RateLimitedError";
  }
}

/** Raised when the skill slug is unknown server-side. */
export class SkillNotFoundError extends Error {
  readonly code = "skill_not_found" as const;
  constructor(public readonly skill: string, public readonly hint?: string) {
    super(`Skill '${skill}' not found.${hint ? ` ${hint}` : ""}`);
    this.name = "SkillNotFoundError";
  }
}

/** Raised when any upstream 4xx/5xx is not specially mapped. */
export class BackendError extends Error {
  readonly code = "backend_error" as const;
  constructor(
    public readonly status: number,
    public readonly detail: string,
  ) {
    super(`Backend ${status}: ${detail}`);
    this.name = "BackendError";
  }
}

/** Raised when the underlying fetch itself fails (DNS, TLS, timeout). */
export class NetworkError extends Error {
  readonly code = "network_error" as const;
  constructor(public readonly detail: string) {
    super(`Network error: ${detail}`);
    this.name = "NetworkError";
  }
}

function parseRetryAfter(res: Response): number {
  const raw = res.headers.get("retry-after");
  if (!raw) return 60;
  const n = Number.parseInt(raw, 10);
  return Number.isFinite(n) && n > 0 ? n : 60;
}

/**
 * Persist a sliding-renewal token to the keychain for the given email.
 * Logs a stderr warning on success (stdout is reserved for MCP JSON-RPC
 * frames) and swallows failures — the caller already has a working token.
 */
async function persistRenewedToken(email: string, renewed: string): Promise<void> {
  try {
    await savePluginAuth({ email, token: renewed });
    process.stderr.write(`[conversion-mcp] token renewed for ${email}\n`);
  } catch (err) {
    const detail = err instanceof Error ? err.message : String(err);
    process.stderr.write(`[conversion-mcp] failed to persist renewed token: ${detail}\n`);
  }
}

/**
 * Perform an authenticated request against the Conversion backend. The
 * returned `Response` is already known to be 2xx — everything else is
 * thrown as a typed error.
 *
 * `opts.body`, if provided, must already be a JSON string (callers stringify
 * so they own the exact shape).
 */
export async function authenticatedFetch(
  path: string,
  opts: { method: "GET" | "POST"; body?: string } = { method: "GET" },
): Promise<Response> {
  return authenticatedFetchAt(BACKEND_URL, path, opts);
}

export async function authenticatedFetchAt(
  backendUrl: string,
  path: string,
  opts: { method: "GET" | "POST"; body?: string } = { method: "GET" },
): Promise<Response> {
  const cred = await getToken();
  if (!cred) throw new NotAuthenticatedError();

  const url = `${backendUrl}${path}`;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);

  let res: Response;
  try {
    res = await fetch(url, {
      method: opts.method,
      headers: {
        authorization: `Bearer ${cred.token}`,
        accept: "application/json",
        ...backendProtectionHeaders(),
        ...(opts.body !== undefined ? { "content-type": "application/json" } : {}),
      },
      body: opts.body,
      signal: controller.signal,
    });
  } catch (err) {
    clearTimeout(timer);
    const detail = err instanceof Error ? err.message : String(err);
    throw new NetworkError(detail);
  }
  clearTimeout(timer);

  // Sliding-renewal passthrough: backend indicates the JWT has been
  // rotated via `x-renewed-token`. Persist it silently so the next call
  // picks up the fresh credential (the keychain is our single source of
  // truth across CLI + MCP server).
  const renewed = res.headers.get("x-renewed-token");
  if (renewed) {
    await persistRenewedToken(cred.email, renewed);
  }

  if (res.ok) return res;

  // Map well-known error codes.
  if (res.status === 401) throw new SessionExpiredError();

  if (res.status === 429) {
    let scope: "hourly" | "daily" | "unknown" = "unknown";
    try {
      const body = (await res.clone().json()) as { scope?: string };
      if (body.scope === "hourly" || body.scope === "daily") scope = body.scope;
    } catch {
      /* ignore body parse */
    }
    throw new RateLimitedError(scope, parseRetryAfter(res));
  }

  if (res.status === 404) {
    let hint: string | undefined;
    try {
      const body = (await res.clone().json()) as { error?: string; hint?: string };
      hint = body.hint;
    } catch {
      /* ignore */
    }
    throw new SkillNotFoundError("unknown", hint);
  }

  // Generic error: include up to 500 chars of body for debugging.
  const text = await res.text().catch(() => "");
  throw new BackendError(res.status, text.slice(0, 500));
}

/** Convenience: fetch + parse JSON. */
export async function authenticatedJson<T>(
  path: string,
  opts?: { method: "GET" | "POST"; body?: string },
): Promise<T> {
  const res = await authenticatedFetch(path, opts);
  const text = await res.text();
  try {
    return JSON.parse(text) as T;
  } catch {
    throw new BackendError(res.status, `Invalid JSON from ${path}`);
  }
}

export async function authenticatedJsonAt<T>(
  backendUrl: string,
  path: string,
  opts?: { method: "GET" | "POST"; body?: string },
): Promise<T> {
  const res = await authenticatedFetchAt(backendUrl, path, opts);
  const text = await res.text();
  try {
    return JSON.parse(text) as T;
  } catch {
    throw new BackendError(res.status, `Invalid JSON from ${path}`);
  }
}
