/**
 * `relatorio` collection — periodic report delivered to the client.
 *
 * Kept intentionally minimal for the v1: the body is prose, optional
 * references point at projects by slug (cross-project reporting is
 * disallowed by ADR-011 §7, but a single project can produce more than
 * one report so we keep the array).
 */

import { z } from "zod";

import { IsoDateTimeSchema, SlugSchema } from "./_common.js";

export const RELATORIO_TYPE = "relatorio" as const;
export const RELATORIO_CONVENTIONAL_PATH =
  "deliverables/relatorios/" as const;

export const RelatorioStatusSchema = z.enum([
  "draft",
  "approved",
  "delivered",
]);

export const RelatorioFrontmatterSchema = z
  .object({
    slug: SlugSchema,
    title: z.string().min(1).max(300),
    type: z.literal(RELATORIO_TYPE),
    periodo: z.string().min(1).max(100),
    status: RelatorioStatusSchema,
    created_at: IsoDateTimeSchema,
    updated_at: IsoDateTimeSchema,
    related_projects: z.array(SlugSchema).optional(),
  })
  .strict();

export type RelatorioFrontmatter = z.infer<typeof RelatorioFrontmatterSchema>;
