/**
 * `brain.personas` collection — audience description for the project.
 */

import { z } from "zod";

import { IsoDateTimeSchema } from "./_common.js";

export const BRAIN_PERSONAS_TYPE = "brain.personas" as const;
export const BRAIN_PERSONAS_CONVENTIONAL_PATH = "brain/personas.md" as const;

export const BrainPersonasFrontmatterSchema = z
  .object({
    title: z.string().min(1).max(300).default("Personas"),
    type: z.literal(BRAIN_PERSONAS_TYPE),
    updated_at: IsoDateTimeSchema,
    sources: z.array(z.string().min(1).max(300)).optional(),
  })
  .strict();

export type BrainPersonasFrontmatter = z.infer<
  typeof BrainPersonasFrontmatterSchema
>;
