/**
 * Shared helpers used by the project-save tools.
 *
 * Keeping them in a dedicated module makes `project_save_batch` reusable
 * without pulling the full single-commit pipeline from `project-save.ts`.
 * The hashing + canonicalization logic must stay byte-identical to the
 * backend (`apps/backend/src/lib/paths.ts`,
 * `apps/backend/src/lib/blobs/canonicalize.ts`,
 * `.../commits/tree.ts`) so the sha256 computed locally matches the
 * value the server writes to `blobs.sha256`.
 */
import { createHash } from "node:crypto";

const PATH_MAX_LENGTH = 512;
const PATH_MAX_DEPTH = 16;
const PROJECT_PATH_SEGMENT_REGEX = /^[A-Za-z0-9._-]+$/u;
const PROJECT_PATH_WINDOWS_RESERVED_NAMES = new Set([
  "con",
  "prn",
  "aux",
  "nul",
  "com1",
  "com2",
  "com3",
  "com4",
  "com5",
  "com6",
  "com7",
  "com8",
  "com9",
  "lpt1",
  "lpt2",
  "lpt3",
  "lpt4",
  "lpt5",
  "lpt6",
  "lpt7",
  "lpt8",
  "lpt9",
]);

export class InvalidProjectPathError extends Error {
  public readonly path: string;
  public readonly reason: string;
  constructor(path: string, reason: string) {
    super(`invalid path: ${reason} (${JSON.stringify(path)})`);
    this.name = "InvalidProjectPathError";
    this.path = path;
    this.reason = reason;
  }
}

/** Exact local mirror of the canonical shared project-path validator. */
export function validateProjectPathReason(p: unknown): string | null {
  if (typeof p !== "string") return "not_a_string";
  if (p.length === 0) return "empty";
  if (p.length > PATH_MAX_LENGTH) return "too_long";
  if (p.includes("\0")) return "null_byte";
  if (p.includes("\\")) return "backslash";
  if (p.startsWith("/")) return "absolute";
  if (/^[A-Za-z]:/u.test(p)) return "windows_drive";
  if (p.endsWith("/")) return "trailing_slash";
  if (p.includes("//")) return "empty_segment";
  const segments = p.split("/");
  if (segments.length > PATH_MAX_DEPTH) return "too_deep";
  for (const seg of segments) {
    if (seg === "." || seg === "..") return "dot_segment";
    if (seg.endsWith(".") || seg.endsWith(" ")) {
      return "windows_trailing_dot_or_space";
    }
    const stem = seg.split(".")[0]!.toLowerCase();
    if (PROJECT_PATH_WINDOWS_RESERVED_NAMES.has(stem)) {
      return "windows_reserved_name";
    }
    if (!PROJECT_PATH_SEGMENT_REGEX.test(seg)) return "invalid_segment";
  }
  return null;
}

export interface ProjectPathCaseCollision {
  folded: string;
  paths: string[];
}

/** Exact local mirror of the canonical shared case-collision detector. */
export function findProjectPathCaseCollision(
  paths: Iterable<string>,
): ProjectPathCaseCollision | null {
  const byFolded = new Map<string, string[]>();
  for (const path of paths) {
    const folded = path.normalize("NFC").toLocaleLowerCase("en-US");
    const list = byFolded.get(folded) ?? [];
    list.push(path);
    byFolded.set(folded, list);
  }
  for (const [folded, list] of byFolded) {
    const unique = Array.from(new Set(list));
    if (unique.length > 1) {
      return { folded, paths: unique.sort((a, b) => a.localeCompare(b)) };
    }
  }
  return null;
}

export function assertValidProjectPath(p: string): void {
  const reason = validateProjectPathReason(p);
  if (reason) throw new InvalidProjectPathError(String(p), reason);
}

const TEXT_APPLICATION_MIMES: ReadonlySet<string> = new Set<string>([
  "application/json",
  "application/yaml",
  "application/x-yaml",
]);

const MIME_TOKEN = "[!#$%&'*+.^_`|~0-9A-Za-z-]+";
const MIME_PARAMETER_VALUE = `(?:${MIME_TOKEN}|"(?:[\\x20\\x21\\x23-\\x5B\\x5D-\\x7E]|\\\\[\\x20-\\x7E])*")`;
const MANIFEST_MIME_PATTERN = new RegExp(
  `^ *(${MIME_TOKEN})/(${MIME_TOKEN})(?: *; *${MIME_TOKEN} *=${MIME_PARAMETER_VALUE})* *$`,
  "u",
);

/**
 * Accept a Content-Type read from a trusted backend response or an existing
 * local manifest, then store only its canonical type/subtype. Inputs passed
 * directly to MCP tools remain subject to their stricter exact-MIME checks.
 */
export function normalizeManifestMime(value: unknown): string | null {
  if (typeof value !== "string" || value.length === 0) return null;
  for (const character of value) {
    const code = character.charCodeAt(0);
    if (code <= 0x1f || code === 0x7f) return null;
  }
  const match = MANIFEST_MIME_PATTERN.exec(value);
  if (!match) return null;
  return `${match[1]!.toLowerCase()}/${match[2]!.toLowerCase()}`;
}

export function isTextMime(mime: string): boolean {
  if (typeof mime !== "string" || mime.length === 0) return false;
  const first = mime.toLowerCase().split(";")[0];
  if (!first) return false;
  const lower = first.trim();
  if (lower.startsWith("text/")) return true;
  return TEXT_APPLICATION_MIMES.has(lower);
}

const UTF8_BOM = new Uint8Array([0xef, 0xbb, 0xbf]);

function hasBom(buf: Uint8Array): boolean {
  if (buf.length < 3) return false;
  return buf[0] === UTF8_BOM[0] && buf[1] === UTF8_BOM[1] && buf[2] === UTF8_BOM[2];
}

/**
 * Canonicalize text content for hashing. Matches
 * `apps/backend/src/lib/blobs/canonicalize.ts` byte-for-byte on text mimes.
 * Binary mimes pass through untouched.
 */
export function canonicalizeText(input: Uint8Array, mime: string): Uint8Array {
  if (!isTextMime(mime)) return input;
  const withoutBom = hasBom(input) ? input.subarray(3) : input;
  const decoded = new TextDecoder("utf-8").decode(withoutBom);
  const lfOnly = decoded.replace(/\r\n?/g, "\n");
  let normalized = lfOnly;
  if (normalized.length > 0) {
    normalized = normalized.replace(/\n+$/g, "") + "\n";
  }
  return new TextEncoder().encode(normalized);
}

const MIME_BY_EXT: Readonly<Record<string, string>> = {
  ".md": "text/markdown",
  ".yaml": "application/yaml",
  ".yml": "application/yaml",
  ".json": "application/json",
  ".txt": "text/plain",
  ".csv": "text/csv",
  ".html": "text/html",
  ".htm": "text/html",
  ".docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  ".xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
};

export function inferMime(path: string): string {
  const i = path.lastIndexOf(".");
  if (i < 0) return "text/plain";
  const ext = path.slice(i).toLowerCase();
  return MIME_BY_EXT[ext] ?? "text/plain";
}

export function sha256Hex(bytes: Uint8Array): string {
  return createHash("sha256").update(bytes).digest("hex");
}

/**
 * Stable, whitespace-free JSON serialisation of a `{path → sha256}` tree.
 * Must stay byte-identical to the backend `canonicalTreeJson` (ADR-010 §1).
 */
export function canonicalTreeJson(tree: Record<string, string>): string {
  const keys = Object.keys(tree).sort();
  let out = "{";
  for (let i = 0; i < keys.length; i += 1) {
    const k = keys[i]!;
    if (i > 0) out += ",";
    out += JSON.stringify(k);
    out += ":";
    out += JSON.stringify(tree[k]);
  }
  out += "}";
  return out;
}

/** Manifest shape — mirror of the CLI constant + `@agenciaconversion/shared`. */
export interface Manifest {
  backendTarget?: "legacy" | "searchhub";
  projectId: string;
  workspaceId: string;
  workspaceSlug: string;
  projectSlug: string;
  treeHash: string;
  commitId: string | null;
  updatedAt: string;
  files: Record<string, { sha256: string; size: number; mime: string }>;
}
