/**
 * `serp_snapshot` collection — frozen SERP read for a keyword at a point
 * in time.
 *
 * Lives under `pesquisas/serp/<slug>.yml`. Shared across briefings (reuse),
 * so it's a first-class file with a backlinks array (`used_by`) rather
 * than embedded in a single briefing.
 */

import { z } from "zod";

import { IsoDateTimeSchema, SlugSchema } from "./_common.js";

export const SERP_SNAPSHOT_TYPE = "serp_snapshot" as const;
export const SERP_SNAPSHOT_CONVENTIONAL_PATH = "pesquisas/serp/" as const;

export const SerpIntencaoSchema = z.enum([
  "informacional",
  "comercial",
  "transacional",
  "navegacional",
]);

export const SerpTop3EntrySchema = z
  .object({
    posicao: z.number().int().min(1).max(100),
    url: z.string().url(),
    title: z.string(),
    description: z.string().optional(),
    word_count: z.number().int().nonnegative().optional(),
    headings_count: z.number().int().nonnegative().optional(),
  })
  .strict();

export const SerpOutroEntrySchema = z
  .object({
    posicao: z.number().int().min(1).max(100),
    url: z.string().url(),
    title: z.string(),
  })
  .strict();

export const SerpSnapshotFrontmatterSchema = z
  .object({
    type: z.literal(SERP_SNAPSHOT_TYPE),
    slug: SlugSchema,
    keyword: z.string().min(1).max(200),
    gl: z.string().length(2).default("br"),
    hl: z.string().default("pt-br"),
    data_coleta: IsoDateTimeSchema,
    top3: z.array(SerpTop3EntrySchema).max(3),
    outros: z.array(SerpOutroEntrySchema).max(20).default([]),
    features: z.array(z.string()).default([]),
    intencao_dominante: SerpIntencaoSchema.optional(),
    used_by: z.array(SlugSchema).default([]),
  })
  .strict();

export type SerpSnapshotFrontmatter = z.infer<
  typeof SerpSnapshotFrontmatterSchema
>;
