import type { ToolsetMode } from "./config.js";

export const LEGACY_PROJECT_TOOL_NAMES = new Set([
  "project_save_and_url",
  "project_save_batch",
  "package_on_page_optimization",
  "ensure_brain_vault",
  "list_workspaces_projects",
  "materialize_project",
  "get_active_project",
  "set_active_project",
  "sync_status",
  "sync_doctor",
  "sync_pause",
  "sync_resume",
  "sync_repair",
]);

export const SEARCHHUB_PROJECT_TOOL_NAMES = new Set(
  [...LEGACY_PROJECT_TOOL_NAMES].map((name) => `searchhub_${name}`),
);

export function isToolEnabled(name: string, mode: ToolsetMode): boolean {
  if (LEGACY_PROJECT_TOOL_NAMES.has(name)) return mode !== "searchhub";
  if (SEARCHHUB_PROJECT_TOOL_NAMES.has(name)) return mode !== "legacy";
  return true;
}
