/**
 * `newsletter` collection — one edition of a periodic newsletter.
 *
 * `references` can name a featured article plus an ordered list of
 * sections, each with its own picks of internal articles and/or external
 * links. See ADR-011 §3.
 */

import { z } from "zod";

import { IsoDateSchema, IsoDateTimeSchema, SlugSchema } from "./_common.js";

export const NEWSLETTER_TYPE = "newsletter" as const;
export const NEWSLETTER_CONVENTIONAL_PATH =
  "deliverables/newsletters/" as const;

export const NewsletterStatusSchema = z.enum([
  "draft",
  "scheduled",
  "sent",
  "archived",
]);

const SecaoExternoSchema = z
  .object({
    url: z.string().url(),
    title: z.string().min(1).max(300),
  })
  .strict();

const SecaoSchema = z
  .object({
    titulo: z.string().min(1).max(200),
    artigos: z.array(SlugSchema).optional(),
    externos: z.array(SecaoExternoSchema).optional(),
  })
  .strict();

const ReferencesSchema = z
  .object({
    featured: SlugSchema.optional(),
    secoes: z.array(SecaoSchema),
  })
  .strict();

export const NewsletterFrontmatterSchema = z
  .object({
    slug: SlugSchema,
    title: z.string().min(1).max(300),
    type: z.literal(NEWSLETTER_TYPE),
    edicao: IsoDateSchema,
    status: NewsletterStatusSchema,
    created_at: IsoDateTimeSchema,
    updated_at: IsoDateTimeSchema,
    references: ReferencesSchema,
  })
  .strict();

export type NewsletterFrontmatter = z.infer<typeof NewsletterFrontmatterSchema>;
