/**
 * `brain.aprendizados` collection — what worked, what didn't.
 */

import { z } from "zod";

import { IsoDateTimeSchema } from "./_common.js";

export const BRAIN_APRENDIZADOS_TYPE = "brain.aprendizados" as const;
export const BRAIN_APRENDIZADOS_CONVENTIONAL_PATH =
  "brain/aprendizados.md" as const;

export const BrainAprendizadosFrontmatterSchema = z
  .object({
    title: z.string().min(1).max(300).default("Aprendizados"),
    type: z.literal(BRAIN_APRENDIZADOS_TYPE),
    updated_at: IsoDateTimeSchema,
    sources: z.array(z.string().min(1).max(300)).optional(),
  })
  .strict();

export type BrainAprendizadosFrontmatter = z.infer<
  typeof BrainAprendizadosFrontmatterSchema
>;
