/**
 * `fonte_entidade` collection — canonical data extracted from a single
 * entity (official blog, press release, governmental dataset, etc.).
 *
 * Lives under `pesquisas/fontes/<slug>.yml`. Reused across briefings and
 * articles; `used_by` captures the backlinks so the editorial team can
 * see where a datapoint is in active circulation.
 */

import { z } from "zod";

import { IsoDateTimeSchema, SlugSchema } from "./_common.js";

export const FONTE_ENTIDADE_TYPE = "fonte_entidade" as const;
export const FONTE_ENTIDADE_CONVENTIONAL_PATH = "pesquisas/fontes/" as const;

export const FonteTipoSchema = z.enum([
  "blog_oficial",
  "press_release",
  "estudo_original",
  "documento_judicial",
  "post_executivo",
  "dados_governamentais",
  "outro",
]);

export const DadoExtraidoSchema = z
  .object({
    tipo: z.string().min(1),
    valor: z.string().min(1),
    fonte_url: z.string().url(),
    verificado_em: IsoDateTimeSchema,
  })
  .strict();

export const FonteEntidadeFrontmatterSchema = z
  .object({
    type: z.literal(FONTE_ENTIDADE_TYPE),
    slug: SlugSchema,
    entidade: z.string().min(1).max(200),
    site_oficial: z.string().url(),
    tipo_fonte: FonteTipoSchema.default("outro"),
    verificado_em: IsoDateTimeSchema,
    dados: z.array(DadoExtraidoSchema).min(1),
    used_by: z.array(SlugSchema).default([]),
  })
  .strict();

export type FonteEntidadeFrontmatter = z.infer<
  typeof FonteEntidadeFrontmatterSchema
>;
