import { marked } from "marked";
import sanitizeHtml from "sanitize-html";

import type { RedlineDocument, RedlineSegment } from "./contracts.js";

const allowedTags = [
  "main",
  "h1",
  "h2",
  "h3",
  "p",
  "ul",
  "ol",
  "li",
  "table",
  "thead",
  "tbody",
  "tr",
  "th",
  "td",
  "strong",
  "em",
  "code",
  "blockquote",
  "ins",
  "del",
  "span",
];

const allowedAttributes = {
  ins: ["data-reason", "data-priority"],
  del: ["data-reason", "data-priority"],
  span: ["class"],
};

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;");
}

function escapeMarkdownBlockMarkers(value: string): string {
  return escapeHtml(value).replace(
    /(^|\n)(?= {0,3}(?:#{1,6}(?:\s|$)|[-+*]\s|>\s|\d+[.)]\s))/gu,
    "$1\\\\",
  );
}

function renderSegment(segment: RedlineSegment): string {
  if (segment.kind === "keep") return escapeMarkdownBlockMarkers(segment.text);
  const tag = segment.kind === "insert" ? "ins" : "del";
  return `<${tag} data-reason="${escapeHtml(segment.reason)}" data-priority="${segment.priority}">${escapeMarkdownBlockMarkers(segment.text)}</${tag}>`;
}

function hasExactKeys(
  value: unknown,
  expectedKeys: readonly string[],
): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const keys = Object.keys(value).sort();
  return (
    keys.length === expectedKeys.length && keys.every((key, index) => key === expectedKeys[index])
  );
}

function isValidSegment(value: unknown): value is RedlineSegment {
  if (hasExactKeys(value, ["kind", "text"])) {
    return value.kind === "keep" && typeof value.text === "string";
  }

  if (!hasExactKeys(value, ["kind", "priority", "reason", "text"])) return false;
  return (
    (value.kind === "insert" || value.kind === "delete") &&
    typeof value.text === "string" &&
    typeof value.reason === "string" &&
    value.reason.trim().length > 0 &&
    (value.priority === "P0" || value.priority === "P1" || value.priority === "P2")
  );
}

function isValidDocument(value: unknown): value is RedlineDocument {
  if (!hasExactKeys(value, ["blocks"]) || !Array.isArray(value.blocks)) return false;
  return value.blocks.every((block) => {
    if (!hasExactKeys(block, ["kind", "segments"]) || !Array.isArray(block.segments)) {
      if (
        !hasExactKeys(block, ["kind", "level", "segments"]) ||
        block.kind !== "heading" ||
        (block.level !== 1 && block.level !== 2 && block.level !== 3) ||
        !Array.isArray(block.segments)
      ) {
        return false;
      }
    } else if (block.kind !== "paragraph") {
      return false;
    }
    return block.segments.every(isValidSegment);
  });
}

function assertValidDocument(value: unknown): asserts value is RedlineDocument {
  let valid = false;
  try {
    valid = isValidDocument(value);
  } catch {
    valid = false;
  }
  if (!valid) throw new Error("invalid_redline_document");
}

export function renderRedlineHtml(document: RedlineDocument): Buffer {
  assertValidDocument(document);
  const markdown = document.blocks
    .map((block) => {
      const content = block.segments.map(renderSegment).join("");
      return block.kind === "heading" ? `${"#".repeat(block.level)} ${content}` : content;
    })
    .join("\n\n");
  const rendered = marked.parse(markdown, { async: false }) as string;
  const sanitized = sanitizeHtml(`<main>${rendered}</main>`, {
    allowedTags,
    allowedAttributes,
    allowedSchemes: [],
    allowProtocolRelative: false,
    disallowedTagsMode: "discard",
    enforceHtmlBoundary: true,
  });
  return Buffer.from(sanitized, "utf8");
}
