import { readFile, realpath } from "node:fs/promises";
import { isAbsolute, relative, resolve } from "node:path";

import {
  buildMarkdown,
  ON_PAGE_ARTIFACT_STAGE,
  OnPageOptimizationCheckpointSchema,
  OnPageOptimizationManifestSchema,
  parseFrontmatter,
  type OnPageOptimizationManifest,
} from "@agenciaconversion/shared";

import type { ProjectFileBytes, ProjectManifestSnapshot } from "../lib/project-commit.js";
import { canonicalizeText, sha256Hex } from "../lib/project-save-helpers.js";
import { assertOnPageRunSlug, isValidOnPageRunSlug } from "./contracts.js";
import { parseRedlineMarkdown, RedlineParseError } from "./redline.js";
import { renderRedlineDocx, renderSeoClientDocx } from "./render-docx.js";
import { renderRedlineHtml } from "./render-html.js";
import { parseSeoPlan, renderSeoPlanXlsx } from "./render-xlsx.js";

const REFERENCE_KEYS = Object.keys(ON_PAGE_ARTIFACT_STAGE) as Array<
  keyof typeof ON_PAGE_ARTIFACT_STAGE
>;

function sourcePath(runSlug: string, file: string): string {
  return `deliverables/otimizacoes/${runSlug}/${file}`;
}

function isWithinRoot(root: string, target: string): boolean {
  const fromRoot = relative(root, target);
  return fromRoot !== "" && !fromRoot.startsWith("..") && !isAbsolute(fromRoot);
}

async function readSnapshotSource(
  projectRoot: string,
  relativePath: string,
  snapshot: ProjectManifestSnapshot,
): Promise<string> {
  const metadata = snapshot.manifest.files[relativePath];
  if (!metadata) throw new Error(`missing_source:${relativePath}`);
  if (metadata.mime !== "text/markdown") throw new Error("snapshot_conflict");
  const lexicalTarget = resolve(projectRoot, ...relativePath.split("/"));
  if (!isWithinRoot(projectRoot, lexicalTarget)) throw new Error("invalid_run_slug");
  let resolvedTarget: string;
  try {
    resolvedTarget = await realpath(lexicalTarget);
  } catch {
    throw new Error("snapshot_conflict");
  }
  if (!isWithinRoot(projectRoot, resolvedTarget)) throw new Error("invalid_run_slug");
  let diskBytes: Buffer;
  try {
    diskBytes = await readFile(resolvedTarget);
  } catch {
    throw new Error("snapshot_conflict");
  }
  const canonical = Buffer.from(canonicalizeText(diskBytes, "text/markdown"));
  if (canonical.length !== metadata.size || sha256Hex(canonical) !== metadata.sha256) {
    throw new Error("snapshot_conflict");
  }
  return canonical.toString("utf8");
}

function parsedMarkdown(source: string): { frontmatter: Record<string, unknown>; body: string } {
  const parsed = parseFrontmatter(source);
  if (!parsed.ok || !parsed.frontmatter || parsed.body === undefined) {
    throw new Error("invalid_manifest");
  }
  return { frontmatter: parsed.frontmatter, body: parsed.body };
}

function validateCheckpoint(
  source: string,
  kind: "redline" | "seo",
  runSlug: string,
  expectedSlug: string,
): string {
  const parsed = parsedMarkdown(source);
  const checkpoint = OnPageOptimizationCheckpointSchema.safeParse(parsed.frontmatter);
  if (
    !checkpoint.success ||
    checkpoint.data.artifact_kind !== kind ||
    checkpoint.data.optimization_ref !== runSlug ||
    checkpoint.data.slug !== expectedSlug ||
    checkpoint.data.status !== "aprovado"
  ) {
    throw new Error(`invalid_${kind}`);
  }
  return parsed.body;
}

function assertQaApproved(source: string, runSlug: string, expectedSlug: string): void {
  const parsed = parsedMarkdown(source);
  const qaResult = parsed.frontmatter.qa_result;
  const openP0 = parsed.frontmatter.open_p0;
  const openP1 = parsed.frontmatter.open_p1;
  if (
    (qaResult !== "aprovado" && qaResult !== "aprovado_com_ressalvas") ||
    openP0 !== 0 ||
    openP1 !== 0
  ) {
    throw new Error("qa_blocked");
  }
  const checkpoint = OnPageOptimizationCheckpointSchema.safeParse(parsed.frontmatter);
  if (
    !checkpoint.success ||
    checkpoint.data.artifact_kind !== "qa" ||
    checkpoint.data.optimization_ref !== runSlug ||
    checkpoint.data.slug !== expectedSlug ||
    checkpoint.data.status !== "aprovado"
  ) {
    throw new Error("qa_blocked");
  }
}

export async function buildOnPagePackage(
  projectRoot: string,
  runSlug: string,
  snapshot: ProjectManifestSnapshot,
): Promise<{ files: ProjectFileBytes[]; manifest: OnPageOptimizationManifest }> {
  if (!isValidOnPageRunSlug(runSlug)) throw new Error("invalid_run_slug");
  let resolvedProjectRoot: string;
  try {
    resolvedProjectRoot = await realpath(resolve(projectRoot));
  } catch {
    throw new Error("invalid_run_slug");
  }
  const indexPath = sourcePath(runSlug, "index.md");
  const redlinePath = sourcePath(runSlug, "04-redline.md");
  const seoPath = sourcePath(runSlug, "05-seo.md");
  const qaPath = sourcePath(runSlug, "07-qa-report.md");
  const indexSource = await readSnapshotSource(resolvedProjectRoot, indexPath, snapshot);
  const index = parsedMarkdown(indexSource);
  const parsedManifest = OnPageOptimizationManifestSchema.safeParse(index.frontmatter);
  if (!parsedManifest.success) throw new Error("invalid_manifest");
  const manifest = parsedManifest.data;
  try {
    assertOnPageRunSlug(runSlug, manifest.canonical_url);
  } catch {
    throw new Error("invalid_run_slug");
  }
  if (
    manifest.run_slug !== runSlug ||
    manifest.archetype !== "blog" ||
    manifest.current_stage !== "qa" ||
    manifest.status !== "aprovado"
  ) {
    throw new Error("invalid_manifest");
  }
  const references = REFERENCE_KEYS.map((key) => manifest.references[key]);
  if (
    references.some((reference) => reference === undefined) ||
    new Set(references).size !== REFERENCE_KEYS.length
  ) {
    throw new Error("invalid_manifest");
  }

  // Read in canonical order so a run with multiple absences has one stable error.
  const redlineSource = await readSnapshotSource(resolvedProjectRoot, redlinePath, snapshot);
  const seoSource = await readSnapshotSource(resolvedProjectRoot, seoPath, snapshot);
  const qaSource = await readSnapshotSource(resolvedProjectRoot, qaPath, snapshot);

  // Complete every gate and parse every source before invoking any renderer.
  assertQaApproved(qaSource, runSlug, manifest.references.qa!);
  const redlineBody = validateCheckpoint(
    redlineSource,
    "redline",
    runSlug,
    manifest.references.redline!,
  );
  const seoBody = validateCheckpoint(seoSource, "seo", runSlug, manifest.references.seo!);
  let redline;
  try {
    redline = parseRedlineMarkdown(redlineBody);
  } catch (error) {
    if (error instanceof RedlineParseError) throw new Error("invalid_redline");
    throw error;
  }
  const seoRows = parseSeoPlan(seoBody);

  const base = `deliverables/otimizacoes/${runSlug}`;
  const artifacts = {
    seo_client_docx: `${base}/05-seo-cliente.docx`,
    redline_docx: `${base}/redline.docx`,
    redline_html: `${base}/redline.html`,
    seo_plan_xlsx: `${base}/plano.xlsx`,
  };
  const nextManifest = OnPageOptimizationManifestSchema.parse({
    ...manifest,
    current_stage: "empacotamento",
    status: "empacotado",
    artifacts,
  });
  const [seoDocx, redlineDocx, redlineHtml, seoXlsx] = await Promise.all([
    renderSeoClientDocx(seoBody, manifest.created_at),
    renderRedlineDocx(redline, manifest.created_at),
    Promise.resolve(renderRedlineHtml(redline)),
    renderSeoPlanXlsx(seoRows, manifest.created_at),
  ]);
  const indexBytes = Buffer.from(
    buildMarkdown(nextManifest as unknown as Record<string, unknown>, index.body),
    "utf8",
  );
  return {
    manifest: nextManifest,
    files: [
      { path: indexPath, bytes: indexBytes, mime: "text/markdown" },
      {
        path: artifacts.seo_client_docx,
        bytes: seoDocx,
        mime: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      },
      {
        path: artifacts.redline_docx,
        bytes: redlineDocx,
        mime: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      },
      { path: artifacts.redline_html, bytes: redlineHtml, mime: "text/html" },
      {
        path: artifacts.seo_plan_xlsx,
        bytes: seoXlsx,
        mime: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      },
    ],
  };
}
