/**
 * `artigo` collection — single piece of editorial content.
 *
 * Lives under `deliverables/conteudos/<slug>.md` by convention (ADR-011 §1).
 * Referenced from clusters and newsletters via `slug`.
 *
 * Rodada 22H — the schema absorbs editorial state that used to live only in
 * skill memory: `workflow` (tipo/etapa/acao), `meta` (title_tag + meta
 * description), `stats` (target vs actual wordcount, headings, links),
 * `revisoes[]` (ordered trail of revisions + coesão passes with gate
 * outcomes) and `conhecimento_original` (inline; promoted to its own
 * collection when the vectorial KB returns). The previous `source_briefing`
 * field is removed in favour of `briefing_ref` — MVP has no legacy, so we
 * break the contract cleanly.
 */

import { z } from "zod";

import { IsoDateTimeSchema, SlugSchema, TagsSchema, UuidSchema } from "./_common.js";

export const ARTIGO_TYPE = "artigo" as const;
export const ARTIGO_CONVENTIONAL_PATH = "deliverables/conteudos/" as const;
export type ArtigoMetadataField = "title" | "description";

const ARTIGO_METADATA_MAX_LENGTH: Record<ArtigoMetadataField, number> = {
  title: 70,
  description: 200,
};

/**
 * Shared validation for every editable SEO title/description alias. Keep this
 * separate from the Zod schema so the web editor can reject invalid values
 * before they become a blob that fails strict article validation.
 */
export function validateArticleMetadataValue(
  field: ArtigoMetadataField,
  value: unknown,
): string | null {
  if (typeof value !== "string" || value.trim().length === 0) {
    return `metadata ${field} cannot be blank`;
  }
  const maxLength = ARTIGO_METADATA_MAX_LENGTH[field];
  if (value.length > maxLength) {
    return `metadata ${field} must be at most ${maxLength} characters`;
  }
  return null;
}

/**
 * pt-BR status set — aligns with the vocabulary the skills actually emit.
 * Old en-US values (`draft`, `review`, `approved`, `published`, `archived`)
 * are intentionally dropped (MVP, no migration).
 */
export const ArtigoStatusSchema = z.enum([
  "rascunho",
  "revisao",
  "finalizado",
  "publicado",
  "arquivado",
]);

export const ArtigoWorkflowTipoSchema = z.enum(["evergreen", "noticia", "cluster"]);

export const ArtigoWorkflowEtapaSchema = z.enum([
  "briefing",
  "redacao",
  "revisao",
  "coesao",
  "finalizado",
]);

export const ArtigoWorkflowAcaoSchema = z.enum(["criar", "atualizar", "otimizar", "refresh"]);

export const ArtigoRevisaoTipoSchema = z.enum(["revisao", "coesao"]);
export const ArtigoFactcheckModeSchema = z.enum(["off", "advisory", "enforced"]);
export const ArtigoFactcheckStatusSchema = z.enum(["skipped", "ok", "needs_review", "blocked"]);

const ArtigoWorkflowSchema = z
  .object({
    tipo: ArtigoWorkflowTipoSchema,
    etapa: ArtigoWorkflowEtapaSchema,
    acao: ArtigoWorkflowAcaoSchema.optional(),
  })
  .strict();

const ArtigoMetadataTitleSchema = z
  .string()
  .min(1)
  .max(70)
  .refine(
    (value) => validateArticleMetadataValue("title", value) === null,
    "metadata title cannot be blank",
  );
const ArtigoMetadataDescriptionSchema = z
  .string()
  .min(1)
  .max(200)
  .refine(
    (value) => validateArticleMetadataValue("description", value) === null,
    "metadata description cannot be blank",
  );

/**
 * Canonical articles use `meta.title_tag` + `meta.description`. The legacy
 * `meta.title` alias remains readable so old artifacts can be repaired in
 * place instead of becoming invisible to strict validation.
 */
const ArtigoMetaSchema = z
  .object({
    title_tag: ArtigoMetadataTitleSchema.optional(),
    title: ArtigoMetadataTitleSchema.optional(),
    description: ArtigoMetadataDescriptionSchema.optional(),
  })
  .strict();

/**
 * Some external article producers wrote SEO fields under `seo.*` and included
 * producer-specific sibling fields (`h1`, `meta_robots`, etc.). Preserve
 * those siblings while validating the title/description aliases we support.
 */
const ArtigoSeoSchema = z
  .object({
    meta_title: ArtigoMetadataTitleSchema.optional(),
    title: ArtigoMetadataTitleSchema.optional(),
    meta_description: ArtigoMetadataDescriptionSchema.optional(),
    description: ArtigoMetadataDescriptionSchema.optional(),
  })
  .catchall(z.unknown());

const ArtigoStatsSchema = z
  .object({
    target_words: z.number().int().nonnegative().optional(),
    actual_words: z.number().int().nonnegative().optional(),
    h2_count: z.number().int().nonnegative().optional(),
    h3_count: z.number().int().nonnegative().optional(),
    links_internos: z.number().int().nonnegative().optional(),
    links_externos: z.number().int().nonnegative().optional(),
    coesao_benchmark: z.string().optional(),
  })
  .strict();

const ArtigoRevisaoSchema = z
  .object({
    data: IsoDateTimeSchema,
    tipo: ArtigoRevisaoTipoSchema,
    skill: z.string().min(1),
    diff_summary: z.string().optional(),
    gates_aprovados: z.array(z.string()).default([]),
  })
  .strict();

const ArtigoConhecimentoOriginalSchema = z
  .object({
    consultado: z.boolean(),
    livros: z.array(z.string()).default([]),
    notas: z.string().optional(),
  })
  .strict();

const ArtigoFactcheckSchema = z
  .object({
    mode: ArtigoFactcheckModeSchema,
    status: ArtigoFactcheckStatusSchema,
    dossier_path: z.string().min(1).max(512).optional(),
    ledger_path: z.string().min(1).max(512).optional(),
    verified_at: IsoDateTimeSchema.optional(),
  })
  .strict();

export const ArtigoFrontmatterSchema = z
  .object({
    slug: SlugSchema,
    title: z.string().min(1).max(300),
    type: z.literal(ARTIGO_TYPE),
    status: ArtigoStatusSchema,
    created_at: IsoDateTimeSchema,
    updated_at: IsoDateTimeSchema,
    created_by: UuidSchema.optional(),
    tags: TagsSchema.optional(),
    keywords: z.array(z.string().min(1).max(120)).optional(),

    /**
     * Optional — required when the article was produced from a briefing (the
     * standard flow) and absent for articles that nasce solto (e.g. news
     * desk). Bidirectional with `briefing.references.conteudo`.
     */
    briefing_ref: SlugSchema.optional(),

    internal_links: z.array(SlugSchema).optional(),
    cluster: SlugSchema.optional(),

    workflow: ArtigoWorkflowSchema.optional(),
    meta: ArtigoMetaSchema.optional(),
    seo: ArtigoSeoSchema.optional(),
    meta_title: ArtigoMetadataTitleSchema.optional(),
    meta_description: ArtigoMetadataDescriptionSchema.optional(),
    stats: ArtigoStatsSchema.optional(),
    revisoes: z.array(ArtigoRevisaoSchema).default([]),
    conhecimento_original: ArtigoConhecimentoOriginalSchema.optional(),
    factcheck: ArtigoFactcheckSchema.optional(),
  })
  .strict()
  .superRefine((frontmatter, ctx) => {
    const titleAliases = [
      { source: "seo.meta_title", value: frontmatter.seo?.meta_title },
      { source: "seo.title", value: frontmatter.seo?.title },
      { source: "meta_title", value: frontmatter.meta_title },
      { source: "meta.title_tag", value: frontmatter.meta?.title_tag },
      { source: "meta.title", value: frontmatter.meta?.title },
    ].filter(
      (candidate): candidate is { source: string; value: string } =>
        typeof candidate.value === "string",
    );
    const descriptionAliases = [
      { source: "seo.meta_description", value: frontmatter.seo?.meta_description },
      { source: "seo.description", value: frontmatter.seo?.description },
      { source: "meta_description", value: frontmatter.meta_description },
      { source: "meta.description", value: frontmatter.meta?.description },
    ].filter(
      (candidate): candidate is { source: string; value: string } =>
        typeof candidate.value === "string",
    );

    if (titleAliases.length + descriptionAliases.length > 0) {
      if (titleAliases.length === 0 || descriptionAliases.length === 0) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message:
            "metadata_title_and_description_required: supported metadata must include title and description",
        });
      }
    }

    for (const [field, aliases] of [
      ["title", titleAliases],
      ["description", descriptionAliases],
    ] as const) {
      const first = aliases[0];
      if (!first || aliases.every((alias) => alias.value === first.value)) continue;

      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: first.source.split("."),
        message: `metadata_alias_conflict: ${field} aliases differ (${aliases
          .map((alias) => alias.source)
          .join(", ")}); resolve explicitly before saving`,
      });
    }
  });

export type ArtigoFrontmatter = z.infer<typeof ArtigoFrontmatterSchema>;
