import { createHash, randomUUID } from "node:crypto";
import {
  chmod,
  link,
  mkdir,
  readFile,
  readdir,
  rename,
  rm,
  stat,
  writeFile,
} from "node:fs/promises";
import { basename, dirname, join, relative, sep } from "node:path";

export interface SyncFileMeta {
  sha256: string;
  size?: number;
  mime?: string;
}

export type SyncTree = Record<string, string>;
export type LocalFileMap = Record<string, SyncFileMeta>;

export interface SyncManifest {
  projectId: string;
  workspaceId: string;
  workspaceSlug: string;
  projectSlug: string;
  treeHash: string;
  commitId: string | null;
  updatedAt: string;
  files: Record<string, SyncFileMeta>;
}

export interface SyncHubProjectEntry {
  ws_slug: string;
  proj_slug: string;
  ws_id: string;
  proj_id: string;
  path: string;
}

export interface SyncHubConfig {
  version: 1;
  created_at: string;
  updated_at: string;
  projects: SyncHubProjectEntry[];
  active: { ws_slug: string; proj_slug: string } | null;
}

export type SyncMode = "observe" | "pull" | "bidirectional" | "disabled";

export interface ProjectSyncStatus {
  mode: SyncMode;
  paused: boolean;
  updatedAt: string;
  lastRunAt?: string;
  lastError?: string;
  conflicts?: SyncConflict[];
  pendingUpload?: string[];
  pendingDownload?: string[];
}

export interface BaseSyncState {
  commitId: string | null;
  treeHash: string;
  tree: SyncTree;
}

export interface RemoteSyncState {
  commitId: string | null;
  treeHash: string;
  tree: SyncTree;
}

export type ConflictKind =
  | "same-file"
  | "delete-vs-edit"
  | "invalid-path"
  | "case-collision";

export interface SyncConflict {
  path: string;
  kind: ConflictKind;
  baseSha?: string;
  localSha?: string;
  remoteSha?: string;
  details?: string;
}

export interface ReconcileInput {
  base: BaseSyncState;
  local: LocalFileMap;
  remote: RemoteSyncState;
}

export interface ReconcilePlan {
  status: "clean" | "pull" | "push" | "merge" | "conflict";
  nextTree: SyncTree;
  upload: string[];
  download: string[];
  deleteLocal: string[];
  conflicts: SyncConflict[];
  remoteChanged: boolean;
  localChanged: boolean;
}

export interface AcquireSyncLockOptions {
  projectRoot: string;
  owner: "plugin" | "cli" | "test" | string;
  staleMs?: number;
}

export interface SyncLockMetadata {
  owner: string;
  ownerId: string;
  pid: number;
  startedAt: string;
  heartbeatAt: string;
  projectRoot: string;
}

export interface SyncLock {
  lockDir: string;
  metadata: SyncLockMetadata;
  heartbeat(): Promise<void>;
  release(): Promise<void>;
}

export interface ConflictSnapshotInput {
  projectRoot: string;
  conflicts: SyncConflict[];
  base?: Record<string, string | Uint8Array | null | undefined>;
  local?: Record<string, string | Uint8Array | null | undefined>;
  remote?: Record<string, string | Uint8Array | null | undefined>;
}

export interface ClientCommitIdInput {
  projectId: string;
  actorUserId: string;
  syncClientId: string;
  parentCommitId: string | null;
  parentTreeHash: string | null;
  treeHash: string;
  message?: string | null;
}

const PATH_MAX_LENGTH = 512;
const PATH_MAX_DEPTH = 16;
const SEGMENT_REGEX = /^[A-Za-z0-9._-]+$/u;
const WINDOWS_RESERVED_NAMES = new Set([
  "con",
  "prn",
  "aux",
  "nul",
  "com1",
  "com2",
  "com3",
  "com4",
  "com5",
  "com6",
  "com7",
  "com8",
  "com9",
  "lpt1",
  "lpt2",
  "lpt3",
  "lpt4",
  "lpt5",
  "lpt6",
  "lpt7",
  "lpt8",
  "lpt9",
]);

const MANIFEST_RELATIVE_PATH = ".conversion/manifest.json";
const HUB_FILE = ".conversion-hub.json";
const STATUS_RELATIVE_PATH = ".conversion/sync/status.json";
const LOCK_RELATIVE_PATH = ".conversion/sync/project.lock";
const QUIET_DIR_RELATIVE_PATH = ".conversion/sync/quiet";
const SNAPSHOT_DIR_RELATIVE_PATH = ".conversion/sync/snapshots";
const DEFAULT_STALE_LOCK_MS = 45_000;

export function manifestPath(projectRoot: string): string {
  return join(projectRoot, MANIFEST_RELATIVE_PATH);
}

export function hubPath(hubRoot: string): string {
  return join(hubRoot, HUB_FILE);
}

export function statusPath(projectRoot: string): string {
  return join(projectRoot, STATUS_RELATIVE_PATH);
}

export async function readJsonFile<T>(filePath: string): Promise<T | null> {
  try {
    return JSON.parse(await readFile(filePath, "utf8")) as T;
  } catch {
    return null;
  }
}

export async function atomicWriteJson(
  filePath: string,
  value: unknown,
  mode = 0o600,
): Promise<void> {
  await mkdir(dirname(filePath), { recursive: true });
  const tmp = join(dirname(filePath), `.${process.pid}.${randomUUID()}.tmp`);
  await writeFile(tmp, `${JSON.stringify(value, null, 2)}\n`, {
    encoding: "utf8",
    mode,
  });
  await chmod(tmp, mode).catch(() => undefined);
  await rename(tmp, filePath);
}

export async function readManifest(projectRoot: string): Promise<SyncManifest | null> {
  const value = await readJsonFile<SyncManifest>(manifestPath(projectRoot));
  return isManifest(value) ? value : null;
}

export async function writeManifest(
  projectRoot: string,
  manifest: SyncManifest,
): Promise<void> {
  await atomicWriteJson(manifestPath(projectRoot), manifest);
}

export async function readHub(hubRoot: string): Promise<SyncHubConfig | null> {
  const value = await readJsonFile<SyncHubConfig>(hubPath(hubRoot));
  return isHub(value) ? value : null;
}

export async function writeHub(
  hubRoot: string,
  hub: SyncHubConfig,
): Promise<void> {
  await atomicWriteJson(hubPath(hubRoot), hub);
}

export async function upsertHubProject(
  hubRoot: string,
  entry: SyncHubProjectEntry,
): Promise<SyncHubConfig> {
  const now = new Date().toISOString();
  const current =
    (await readHub(hubRoot)) ?? {
      version: 1 as const,
      created_at: now,
      updated_at: now,
      projects: [],
      active: null,
    };
  const projects = current.projects.filter(
    (p) => !(p.ws_slug === entry.ws_slug && p.proj_slug === entry.proj_slug),
  );
  projects.push(entry);
  projects.sort((a, b) =>
    `${a.ws_slug}/${a.proj_slug}`.localeCompare(`${b.ws_slug}/${b.proj_slug}`),
  );
  const next: SyncHubConfig = { ...current, updated_at: now, projects };
  await writeHub(hubRoot, next);
  return next;
}

export async function scanLocalFiles(projectRoot: string): Promise<LocalFileMap> {
  const out: LocalFileMap = {};
  await scanDirectory(projectRoot, projectRoot, out);
  const collision = caseCollisionConflicts(Object.keys(out))[0];
  if (collision) {
    throw new Error(`case_collision:${collision.path}`);
  }
  return out;
}

export async function acquireSyncLock(
  opts: AcquireSyncLockOptions,
): Promise<SyncLock | null> {
  const staleMs = opts.staleMs ?? DEFAULT_STALE_LOCK_MS;
  const lockDir = join(opts.projectRoot, LOCK_RELATIVE_PATH);
  await mkdir(dirname(lockDir), { recursive: true });
  const guard = await acquireMutationGuard(lockDir, staleMs);
  try {
    const exists = await syncPathExists(lockDir);
    const current = exists ? await readBusinessLock(lockDir) : null;
    if (current && isFreshLock(current, staleMs)) return null;
    if (exists) await rm(lockDir, { recursive: true, force: true });
    try {
      await mkdir(lockDir);
      const metadata = makeLockMetadata(opts.projectRoot, opts.owner);
      await atomicWriteJson(join(lockDir, "owner.json"), metadata);
      await atomicWriteJson(join(lockDir, "heartbeat.json"), {
        ownerId: metadata.ownerId,
        heartbeatAt: metadata.heartbeatAt,
      });
      return makeSyncLock(lockDir, metadata, staleMs);
    } catch (error) {
      await rm(lockDir, { recursive: true, force: true });
      throw error;
    }
  } finally {
    await guard.release();
  }
}

export async function readSyncStatus(
  projectRoot: string,
): Promise<ProjectSyncStatus | null> {
  return readJsonFile<ProjectSyncStatus>(statusPath(projectRoot));
}

export async function writeSyncStatus(
  projectRoot: string,
  status: Omit<ProjectSyncStatus, "updatedAt"> & { updatedAt?: string },
): Promise<ProjectSyncStatus> {
  const next: ProjectSyncStatus = {
    ...status,
    updatedAt: status.updatedAt ?? new Date().toISOString(),
  };
  await atomicWriteJson(statusPath(projectRoot), next);
  return next;
}

export async function pauseSync(
  projectRoot: string,
  reason: string,
  conflicts: SyncConflict[] = [],
): Promise<ProjectSyncStatus> {
  const current = await readSyncStatus(projectRoot);
  return writeSyncStatus(projectRoot, {
    mode: current?.mode ?? "observe",
    paused: true,
    lastError: reason,
    conflicts,
    lastRunAt: current?.lastRunAt,
    pendingUpload: current?.pendingUpload,
    pendingDownload: current?.pendingDownload,
  });
}

export async function resumeSync(projectRoot: string): Promise<ProjectSyncStatus> {
  const current = await readSyncStatus(projectRoot);
  return writeSyncStatus(projectRoot, {
    mode: current?.mode ?? "observe",
    paused: false,
    lastRunAt: current?.lastRunAt,
    pendingUpload: current?.pendingUpload,
    pendingDownload: current?.pendingDownload,
  });
}

export async function writeQuietMarker(
  projectRoot: string,
  marker: { path: string; sha256: string; reason: string; expiresAt?: string },
): Promise<void> {
  const reason = validateSyncPath(marker.path);
  if (reason) throw new Error(`invalid_path:${reason}:${marker.path}`);
  await atomicWriteJson(quietMarkerPath(projectRoot, marker.path), {
    ...marker,
    createdAt: new Date().toISOString(),
  });
}

export async function readQuietMarker(
  projectRoot: string,
  path: string,
): Promise<{ path: string; sha256: string; reason: string; expiresAt?: string } | null> {
  const marker = await readJsonFile<{
    path: string;
    sha256: string;
    reason: string;
    expiresAt?: string;
  }>(quietMarkerPath(projectRoot, path));
  if (!marker) return null;
  if (marker.expiresAt && Date.parse(marker.expiresAt) <= Date.now()) {
    await rm(quietMarkerPath(projectRoot, path), { force: true });
    return null;
  }
  return marker;
}

export async function clearQuietMarker(
  projectRoot: string,
  path: string,
): Promise<void> {
  await rm(quietMarkerPath(projectRoot, path), { force: true });
}

export async function writeConflictSnapshot(
  input: ConflictSnapshotInput,
): Promise<string> {
  const firstPath = input.conflicts[0]?.path ?? "conflict";
  const id = `${new Date().toISOString().replace(/[:.]/gu, "-")}-${hashText(firstPath).slice(0, 8)}`;
  const dir = join(input.projectRoot, SNAPSHOT_DIR_RELATIVE_PATH, id);
  await mkdir(dir, { recursive: true });
  await atomicWriteJson(join(dir, "conflicts.json"), {
    createdAt: new Date().toISOString(),
    conflicts: input.conflicts,
  });
  await writeSnapshotSide(dir, "base", input.base);
  await writeSnapshotSide(dir, "local", input.local);
  await writeSnapshotSide(dir, "remote", input.remote);
  return dir;
}

export function reconcile(input: ReconcileInput): ReconcilePlan {
  const localTree = localToTree(input.local);
  const allPaths = sortedUnion(
    Object.keys(input.base.tree),
    Object.keys(localTree),
    Object.keys(input.remote.tree),
  );

  const conflicts: SyncConflict[] = [
    ...validatePathSet("base", Object.keys(input.base.tree)),
    ...validatePathSet("local", Object.keys(localTree)),
    ...validatePathSet("remote", Object.keys(input.remote.tree)),
    ...caseCollisionConflicts(allPaths),
  ];
  const conflictKeys = new Set(conflicts.map((c) => `${c.kind}:${c.path}`));

  const nextTree: SyncTree = {};
  const upload: string[] = [];
  const download: string[] = [];
  const deleteLocal: string[] = [];
  let remoteChanged = false;
  let localChanged = false;

  for (const path of allPaths) {
    const baseSha = input.base.tree[path];
    const localSha = localTree[path];
    const remoteSha = input.remote.tree[path];
    const localTouched = localSha !== baseSha;
    const remoteTouched = remoteSha !== baseSha;

    if (localTouched) localChanged = true;
    if (remoteTouched) remoteChanged = true;

    if (localTouched && remoteTouched && localSha !== remoteSha) {
      const kind =
        localSha === undefined || remoteSha === undefined
          ? "delete-vs-edit"
          : "same-file";
      const key = `${kind}:${path}`;
      if (!conflictKeys.has(key)) {
        conflicts.push({ path, kind, baseSha, localSha, remoteSha });
        conflictKeys.add(key);
      }
      if (localSha !== undefined) nextTree[path] = localSha;
      continue;
    }

    const chosenSha = localTouched ? localSha : remoteSha;
    if (chosenSha !== undefined) nextTree[path] = chosenSha;

    if (!localTouched && remoteTouched) {
      if (remoteSha === undefined) deleteLocal.push(path);
      else download.push(path);
    }
    if (localTouched && !remoteTouched && localSha !== undefined) {
      upload.push(path);
    }
  }

  upload.sort();
  download.sort();
  deleteLocal.sort();
  conflicts.sort((a, b) => a.path.localeCompare(b.path) || a.kind.localeCompare(b.kind));

  return {
    status: statusFor({ conflicts, upload, download, deleteLocal }),
    nextTree,
    upload,
    download,
    deleteLocal,
    conflicts,
    remoteChanged,
    localChanged,
  };
}

export function localToTree(local: LocalFileMap): SyncTree {
  const tree: SyncTree = {};
  for (const [path, meta] of Object.entries(local)) {
    tree[path] = meta.sha256;
  }
  return tree;
}

export function validateSyncPath(path: string): string | null {
  if (path.length === 0) return "empty";
  if (path.length > PATH_MAX_LENGTH) return "too_long";
  if (path.includes("\0")) return "null_byte";
  if (path.includes("\\")) return "backslash";
  if (path.startsWith("/")) return "absolute";
  if (/^[A-Za-z]:/u.test(path)) return "windows_drive";
  if (path.endsWith("/")) return "trailing_slash";
  if (path.includes("//")) return "empty_segment";

  const segments = path.split("/");
  if (segments.length > PATH_MAX_DEPTH) return "too_deep";
  for (const segment of segments) {
    if (segment === "." || segment === "..") return "dot_segment";
    if (segment.endsWith(".") || segment.endsWith(" ")) {
      return "windows_trailing_dot_or_space";
    }
    const stem = segment.split(".")[0]!.toLowerCase();
    if (WINDOWS_RESERVED_NAMES.has(stem)) return "windows_reserved_name";
    if (!SEGMENT_REGEX.test(segment)) return "invalid_segment";
  }
  return null;
}

export function deterministicCommitId(input: ClientCommitIdInput): string {
  const hex = createHash("sha256")
    .update(
      [
        "conversion-client-commit-v2",
        input.projectId,
        input.actorUserId,
        input.syncClientId,
        input.parentCommitId ?? "null",
        input.parentTreeHash ?? "null",
        input.treeHash,
        input.message ?? "",
      ].join("\0"),
    )
    .digest("hex");
  const chars = hex.slice(0, 32).split("");
  chars[12] = "4";
  const variant = Number.parseInt(chars[16]!, 16);
  chars[16] = ((variant & 0x3) | 0x8).toString(16);
  const id = chars.join("");
  return `${id.slice(0, 8)}-${id.slice(8, 12)}-${id.slice(12, 16)}-${id.slice(16, 20)}-${id.slice(20, 32)}`;
}

function isManifest(value: SyncManifest | null): value is SyncManifest {
  if (!value || typeof value !== "object") return false;
  return (
    typeof value.projectId === "string" &&
    typeof value.workspaceId === "string" &&
    typeof value.workspaceSlug === "string" &&
    typeof value.projectSlug === "string" &&
    typeof value.treeHash === "string" &&
    (value.commitId === null || typeof value.commitId === "string") &&
    typeof value.updatedAt === "string" &&
    !!value.files &&
    typeof value.files === "object"
  );
}

function isHub(value: SyncHubConfig | null): value is SyncHubConfig {
  if (!value || typeof value !== "object") return false;
  return (
    value.version === 1 &&
    typeof value.created_at === "string" &&
    typeof value.updated_at === "string" &&
    Array.isArray(value.projects)
  );
}

async function scanDirectory(
  root: string,
  dir: string,
  out: LocalFileMap,
): Promise<void> {
  const entries = await readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.name === ".conversion" || entry.name === ".git") continue;
    const absolute = join(dir, entry.name);
    if (entry.isDirectory()) {
      await scanDirectory(root, absolute, out);
      continue;
    }
    if (!entry.isFile()) continue;
    const rel = normalizeRelativePath(relative(root, absolute));
    const reason = validateSyncPath(rel);
    if (reason) throw new Error(`invalid_path:${reason}:${rel}`);
    const content = await readFile(absolute);
    const fileStat = await stat(absolute);
    out[rel] = {
      sha256: createHash("sha256").update(content).digest("hex"),
      size: fileStat.size,
    };
  }
}

function normalizeRelativePath(path: string): string {
  return sep === "/" ? path : path.split(sep).join("/");
}

function makeLockMetadata(projectRoot: string, owner: string): SyncLockMetadata {
  const now = new Date().toISOString();
  return {
    owner,
    ownerId: randomUUID(),
    pid: process.pid,
    startedAt: now,
    heartbeatAt: now,
    projectRoot,
  };
}

function makeSyncLock(
  lockDir: string,
  metadata: SyncLockMetadata,
  staleMs: number,
): SyncLock {
  return {
    lockDir,
    metadata,
    async heartbeat() {
      const guard = await acquireMutationGuard(lockDir, staleMs);
      try {
        const current = await readJsonFile<SyncLockMetadata>(join(lockDir, "owner.json"));
        assertBusinessOwnership(current, metadata.ownerId);
        await atomicWriteJson(join(lockDir, "heartbeat.json"), {
          ownerId: metadata.ownerId,
          heartbeatAt: new Date().toISOString(),
        });
      } finally {
        await guard.release();
      }
    },
    async release() {
      const guard = await acquireMutationGuard(lockDir, staleMs);
      try {
        const current = await readJsonFile<SyncLockMetadata>(join(lockDir, "owner.json"));
        assertBusinessOwnership(current, metadata.ownerId);
        await rm(lockDir, { recursive: true, force: true });
      } finally {
        await guard.release();
      }
    },
  };
}

interface MutationGuardMetadata {
  ownerId: string;
  pid: number;
  startedAt: string;
  lockDir: string;
}

interface GuardSnapshot {
  raw: string | null;
  metadata: MutationGuardMetadata | null;
  mtimeMs: number | null;
}

interface RecoveryClaimMetadata {
  claimId: string;
  pid: number;
  startedAt: string;
  lockDir: string;
}

async function readGuardSnapshot(guardDir: string): Promise<GuardSnapshot> {
  let mtimeMs: number | null = null;
  try {
    mtimeMs = (await stat(guardDir)).mtimeMs;
  } catch {
    // The guard disappeared before inspection.
  }
  try {
    const raw = await readFile(join(guardDir, "owner.json"), "utf8");
    try {
      return { raw, metadata: JSON.parse(raw) as MutationGuardMetadata, mtimeMs };
    } catch {
      return { raw, metadata: null, mtimeMs };
    }
  } catch {
    return { raw: null, metadata: null, mtimeMs };
  }
}

async function readBusinessLock(lockDir: string): Promise<SyncLockMetadata | null> {
  const owner = await readJsonFile<SyncLockMetadata>(join(lockDir, "owner.json"));
  if (!owner) return null;
  const heartbeat = await readJsonFile<{ ownerId?: unknown; heartbeatAt?: unknown }>(
    join(lockDir, "heartbeat.json"),
  );
  if (
    heartbeat?.ownerId === owner.ownerId &&
    typeof heartbeat?.heartbeatAt === "string"
  ) {
    return { ...owner, heartbeatAt: heartbeat.heartbeatAt };
  }
  return owner;
}

async function syncPathExists(path: string): Promise<boolean> {
  try {
    await stat(path);
    return true;
  } catch {
    return false;
  }
}

function guardSnapshotMatches(left: GuardSnapshot, right: GuardSnapshot): boolean {
  return left.raw === right.raw && left.mtimeMs === right.mtimeMs;
}

function guardIsActive(snapshot: GuardSnapshot, staleMs: number): boolean {
  if (snapshot.metadata) {
    const startedMs = Date.parse(snapshot.metadata.startedAt);
    const fresh = Number.isFinite(startedMs) && Date.now() - startedMs < staleMs;
    return isProcessAlive(snapshot.metadata.pid) || fresh;
  }
  return snapshot.mtimeMs !== null && Date.now() - snapshot.mtimeMs < staleMs;
}

async function waitForGuardRetry(): Promise<void> {
  await new Promise<void>((resolve) => setTimeout(resolve, 2));
}

function recoveryActivePath(guardDir: string): string {
  return `${guardDir}.recovery-active.json`;
}

function recoveryClaimPath(guardDir: string, claimId: string): string {
  return `${guardDir}.recovery-${claimId}.json`;
}

function recoveredGuardPath(guardDir: string, claimId: string): string {
  return `${guardDir}.recovered-${claimId}`;
}

async function readRecoverySnapshot(
  path: string,
): Promise<{ raw: string | null; metadata: RecoveryClaimMetadata | null; mtimeMs: number | null }> {
  let mtimeMs: number | null = null;
  try {
    mtimeMs = (await stat(path)).mtimeMs;
  } catch {
    return { raw: null, metadata: null, mtimeMs: null };
  }
  try {
    const raw = await readFile(path, "utf8");
    try {
      return { raw, metadata: JSON.parse(raw) as RecoveryClaimMetadata, mtimeMs };
    } catch {
      return { raw, metadata: null, mtimeMs };
    }
  } catch {
    return { raw: null, metadata: null, mtimeMs };
  }
}

function recoverySnapshotIsActive(
  snapshot: { metadata: RecoveryClaimMetadata | null; mtimeMs: number | null },
  staleMs: number,
): boolean {
  if (snapshot.metadata) {
    const startedMs = Date.parse(snapshot.metadata.startedAt);
    const fresh = Number.isFinite(startedMs) && Date.now() - startedMs < staleMs;
    return isProcessAlive(snapshot.metadata.pid) || fresh;
  }
  return snapshot.mtimeMs !== null && Date.now() - snapshot.mtimeMs < staleMs;
}

async function listRecoveryClaimPaths(guardDir: string): Promise<string[]> {
  const directory = dirname(guardDir);
  const prefix = `${basename(guardDir)}.recovery-`;
  const activeName = basename(recoveryActivePath(guardDir));
  let entries: string[];
  try {
    entries = await readdir(directory);
  } catch {
    return [];
  }
  return entries
    .filter((entry) => entry !== activeName && entry.startsWith(prefix) && entry.endsWith(".json"))
    .map((entry) => join(directory, entry))
    .sort((left, right) => left.localeCompare(right));
}

async function cleanupAbandonedClaim(
  guardDir: string,
  path: string,
  metadata: RecoveryClaimMetadata | null,
): Promise<void> {
  if (metadata) {
    await rm(recoveredGuardPath(guardDir, metadata.claimId), { recursive: true, force: true });
  }
  await rm(path, { force: true });
}

async function listLiveRecoveryClaims(guardDir: string, staleMs: number): Promise<string[]> {
  const live: string[] = [];
  for (const path of await listRecoveryClaimPaths(guardDir)) {
    const snapshot = await readRecoverySnapshot(path);
    if (recoverySnapshotIsActive(snapshot, staleMs)) {
      live.push(path);
    } else {
      await cleanupAbandonedClaim(guardDir, path, snapshot.metadata);
    }
  }
  return live.sort((left, right) => left.localeCompare(right));
}

async function releaseRecoveryFence(
  guardDir: string,
  metadata: RecoveryClaimMetadata,
): Promise<void> {
  const activePath = recoveryActivePath(guardDir);
  const releasePath = `${activePath}.release-${randomUUID()}`;
  try {
    await rename(activePath, releasePath);
  } catch {
    throw new Error("sync_lock_recovery_ownership_lost");
  }
  const current = await readRecoverySnapshot(releasePath);
  if (!current.metadata || current.metadata.claimId !== metadata.claimId) {
    try {
      await rename(releasePath, activePath);
    } catch {
      // Never overwrite a newer recovery owner.
    }
    throw new Error("sync_lock_recovery_ownership_lost");
  }
  await rm(releasePath, { force: true });
  await rm(recoveryClaimPath(guardDir, metadata.claimId), { force: true });
}

async function acquireRecoveryFence(
  guardDir: string,
  lockDir: string,
  staleMs: number,
): Promise<{ claimId: string; release(): Promise<void> } | null> {
  const claimId = randomUUID();
  const metadata: RecoveryClaimMetadata = {
    claimId,
    pid: process.pid,
    startedAt: new Date().toISOString(),
    lockDir,
  };
  const ownPath = recoveryClaimPath(guardDir, claimId);
  await atomicWriteJson(ownPath, metadata);

  const liveClaims = await listLiveRecoveryClaims(guardDir, staleMs);
  if (liveClaims[0] !== ownPath) {
    await rm(ownPath, { force: true });
    return null;
  }

  const activePath = recoveryActivePath(guardDir);
  const active = await readRecoverySnapshot(activePath);
  if (active.mtimeMs !== null) {
    if (recoverySnapshotIsActive(active, staleMs)) {
      await rm(ownPath, { force: true });
      return null;
    }
    const abandonedPath = `${activePath}.abandoned-${randomUUID()}`;
    try {
      await rename(activePath, abandonedPath);
    } catch {
      await rm(ownPath, { force: true });
      return null;
    }
    const claimedActive = await readRecoverySnapshot(abandonedPath);
    if (
      claimedActive.raw !== active.raw ||
      claimedActive.mtimeMs !== active.mtimeMs ||
      recoverySnapshotIsActive(claimedActive, staleMs)
    ) {
      try {
        await rename(abandonedPath, activePath);
      } catch {
        // A newer active recovery exists; preserve its unique predecessor.
      }
      await rm(ownPath, { force: true });
      return null;
    }
    await cleanupAbandonedClaim(
      guardDir,
      recoveryClaimPath(guardDir, claimedActive.metadata?.claimId ?? "unknown"),
      claimedActive.metadata,
    );
    await rm(abandonedPath, { force: true });
  }

  const finalClaims = await listLiveRecoveryClaims(guardDir, staleMs);
  if (finalClaims[0] !== ownPath) {
    await rm(ownPath, { force: true });
    return null;
  }
  try {
    await link(ownPath, activePath);
  } catch {
    await rm(ownPath, { force: true });
    return null;
  }
  return {
    claimId,
    release: () => releaseRecoveryFence(guardDir, metadata),
  };
}

async function withRecoveryFence<T>(
  guardDir: string,
  lockDir: string,
  staleMs: number,
  operation: (claimId: string) => Promise<T>,
): Promise<T> {
  for (;;) {
    const fence = await acquireRecoveryFence(guardDir, lockDir, staleMs);
    if (!fence) {
      await waitForGuardRetry();
      continue;
    }
    try {
      return await operation(fence.claimId);
    } finally {
      await fence.release();
    }
  }
}

async function recoveryFenceIsClear(
  guardDir: string,
  lockDir: string,
  staleMs: number,
): Promise<boolean> {
  const active = await readRecoverySnapshot(recoveryActivePath(guardDir));
  if (active.mtimeMs !== null) {
    if (recoverySnapshotIsActive(active, staleMs)) return false;
    const recovered = await acquireRecoveryFence(guardDir, lockDir, staleMs);
    if (recovered) await recovered.release();
    return false;
  }
  return (await listLiveRecoveryClaims(guardDir, staleMs)).length === 0;
}

async function releaseMutationGuard(
  guardDir: string,
  lockDir: string,
  staleMs: number,
  ownerId: string,
): Promise<void> {
  await withRecoveryFence(guardDir, lockDir, staleMs, async () => {
    const claimDir = `${guardDir}.release-${process.pid}-${randomUUID()}`;
    for (;;) {
      try {
        await rename(guardDir, claimDir);
        break;
      } catch {
        const stillOwned = await readJsonFile<MutationGuardMetadata>(join(guardDir, "owner.json"));
        if (!stillOwned || stillOwned.ownerId !== ownerId) {
          throw new Error("sync_lock_guard_ownership_lost");
        }
        await waitForGuardRetry();
      }
    }
    const current = await readJsonFile<MutationGuardMetadata>(join(claimDir, "owner.json"));
    if (!current || current.ownerId !== ownerId) {
      try {
        await rename(claimDir, guardDir);
      } catch {
        // Never overwrite a newer guard owner.
      }
      throw new Error("sync_lock_guard_ownership_lost");
    }
    await rm(claimDir, { recursive: true, force: true });
  });
}

async function recoverStaleGuard(
  guardDir: string,
  lockDir: string,
  staleMs: number,
): Promise<MutationGuardMetadata | null> {
  return withRecoveryFence(guardDir, lockDir, staleMs, async (claimId) => {
    const observed = await readGuardSnapshot(guardDir);
    if (guardIsActive(observed, staleMs)) return null;
    const movedPath = recoveredGuardPath(guardDir, claimId);
    try {
      await rename(guardDir, movedPath);
    } catch {
      return null;
    }
    const moved = await readGuardSnapshot(movedPath);
    if (guardSnapshotMatches(observed, moved) && !guardIsActive(moved, staleMs)) {
      await rm(movedPath, { recursive: true, force: true });
      const metadata = makeMutationGuardMetadata(lockDir);
      await mkdir(guardDir);
      try {
        await atomicWriteJson(join(guardDir, "owner.json"), metadata);
      } catch (error) {
        await rm(guardDir, { recursive: true, force: true });
        throw error;
      }
      return metadata;
    }
    try {
      await rename(movedPath, guardDir);
    } catch {
      // The recovery fence prevents a normal replacement; preserve unexpected state.
    }
    return null;
  });
}

function makeMutationGuardMetadata(lockDir: string): MutationGuardMetadata {
  return {
    ownerId: randomUUID(),
    pid: process.pid,
    startedAt: new Date().toISOString(),
    lockDir,
  };
}

async function acquireMutationGuard(lockDir: string, staleMs: number): Promise<{
  release(): Promise<void>;
}> {
  const guardDir = `${lockDir}.guard`;
  for (;;) {
    if (!(await recoveryFenceIsClear(guardDir, lockDir, staleMs))) {
      await waitForGuardRetry();
      continue;
    }
    const metadata = makeMutationGuardMetadata(lockDir);
    try {
      await mkdir(guardDir);
    } catch (error) {
      if (!isAlreadyExists(error)) throw error;
      const recovered = await recoverStaleGuard(guardDir, lockDir, staleMs);
      if (recovered) {
        return {
          release: () => releaseMutationGuard(
            guardDir,
            lockDir,
            staleMs,
            recovered.ownerId,
          ),
        };
      }
      await waitForGuardRetry();
      continue;
    }
    try {
      await atomicWriteJson(join(guardDir, "owner.json"), metadata);
    } catch (error) {
      await rm(guardDir, { recursive: true, force: true });
      throw error;
    }
    if (!(await recoveryFenceIsClear(guardDir, lockDir, staleMs))) {
      await releaseMutationGuard(guardDir, lockDir, staleMs, metadata.ownerId);
      await waitForGuardRetry();
      continue;
    }
    return {
      release: () => releaseMutationGuard(guardDir, lockDir, staleMs, metadata.ownerId),
    };
  }
}

function isAlreadyExists(error: unknown): boolean {
  return typeof error === "object" && error !== null && "code" in error && error.code === "EEXIST";
}

function assertBusinessOwnership(
  metadata: SyncLockMetadata | null,
  expectedOwnerId: string,
): asserts metadata is SyncLockMetadata {
  if (!metadata || metadata.ownerId !== expectedOwnerId) {
    throw new Error("sync_lock_ownership_lost");
  }
}

function isFreshLock(metadata: SyncLockMetadata, staleMs: number): boolean {
  const heartbeatMs = Date.parse(metadata.heartbeatAt);
  const heartbeatFresh = Number.isFinite(heartbeatMs) && Date.now() - heartbeatMs < staleMs;
  return isProcessAlive(metadata.pid) || heartbeatFresh;
}

function isProcessAlive(pid: number): boolean {
  if (!Number.isInteger(pid) || pid <= 0) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

function quietMarkerPath(projectRoot: string, path: string): string {
  return join(projectRoot, QUIET_DIR_RELATIVE_PATH, `${hashText(path)}.json`);
}

function hashText(value: string): string {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

async function writeSnapshotSide(
  dir: string,
  side: "base" | "local" | "remote",
  files: Record<string, string | Uint8Array | null | undefined> | undefined,
): Promise<void> {
  if (!files) return;
  for (const [path, content] of Object.entries(files)) {
    if (content === null || content === undefined) continue;
    const reason = validateSyncPath(path);
    if (reason) throw new Error(`invalid_path:${reason}:${path}`);
    const target = join(dir, side, path);
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, content);
  }
}

function statusFor(input: {
  conflicts: SyncConflict[];
  upload: string[];
  download: string[];
  deleteLocal: string[];
}): ReconcilePlan["status"] {
  if (input.conflicts.length > 0) return "conflict";
  const hasLocal = input.upload.length > 0;
  const hasRemote = input.download.length > 0 || input.deleteLocal.length > 0;
  if (hasLocal && hasRemote) return "merge";
  if (hasLocal) return "push";
  if (hasRemote) return "pull";
  return "clean";
}

function validatePathSet(
  source: string,
  paths: string[],
): SyncConflict[] {
  const out: SyncConflict[] = [];
  for (const path of paths) {
    const reason = validateSyncPath(path);
    if (reason) {
      out.push({
        path,
        kind: "invalid-path",
        details: `${source}:${reason}`,
      });
    }
  }
  return out;
}

function caseCollisionConflicts(paths: string[]): SyncConflict[] {
  const byFolded = new Map<string, string[]>();
  for (const path of paths) {
    const folded = path.normalize("NFC").toLocaleLowerCase("en-US");
    const list = byFolded.get(folded) ?? [];
    list.push(path);
    byFolded.set(folded, list);
  }

  const out: SyncConflict[] = [];
  for (const pathsForKey of byFolded.values()) {
    const unique = Array.from(new Set(pathsForKey));
    if (unique.length <= 1) continue;
    for (const path of unique) {
      out.push({
        path,
        kind: "case-collision",
        details: unique.sort().join(" | "),
      });
    }
  }
  return out;
}

function sortedUnion(...sets: string[][]): string[] {
  return Array.from(new Set(sets.flat())).sort();
}
