/**
 * Tool: `search_project` (Rodada 21B; Rodada 22F: hub + slugs).
 *
 * Lista/filtra projected content do project identificado por `(ws_slug,
 * proj_slug)`. Resolve UUIDs via `.conversion-hub.json` e repassa filtros
 * para `GET /content?type=&status=&query=`. Thin passthrough.
 */
import {
  authenticatedJson,
  authenticatedJsonAt,
  BackendError,
  NetworkError,
  NotAuthenticatedError,
  RateLimitedError,
  SessionExpiredError,
} from "../lib/api.js";
import { PROJECT_SCOPE_SCHEMA_FRAGMENT, resolveProjectScope } from "../lib/project-scope.js";

export interface SearchProjectInput {
  ws_slug: string;
  proj_slug: string;
  type?: string;
  status?: string;
  query?: string;
  limit?: number;
}

export interface SearchProjectItem {
  path: string;
  type: string;
  slug: string;
  title: string | null;
  status: string | null;
  frontmatter: unknown;
  updatedAt: string;
}

export type SearchProjectOutput =
  | { ok: true; items: SearchProjectItem[]; total: number }
  | {
      ok: false;
      error:
        | "not_authenticated"
        | "session_expired"
        | "rate_limited"
        | "not_in_hub"
        | "project_not_in_hub"
        | "backend_error"
        | "network_error"
        | "bad_input"
        | "unknown_error";
      hint?: string;
      retry_after_sec?: number;
    };

const VALID_TYPES: ReadonlySet<string> = new Set([
  "artigo",
  "cluster",
  "factcheck_dossier",
  "otimizacao_on_page",
  "newsletter",
  "relatorio",
  "brain.tom_voz",
  "brain.glossario",
  "brain.fontes",
  "brain.decisoes",
  "brain.aprendizados",
  "brain.personas",
  "brain.provas",
]);

export const SEARCH_PROJECT_INPUT_SCHEMA = {
  type: "object",
  properties: {
    ...PROJECT_SCOPE_SCHEMA_FRAGMENT,
    type: {
      type: "string",
      description: "Filter by collection type (e.g. 'artigo', 'cluster').",
      enum: Array.from(VALID_TYPES),
    },
    status: {
      type: "string",
      description:
        "Filter by status (schema-specific: 'active' for clusters, 'finalizado' for articles, etc.).",
    },
    query: {
      type: "string",
      description: "Full-text search (Portuguese) against title + body_preview.",
    },
    limit: {
      type: "number",
      description: "Maximum number of items to return (default 50, max 200).",
      minimum: 1,
      maximum: 200,
    },
  },
  required: ["ws_slug", "proj_slug"],
  additionalProperties: false,
} as const;

function buildQuery(input: SearchProjectInput): string {
  const qs = new URLSearchParams();
  if (typeof input.type === "string" && input.type.length > 0) {
    qs.set("type", input.type);
  }
  if (typeof input.status === "string" && input.status.length > 0) {
    qs.set("status", input.status);
  }
  if (typeof input.query === "string" && input.query.trim().length > 0) {
    qs.set("query", input.query.trim());
  }
  if (typeof input.limit === "number" && Number.isFinite(input.limit)) {
    qs.set("limit", String(Math.max(1, Math.min(200, Math.trunc(input.limit)))));
  }
  const s = qs.toString();
  return s ? `?${s}` : "";
}

export async function runSearchProject(
  input: SearchProjectInput,
  cwd: string = process.cwd(),
  target: { backendUrl?: string; hubFile?: string; materializeTool?: string } = {},
): Promise<SearchProjectOutput> {
  if (input && typeof input !== "object") {
    return { ok: false, error: "bad_input", hint: "Input must be an object." };
  }
  if (input.type && !VALID_TYPES.has(input.type)) {
    return {
      ok: false,
      error: "bad_input",
      hint: `Unknown type '${input.type}'. Allowed: ${Array.from(VALID_TYPES).join(", ")}.`,
    };
  }

  const scope = await resolveProjectScope(input, cwd, target.hubFile, target.materializeTool);
  if (!scope.ok) return scope;

  try {
    const path = `/api/v1/ws/${scope.ws_id}/projects/${scope.proj_id}/content${buildQuery(input)}`;
    const body = target.backendUrl
      ? await authenticatedJsonAt<{
          items: SearchProjectItem[];
          total: number;
        }>(target.backendUrl, path, { method: "GET" })
      : await authenticatedJson<{
          items: SearchProjectItem[];
          total: number;
        }>(path, { method: "GET" });
    return { ok: true, items: body.items, total: body.total };
  } catch (err) {
    return mapError(err);
  }
}

function mapError(err: unknown): SearchProjectOutput {
  if (err instanceof NotAuthenticatedError) {
    return {
      ok: false,
      error: err.code,
      hint: "Use the `auth_login_start` MCP tool (then `auth_login_poll`) first.",
    };
  }
  if (err instanceof SessionExpiredError) {
    return {
      ok: false,
      error: err.code,
      hint: "Use the `auth_login_start` MCP tool (then `auth_login_poll`) to renew your session.",
    };
  }
  if (err instanceof RateLimitedError) {
    return {
      ok: false,
      error: err.code,
      hint: `Rate limit (${err.scope}) — retry after ${err.retryAfterSec}s.`,
      retry_after_sec: err.retryAfterSec,
    };
  }
  if (err instanceof NetworkError) {
    return { ok: false, error: err.code, hint: err.detail };
  }
  if (err instanceof BackendError) {
    return {
      ok: false,
      error: err.code,
      hint: `HTTP ${err.status}: ${err.detail.slice(0, 200)}`,
    };
  }
  return {
    ok: false,
    error: "unknown_error",
    hint: err instanceof Error ? err.message : String(err),
  };
}
