/**
 * Project-scope resolver — shared across project-scoped MCP tools
 * (Rodada 22F).
 *
 * O contrato novo: toda chamada project-scoped (read_brain, get_content,
 * search_project, get_backlinks, project_save_and_url, project_save_batch)
 * recebe `ws_slug` + `proj_slug` explícitos. Este módulo valida a
 * presença dos slugs + resolve `(ws_slug, proj_slug)` contra o
 * `.conversion-hub.json` do hub ancestral do CWD.
 *
 * Retorna um envelope tipado que os handlers repassam verbatim em caso
 * de falha.
 */
import { HUB_FILE, findHubRoot, resolveProjectFromHub } from "./hub.js";

export interface ProjectScopeInput {
  ws_slug?: unknown;
  proj_slug?: unknown;
}

export type ProjectScopeResult =
  | {
      ok: true;
      ws_slug: string;
      proj_slug: string;
      ws_id: string;
      proj_id: string;
      project_root: string;
      hub_root: string;
    }
  | {
      ok: false;
      error:
        | "bad_input"
        | "not_in_hub"
        | "project_not_in_hub";
      hint: string;
    };

/**
 * Valida ws/proj slugs no input e resolve-os via hub. Deve ser chamado
 * antes de qualquer lookup no backend — todos os endpoints project-scoped
 * dependem dos UUIDs resolvidos aqui.
 */
export async function resolveProjectScope(
  input: ProjectScopeInput,
  cwd: string = process.cwd(),
  hubFile: string = HUB_FILE,
  materializeTool = "materialize_project",
): Promise<ProjectScopeResult> {
  if (!input || typeof input !== "object") {
    return {
      ok: false,
      error: "bad_input",
      hint: "Input deve ser um objeto com campos 'ws_slug' e 'proj_slug'.",
    };
  }
  const ws = input.ws_slug;
  const proj = input.proj_slug;
  if (typeof ws !== "string" || ws.length === 0) {
    return {
      ok: false,
      error: "bad_input",
      hint: "Campo 'ws_slug' (string) é obrigatório.",
    };
  }
  if (typeof proj !== "string" || proj.length === 0) {
    return {
      ok: false,
      error: "bad_input",
      hint: "Campo 'proj_slug' (string) é obrigatório.",
    };
  }

  const hubRoot = await findHubRoot(cwd, hubFile);
  if (!hubRoot) {
    return {
      ok: false,
      error: "not_in_hub",
      hint:
        `Não encontrei ${hubFile}. Certifique-se de abrir o Claude Code dentro de um hub (pasta materializada com a ferramenta \`${materializeTool}\`).`,
    };
  }
  const resolved = await resolveProjectFromHub(hubRoot, ws, proj, hubFile);
  if (!resolved) {
    return {
      ok: false,
      error: "project_not_in_hub",
      hint: `Project '${ws}/${proj}' não está neste hub. Use a ferramenta \`${materializeTool}\` primeiro.`,
    };
  }
  return {
    ok: true,
    ws_slug: ws,
    proj_slug: proj,
    ws_id: resolved.ws_id,
    proj_id: resolved.proj_id,
    project_root: resolved.absolute_path,
    hub_root: hubRoot,
  };
}

/**
 * JSON Schema fragment com `ws_slug` + `proj_slug` required —
 * reutilizado por todas as 6 tools project-scoped.
 */
export const PROJECT_SCOPE_SCHEMA_FRAGMENT = {
  ws_slug: {
    type: "string",
    description:
      "Workspace slug do project-ativo (ex: 'acme'). O orquestrador passa explicitamente — nunca infira.",
    minLength: 1,
  },
  proj_slug: {
    type: "string",
    description:
      "Project slug do project-ativo (ex: 'site-institucional'). O orquestrador passa explicitamente — nunca infira.",
    minLength: 1,
  },
} as const;
