/**
 * Tool: `project_save_batch` (Rodada 21B, ADR-012 §5; Rodada 22F: hub + slugs).
 *
 * Atomic multi-file commit no project identificado por `(ws_slug, proj_slug)`.
 * O orquestrador passa ambos os slugs explicitamente; a tool resolve via
 * hub, lê manifest local no `<hub>/<ws>/<proj>/.conversion/manifest.json`
 * e posta `/commits/batch`.
 */
import { mkdir, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";

import {
  acquireSyncLock,
  deterministicCommitId,
  type SyncLock,
} from "@agenciaconversion/local-sync";

import { BACKEND_URL, backendProtectionHeaders } from "../lib/config.js";
import { getToken, savePluginAuth, type StoredCredential } from "../lib/keychain.js";
import { manifestMatchesProjectScope, readProjectManifestSnapshot } from "../lib/project-commit.js";
import {
  assertValidProjectPath,
  canonicalTreeJson,
  canonicalizeText,
  inferMime,
  InvalidProjectPathError,
  isTextMime,
  sha256Hex,
  type Manifest,
} from "../lib/project-save-helpers.js";
import { PROJECT_SCOPE_SCHEMA_FRAGMENT, resolveProjectScope } from "../lib/project-scope.js";

const MANIFEST_FILE = ".conversion/manifest.json";

export interface BatchFileInput {
  path: string;
  content: string;
}

export interface ProjectSaveBatchInput {
  ws_slug: string;
  proj_slug: string;
  files: BatchFileInput[];
  message?: string;
}

export type ProjectSaveBatchOutput =
  | {
      ok: true;
      url: string;
      commit_id: string;
      tree_hash: string;
      files: Array<{ path: string; sha256: string }>;
    }
  | {
      ok: false;
      error:
        | "not_authenticated"
        | "not_in_hub"
        | "project_not_in_hub"
        | "invalid_manifest"
        | "invalid_path"
        | "binary_not_supported"
        | "conflict"
        | "backend_error"
        | "network_error"
        | "bad_input";
      hint?: string;
      server_head?: { commitId: string; treeHash: string } | null;
    };

export const PROJECT_SAVE_BATCH_INPUT_SCHEMA = {
  type: "object",
  properties: {
    ...PROJECT_SCOPE_SCHEMA_FRAGMENT,
    files: {
      type: "array",
      description:
        "Files to commit. Each entry carries the project-relative path (no leading `/`, no `..`) and the UTF-8 text content.",
      minItems: 1,
      maxItems: 200,
      items: {
        type: "object",
        properties: {
          path: {
            type: "string",
            description: "Project-relative path (e.g. 'deliverables/clusters/seo-local.md').",
          },
          content: {
            type: "string",
            description: "File content as UTF-8 text.",
          },
        },
        required: ["path", "content"],
        additionalProperties: false,
      },
    },
    message: {
      type: "string",
      description: "Optional commit message (max 2000 chars).",
    },
  },
  required: ["ws_slug", "proj_slug", "files"],
  additionalProperties: false,
} as const;

async function authedFetch(
  cred: StoredCredential,
  url: string,
  init: RequestInit,
): Promise<Response> {
  const headers = {
    authorization: `Bearer ${cred.token}`,
    accept: "application/json",
    ...backendProtectionHeaders(),
    ...(init.headers as Record<string, string> | undefined),
  };
  const res = await fetch(url, { ...init, headers });
  const renewed = res.headers.get("x-renewed-token");
  if (renewed) {
    await savePluginAuth({ email: cred.email, token: renewed });
  }
  return res;
}

export async function runProjectSaveBatch(
  input: ProjectSaveBatchInput,
  cwd: string = process.cwd(),
  target: {
    backendUrl?: string;
    hubFile?: string;
    materializeTool?: string;
    backendTarget?: "legacy" | "searchhub";
  } = {},
): Promise<ProjectSaveBatchOutput> {
  const backendUrl = target.backendUrl ?? BACKEND_URL;
  if (!input || !Array.isArray(input.files) || input.files.length === 0) {
    return {
      ok: false,
      error: "bad_input",
      hint: "Field 'files' is required (non-empty array).",
    };
  }
  if (input.files.length > 200) {
    return {
      ok: false,
      error: "bad_input",
      hint: "Batch too large: max 200 files per commit.",
    };
  }
  for (const f of input.files) {
    if (!f || typeof f.path !== "string" || typeof f.content !== "string") {
      return {
        ok: false,
        error: "bad_input",
        hint: "Every file must have 'path' (string) and 'content' (string).",
      };
    }
  }

  for (const f of input.files) {
    try {
      assertValidProjectPath(f.path);
    } catch (err) {
      if (err instanceof InvalidProjectPathError) {
        return {
          ok: false,
          error: "invalid_path",
          hint: `Path rejected: ${err.reason} (${f.path})`,
        };
      }
      return { ok: false, error: "invalid_path", hint: String(err) };
    }
  }

  const scope = await resolveProjectScope(input, cwd, target.hubFile, target.materializeTool);
  if (!scope.ok) return scope;

  let acquiredLock: SyncLock | null;
  try {
    acquiredLock = await acquireSyncLock({
      projectRoot: scope.project_root,
      owner: "mcp-project-save-batch",
    });
  } catch {
    return {
      ok: false,
      error: "conflict",
      hint: "Could not acquire the project sync lock; retry after the active operation releases it.",
    };
  }
  if (!acquiredLock) {
    return {
      ok: false,
      error: "conflict",
      hint: "Project sync is busy; retry after the active operation releases its project lock.",
    };
  }

  try {
    const projectRoot = scope.project_root;
    const snapshot = await readProjectManifestSnapshot(projectRoot);
    if (!snapshot) {
      return {
        ok: false,
        error: "invalid_manifest",
        hint: `\`.conversion/manifest.json\` is missing or malformed. Use the \`${target.materializeTool ?? "materialize_project"}\` MCP tool again.`,
      };
    }
    const backendTarget = target.backendTarget ?? "legacy";
    const materializeTool =
      target.materializeTool ??
      (backendTarget === "searchhub" ? "searchhub_materialize_project" : "materialize_project");
    if (
      !manifestMatchesProjectScope(snapshot.manifest, {
        wsId: scope.ws_id,
        projId: scope.proj_id,
        wsSlug: input.ws_slug,
        projSlug: input.proj_slug,
        backendTarget,
      })
    ) {
      return {
        ok: false,
        error: "conflict",
        hint: `The local project snapshot belongs to another scope; use the \`${materializeTool}\` MCP tool and try again.`,
      };
    }
    const manifest = snapshot.manifest;

    const cred = await getToken();
    if (!cred) {
      return {
        ok: false,
        error: "not_authenticated",
        hint: "Use the `auth_login_start` MCP tool (then `auth_login_poll`) first.",
      };
    }

    // Canonicaliza + hasheia cada file. Rejeita binário.
    const processed: Array<{
      path: string;
      mime: string;
      canonical: Buffer;
      sha: string;
    }> = [];
    for (const f of input.files) {
      const mime = inferMime(f.path);
      if (!isTextMime(mime)) {
        return {
          ok: false,
          error: "binary_not_supported",
          hint: `Binary mime '${mime}' rejected for path ${f.path}; the batch route is text-only.`,
        };
      }
      const canonical = Buffer.from(canonicalizeText(Buffer.from(f.content, "utf8"), mime));
      processed.push({ path: f.path, mime, canonical, sha: sha256Hex(canonical) });
    }

    const nextTree: Record<string, string> = {};
    for (const [p, meta] of Object.entries(manifest.files)) {
      nextTree[p] = meta.sha256;
    }
    for (const p of processed) {
      nextTree[p.path] = p.sha;
    }
    const nextTreeHash = sha256Hex(Buffer.from(canonicalTreeJson(nextTree), "utf8"));

    const batchBody = {
      parent_tree_hash: manifest.commitId ? manifest.treeHash : null,
      parent_commit_id: manifest.commitId ?? null,
      client_commit_id: deterministicCommitId({
        projectId: manifest.projectId,
        actorUserId: cred.email,
        syncClientId: "mcp-project-save-batch",
        parentCommitId: manifest.commitId,
        parentTreeHash: manifest.commitId ? manifest.treeHash : null,
        treeHash: nextTreeHash,
        message: input.message ?? null,
      }),
      files: input.files.map((f) => ({ path: f.path, content: f.content })),
      ...(input.message ? { message: input.message } : {}),
    };

    let res: Response;
    try {
      res = await authedFetch(
        cred,
        `${backendUrl}/api/v1/ws/${scope.ws_id}/projects/${scope.proj_id}/commits/batch`,
        {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify(batchBody),
        },
      );
    } catch (err) {
      return {
        ok: false,
        error: "network_error",
        hint: err instanceof Error ? err.message : String(err),
      };
    }

    if (res.status === 409) {
      let serverHead: { commitId: string; treeHash: string } | null = null;
      try {
        const body = (await res.json()) as {
          server_head?: { commitId: string; treeHash: string } | null;
        };
        serverHead = body.server_head ?? null;
      } catch {
        /* keep null */
      }
      return {
        ok: false,
        error: "conflict",
        hint: `Project head moved; use the \`${materializeTool}\` MCP tool and retry.`,
        server_head: serverHead,
      };
    }

    if (!res.ok) {
      const text = await res.text().catch(() => "");
      return {
        ok: false,
        error: "backend_error",
        hint: `Commit batch failed (HTTP ${res.status}): ${text.slice(0, 200)}`,
      };
    }

    let commit: {
      id: string;
      treeHash: string;
      parentId: string | null;
      createdAt: string;
    };
    try {
      const parsed = (await res.json()) as {
        commit: {
          id: string;
          treeHash: string;
          parentId: string | null;
          createdAt: string;
        };
      };
      commit = parsed.commit;
    } catch (err) {
      return {
        ok: false,
        error: "backend_error",
        hint: err instanceof Error ? err.message : String(err),
      };
    }

    // Mirror bytes em disco + atualiza manifest. Erros não são fatais.
    try {
      for (const p of processed) {
        const abs = join(projectRoot, p.path);
        await mkdir(dirname(abs), { recursive: true });
        await writeFile(abs, p.canonical);
      }
    } catch (err) {
      process.stderr.write(
        `[conversion-mcp] batch: failed to mirror local file: ${err instanceof Error ? err.message : String(err)}\n`,
      );
    }

    const nextFiles: Manifest["files"] = { ...manifest.files };
    for (const p of processed) {
      nextFiles[p.path] = {
        sha256: p.sha,
        size: p.canonical.length,
        mime: p.mime,
      };
    }
    const nextManifest: Manifest = {
      ...manifest,
      treeHash: commit.treeHash,
      commitId: commit.id,
      updatedAt: new Date().toISOString(),
      files: nextFiles,
    };
    try {
      const manifestPath = join(projectRoot, MANIFEST_FILE);
      await mkdir(dirname(manifestPath), { recursive: true });
      await writeFile(manifestPath, JSON.stringify(nextManifest, null, 2) + "\n", "utf8");
    } catch (err) {
      process.stderr.write(
        `[conversion-mcp] batch: failed to refresh manifest: ${err instanceof Error ? err.message : String(err)}\n`,
      );
    }

    const firstPath = processed[0]!.path;
    const url = `${backendUrl}/p/${scope.ws_id}/${scope.proj_id}/file/${firstPath}`;
    return {
      ok: true,
      url,
      commit_id: commit.id,
      tree_hash: commit.treeHash,
      files: processed.map((p) => ({ path: p.path, sha256: p.sha })),
    };
  } finally {
    try {
      await acquiredLock.release();
    } catch (error) {
      process.stderr.write(
        `[conversion-mcp] batch: lock release failed: ${error instanceof Error ? error.message : String(error)}\n`,
      );
    }
  }
}
