/**
 * Tool: `read_brain` (Rodada 21B, ADR-011 §5; Rodada 22F: hub + slugs).
 *
 * Returns the 8 brain files of the project identified by `(ws_slug,
 * proj_slug)`. Quando `collection` é omitido, retorna todos os brain
 * items; quando informado, apenas o tipo correspondente. Thin passthrough
 * sobre `GET /projects/:id/brain` + filtro client-side.
 *
 * O orquestrador deve passar `ws_slug` + `proj_slug` explicitamente —
 * o MCP server nunca infere project-ativo por CWD-walk.
 */
import {
  authenticatedJson,
  authenticatedJsonAt,
  BackendError,
  NetworkError,
  NotAuthenticatedError,
  RateLimitedError,
  SessionExpiredError,
} from "../lib/api.js";
import { PROJECT_SCOPE_SCHEMA_FRAGMENT, resolveProjectScope } from "../lib/project-scope.js";

const BRAIN_TYPES = [
  "brain.tom_voz",
  "brain.glossario",
  "brain.fontes",
  "brain.decisoes",
  "brain.aprendizados",
  "brain.personas",
  "brain.provas",
  "brain.produtos",
] as const;
type BrainType = (typeof BRAIN_TYPES)[number];

const VALID_BRAIN_TYPES: ReadonlySet<string> = new Set<string>(BRAIN_TYPES);

export interface ReadBrainInput {
  ws_slug: string;
  proj_slug: string;
  collection?: BrainType | string;
}

export interface BrainItem {
  type: string;
  title: string | null;
  body: string | null;
  frontmatter: unknown;
  updatedAt: string;
}

export type ReadBrainOutput =
  | { ok: true; items: BrainItem[] }
  | {
      ok: false;
      error:
        | "not_authenticated"
        | "session_expired"
        | "rate_limited"
        | "not_in_hub"
        | "project_not_in_hub"
        | "backend_error"
        | "network_error"
        | "bad_input"
        | "unknown_error";
      hint?: string;
      retry_after_sec?: number;
    };

export const READ_BRAIN_INPUT_SCHEMA = {
  type: "object",
  properties: {
    ...PROJECT_SCOPE_SCHEMA_FRAGMENT,
    collection: {
      type: "string",
      description: "Optional collection filter. Omit to receive all 8 brain files.",
      enum: [...BRAIN_TYPES],
    },
  },
  required: ["ws_slug", "proj_slug"],
  additionalProperties: false,
} as const;

export async function runReadBrain(
  input: ReadBrainInput,
  cwd: string = process.cwd(),
  target: { backendUrl?: string; hubFile?: string; materializeTool?: string } = {},
): Promise<ReadBrainOutput> {
  if (input && typeof input.collection === "string" && !VALID_BRAIN_TYPES.has(input.collection)) {
    return {
      ok: false,
      error: "bad_input",
      hint: `Unknown collection '${input.collection}'. Allowed: ${Array.from(VALID_BRAIN_TYPES).join(", ")}.`,
    };
  }

  const scope = await resolveProjectScope(
    input,
    cwd,
    target.hubFile,
    target.materializeTool,
  );
  if (!scope.ok) return scope;

  try {
    const path = `/api/v1/ws/${scope.ws_id}/projects/${scope.proj_id}/brain`;
    const body = target.backendUrl
      ? await authenticatedJsonAt<{ items: BrainItem[] }>(
          target.backendUrl,
          path,
          { method: "GET" },
        )
      : await authenticatedJson<{ items: BrainItem[] }>(path, { method: "GET" });
    const items =
      typeof input.collection === "string"
        ? body.items.filter((i) => i.type === input.collection)
        : body.items;
    return { ok: true, items };
  } catch (err) {
    return mapError(err);
  }
}

function mapError(err: unknown): ReadBrainOutput {
  if (err instanceof NotAuthenticatedError) {
    return {
      ok: false,
      error: err.code,
      hint: "Use the `auth_login_start` MCP tool (then `auth_login_poll`) first.",
    };
  }
  if (err instanceof SessionExpiredError) {
    return { ok: false, error: err.code, hint: "Session expired." };
  }
  if (err instanceof RateLimitedError) {
    return {
      ok: false,
      error: err.code,
      hint: `Retry after ${err.retryAfterSec}s.`,
      retry_after_sec: err.retryAfterSec,
    };
  }
  if (err instanceof NetworkError) {
    return { ok: false, error: err.code, hint: err.detail };
  }
  if (err instanceof BackendError) {
    return {
      ok: false,
      error: err.code,
      hint: `HTTP ${err.status}: ${err.detail.slice(0, 200)}`,
    };
  }
  return {
    ok: false,
    error: "unknown_error",
    hint: err instanceof Error ? err.message : String(err),
  };
}
