import ExcelJS from "exceljs";

import { normalizeOoxmlPackage } from "./deterministic-zip.js";

export interface SeoPlanRow {
  id: string;
  prioridade: "P0" | "P1" | "P2";
  elemento: string;
  recomendacao: string;
  motivo: string;
  status: string;
}

const INPUT_HEADERS = ["id", "prioridade", "elemento", "recomendacao", "motivo", "status"] as const;
const HEADERS = ["ID", "Prioridade", "Elemento", "Recomendação", "Motivo", "Status"] as const;
const KEYS = ["id", "prioridade", "elemento", "recomendacao", "motivo", "status"] as const;
const DEFAULT_CREATED_AT = "1980-01-01T00:00:00.000Z";

function cells(line: string): string[] {
  if (!line.trim().startsWith("|") || !line.trim().endsWith("|")) return [];
  return line
    .trim()
    .slice(1, -1)
    .split("|")
    .map((cell) => cell.trim());
}

export function parseSeoPlan(markdownBody: string): SeoPlanRow[] {
  const lines = markdownBody.replace(/\r\n?/gu, "\n").split("\n");
  const headerIndex = lines.findIndex(
    (line) => JSON.stringify(cells(line)) === JSON.stringify(INPUT_HEADERS),
  );
  if (headerIndex === -1) throw new Error("invalid_seo_plan");
  const separator = cells(lines[headerIndex + 1] ?? "");
  if (
    separator.length !== HEADERS.length ||
    !separator.every((cell) => /^:?-{3,}:?$/u.test(cell))
  ) {
    throw new Error("invalid_seo_plan");
  }

  const rows: SeoPlanRow[] = [];
  const ids = new Set<string>();
  for (const line of lines.slice(headerIndex + 2)) {
    if (!line.trim().startsWith("|")) {
      if (rows.length > 0 && line.trim() !== "") break;
      continue;
    }
    const values = cells(line);
    if (values.length !== HEADERS.length || values.some((value) => value.length === 0)) {
      throw new Error("invalid_seo_plan");
    }
    const [id, prioridade, elemento, recomendacao, motivo, status] = values as [
      string,
      string,
      string,
      string,
      string,
      string,
    ];
    if (ids.has(id) || (prioridade !== "P0" && prioridade !== "P1" && prioridade !== "P2")) {
      throw new Error("invalid_seo_plan");
    }
    ids.add(id);
    rows.push({ id, prioridade, elemento, recomendacao, motivo, status });
  }
  if (rows.length === 0) throw new Error("invalid_seo_plan");
  return rows;
}

export async function renderSeoPlanXlsx(
  rows: readonly SeoPlanRow[],
  createdAt = DEFAULT_CREATED_AT,
): Promise<Buffer> {
  const workbook = new ExcelJS.Workbook();
  const timestamp = new Date(createdAt);
  workbook.creator = "Conversion";
  workbook.lastModifiedBy = "Conversion";
  workbook.created = timestamp;
  workbook.modified = timestamp;
  const sheet = workbook.addWorksheet("Plano", {
    views: [{ state: "frozen", ySplit: 1 }],
  });
  sheet.columns = HEADERS.map((header, index) => ({
    header,
    key: KEYS[index],
    width: [16, 12, 20, 42, 42, 16][index],
  }));
  for (const row of rows) sheet.addRow(row);
  sheet.autoFilter = { from: "A1", to: "F1" };
  sheet.getRow(1).eachCell((cell) => {
    cell.font = { bold: true, color: { argb: "FFFFFFFF" } };
    cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF333333" } };
  });
  sheet.eachRow((row) => {
    row.eachCell((cell) => {
      cell.alignment = { vertical: "top", wrapText: true };
    });
  });
  const bytes = await workbook.xlsx.writeBuffer();
  return normalizeOoxmlPackage(new Uint8Array(bytes));
}
