/**
 * `brain.tom_voz` collection — brand voice memory.
 *
 * Lives at `brain/tom-voz.md`. One per project. Prepended as cacheable
 * prefix to every content skill prompt (ADR-011 §5).
 */

import { z } from "zod";

import { IsoDateTimeSchema } from "./_common.js";

export const BRAIN_TOM_VOZ_TYPE = "brain.tom_voz" as const;
export const BRAIN_TOM_VOZ_CONVENTIONAL_PATH = "brain/tom-voz.md" as const;

export const BrainTomVozFrontmatterSchema = z
  .object({
    title: z.string().min(1).max(300).default("Tom de voz"),
    type: z.literal(BRAIN_TOM_VOZ_TYPE),
    updated_at: IsoDateTimeSchema,
    sources: z.array(z.string().min(1).max(300)).optional(),
  })
  .strict();

export type BrainTomVozFrontmatter = z.infer<
  typeof BrainTomVozFrontmatterSchema
>;
