/**
 * Tool: `get_backlinks` (Rodada 21B, ADR-012 §3; Rodada 22F: hub + slugs).
 *
 * Returns every inbound wikilink or typed reference pointing to the
 * given slug inside the project identified by `(ws_slug, proj_slug)`.
 * Thin passthrough over `GET /content/:slug/backlinks`.
 */
import {
  authenticatedJson,
  authenticatedJsonAt,
  BackendError,
  NetworkError,
  NotAuthenticatedError,
  RateLimitedError,
  SessionExpiredError,
} from "../lib/api.js";
import {
  PROJECT_SCOPE_SCHEMA_FRAGMENT,
  resolveProjectScope,
} from "../lib/project-scope.js";

export interface GetBacklinksInput {
  ws_slug: string;
  proj_slug: string;
  slug: string;
}

export interface BacklinkItem {
  fromPath: string;
  fromSlug: string | null;
  fromTitle: string | null;
  relationType: string;
  orphan: boolean;
}

export type GetBacklinksOutput =
  | { ok: true; backlinks: BacklinkItem[] }
  | {
      ok: false;
      error:
        | "not_authenticated"
        | "session_expired"
        | "rate_limited"
        | "not_in_hub"
        | "project_not_in_hub"
        | "backend_error"
        | "network_error"
        | "bad_input"
        | "unknown_error";
      hint?: string;
      retry_after_sec?: number;
    };

const SLUG_REGEX = /^[a-z0-9][a-z0-9-]*$/u;

export const GET_BACKLINKS_INPUT_SCHEMA = {
  type: "object",
  properties: {
    ...PROJECT_SCOPE_SCHEMA_FRAGMENT,
    slug: {
      type: "string",
      description:
        "Slug of the target content item (e.g. 'cluster-seo-local' or 'artigo-inbound-b2b').",
      pattern: "^[a-z0-9][a-z0-9-]*$",
    },
  },
  required: ["ws_slug", "proj_slug", "slug"],
  additionalProperties: false,
} as const;

export async function runGetBacklinks(
  input: GetBacklinksInput,
  cwd: string = process.cwd(),
  target: { backendUrl?: string; hubFile?: string; materializeTool?: string } = {},
): Promise<GetBacklinksOutput> {
  if (!input || typeof input.slug !== "string") {
    return {
      ok: false,
      error: "bad_input",
      hint: "Field 'slug' is required (string).",
    };
  }
  const slug = input.slug.trim();
  if (!SLUG_REGEX.test(slug)) {
    return {
      ok: false,
      error: "bad_input",
      hint: `Invalid slug '${input.slug}'. Lowercase, alphanumerics and hyphens only.`,
    };
  }

  const scope = await resolveProjectScope(input, cwd, target.hubFile, target.materializeTool);
  if (!scope.ok) return scope;

  try {
    const path = `/api/v1/ws/${scope.ws_id}/projects/${scope.proj_id}/content/${encodeURIComponent(slug)}/backlinks`;
    const body = target.backendUrl
      ? await authenticatedJsonAt<{ backlinks: BacklinkItem[] }>(target.backendUrl, path, {
          method: "GET",
        })
      : await authenticatedJson<{ backlinks: BacklinkItem[] }>(path, { method: "GET" });
    return { ok: true, backlinks: body.backlinks };
  } catch (err) {
    return mapError(err);
  }
}

function mapError(err: unknown): GetBacklinksOutput {
  if (err instanceof NotAuthenticatedError) {
    return {
      ok: false,
      error: err.code,
      hint: "Use the `auth_login_start` MCP tool (then `auth_login_poll`) first.",
    };
  }
  if (err instanceof SessionExpiredError) {
    return { ok: false, error: err.code, hint: "Session expired." };
  }
  if (err instanceof RateLimitedError) {
    return {
      ok: false,
      error: err.code,
      hint: `Retry after ${err.retryAfterSec}s.`,
      retry_after_sec: err.retryAfterSec,
    };
  }
  if (err instanceof NetworkError) {
    return { ok: false, error: err.code, hint: err.detail };
  }
  if (err instanceof BackendError) {
    return {
      ok: false,
      error: err.code,
      hint: `HTTP ${err.status}: ${err.detail.slice(0, 200)}`,
    };
  }
  return {
    ok: false,
    error: "unknown_error",
    hint: err instanceof Error ? err.message : String(err),
  };
}
