/**
 * `brain.fontes` collection — project-specific source authority hierarchy
 * used by fact-checking.
 */

import { z } from "zod";

import { IsoDateTimeSchema } from "./_common.js";

export const BRAIN_FONTES_TYPE = "brain.fontes" as const;
export const BRAIN_FONTES_CONVENTIONAL_PATH = "brain/fontes.md" as const;

export const BrainFontesFrontmatterSchema = z
  .object({
    title: z.string().min(1).max(200),
    type: z.literal(BRAIN_FONTES_TYPE),
    updated_at: IsoDateTimeSchema,
  })
  .strict();

export type BrainFontesFrontmatter = z.infer<
  typeof BrainFontesFrontmatterSchema
>;
