/**
 * Tool: `project_save_and_url` (Rodada 22F: hub + slugs explícitos).
 *
 * O orquestrador passa `ws_slug` + `proj_slug` — a tool resolve via hub e
 * delega pro `runProjectSave` com o context já resolvido.
 */
import { PROJECT_SCOPE_SCHEMA_FRAGMENT, resolveProjectScope } from "../lib/project-scope.js";
import {
  runProjectSave,
  type ProjectSaveInput,
  type ProjectSaveOutput,
} from "../lib/project-save.js";

export interface ProjectSaveAndUrlInput extends ProjectSaveInput {
  ws_slug: string;
  proj_slug: string;
}

export type ProjectSaveAndUrlOutput =
  | ProjectSaveOutput
  | {
      ok: false;
      error: "not_in_hub" | "project_not_in_hub" | "bad_input";
      hint?: string;
    };

export const PROJECT_SAVE_AND_URL_INPUT_SCHEMA = {
  type: "object",
  properties: {
    ...PROJECT_SCOPE_SCHEMA_FRAGMENT,
    path: {
      type: "string",
      description:
        "Project-relative path (e.g. 'conteudo/briefing-x.md'). Must use forward slashes, no leading `/`, no `..` segments.",
    },
    content: {
      type: "string",
      description: "File content as UTF-8 text. Binary payloads are not supported in v1.",
    },
    message: {
      type: "string",
      description: "Optional commit message (max 2000 chars).",
    },
  },
  required: ["ws_slug", "proj_slug", "path", "content"],
  additionalProperties: false,
} as const;

export type { ProjectSaveInput, ProjectSaveOutput };

/** Tool entry point. Resolve o scope pelo hub e delega pra lib. */
export async function runProjectSaveAndUrl(
  input: ProjectSaveAndUrlInput,
  cwd: string = process.cwd(),
): Promise<ProjectSaveAndUrlOutput> {
  const scope = await resolveProjectScope(input, cwd);
  if (!scope.ok) return scope;

  return runProjectSave(
    { path: input.path, content: input.content, message: input.message },
    {
      wsId: scope.ws_id,
      projId: scope.proj_id,
      wsSlug: input.ws_slug,
      projSlug: input.proj_slug,
      backendTarget: "legacy",
      absoluteProjectRoot: scope.project_root,
    },
  );
}
