/**
 * Tool: `proxy_semrush` — Semrush keyword data.
 *
 * Passthrough to `POST /api/v1/apis/semrush`. Backend builds the upstream
 * querystring from the body; we only enforce a minimal sanity check.
 */
import { authenticatedJson } from "../lib/api.js";

import { mapProxyError } from "./proxy-serper.js";

export const PROXY_SEMRUSH_INPUT_SCHEMA = {
  type: "object",
  properties: {
    type: {
      type: "string",
      description:
        "Semrush report type (e.g. 'phrase_all', 'phrase_related').",
    },
    phrase: { type: "string", description: "Target phrase / keyword." },
    database: {
      type: "string",
      description: "Semrush database code (e.g. 'br', 'us'). Default: 'br'.",
    },
  },
  required: ["type"],
  additionalProperties: true,
} as const;

export interface ProxySemrushInput {
  type: string;
  phrase?: string;
  database?: string;
  [k: string]: unknown;
}

export type ProxySemrushOutput =
  | { ok: true; data: unknown }
  | { ok: false; error: string; hint?: string; retry_after_sec?: number };

export async function runProxySemrush(
  input: ProxySemrushInput,
): Promise<ProxySemrushOutput> {
  if (typeof input.type !== "string" || input.type.length === 0) {
    return { ok: false, error: "bad_input", hint: "Field 'type' is required." };
  }
  try {
    const data = await authenticatedJson<unknown>("/api/v1/apis/semrush", {
      method: "POST",
      body: JSON.stringify(input),
    });
    return { ok: true, data };
  } catch (err) {
    return mapProxyError(err);
  }
}
