/**
 * `brain.produtos` collection — canonical catalog of the client's products and
 * services. Single source of truth the agent reads to recover product names,
 * positioning, official URLs (for linking) and preferred anchors when writing
 * and linking. Keeps frontmatter minimal; the per-product structure lives in
 * the body (one section per product/service).
 */

import { z } from "zod";

import { IsoDateTimeSchema } from "./_common.js";

export const BRAIN_PRODUTOS_TYPE = "brain.produtos" as const;
export const BRAIN_PRODUTOS_CONVENTIONAL_PATH = "brain/produtos.md" as const;

export const BrainProdutosFrontmatterSchema = z
  .object({
    title: z.string().min(1).max(200),
    type: z.literal(BRAIN_PRODUTOS_TYPE),
    updated_at: IsoDateTimeSchema,
  })
  .strict();

export type BrainProdutosFrontmatter = z.infer<typeof BrainProdutosFrontmatterSchema>;
