/**
 * `brain.decisoes` collection — append-only log of decisions with rationale.
 *
 * `append_only: true` is a marker flag used by the web editor and the
 * /brain-update skill to enforce the invariant: the body grows, never
 * shrinks (ADR-011 §5).
 */

import { z } from "zod";

import { IsoDateTimeSchema } from "./_common.js";

export const BRAIN_DECISOES_TYPE = "brain.decisoes" as const;
export const BRAIN_DECISOES_CONVENTIONAL_PATH = "brain/decisoes.md" as const;

export const BrainDecisoesFrontmatterSchema = z
  .object({
    title: z.string().min(1).max(300).default("Decisões"),
    type: z.literal(BRAIN_DECISOES_TYPE),
    updated_at: IsoDateTimeSchema,
    sources: z.array(z.string().min(1).max(300)).optional(),
    append_only: z.literal(true).default(true),
  })
  .strict();

export type BrainDecisoesFrontmatter = z.infer<
  typeof BrainDecisoesFrontmatterSchema
>;
