/**
 * `briefing` collection — editorial briefing that precedes an article.
 *
 * Lives under `deliverables/briefings/<slug>.md` by convention. A briefing
 * is a human-signed contract: it freezes the client analysis, the SERP
 * snapshot reference and the skyscraper plan before the redator runs.
 *
 * Relationship model (hybrid — ADR pending, decision captured in
 * `docs/raw/22h-arquitetura/plan.md`):
 *   - `references.serp`   → `pesquisas/serp/<slug>.yml`   (serp_snapshot)
 *   - `references.fontes` → `pesquisas/fontes/<slug>.yml` (fonte_entidade[])
 *   - `references.conteudo` → `deliverables/conteudos/<slug>.md` (artigo)
 *      Bidirectional: once the redator creates the article, the briefing's
 *      `references.conteudo` points at it and the article's `briefing_ref`
 *      points back. The lint pass enforces the pair.
 */

import { z } from "zod";

import { IsoDateTimeSchema, SlugSchema, TagsSchema } from "./_common.js";

export const BRIEFING_TYPE = "briefing" as const;
export const BRIEFING_CONVENTIONAL_PATH = "deliverables/briefings/" as const;

export const BriefingStatusSchema = z.enum([
  "rascunho", // skill criou, aguarda dados
  "em_analise", // SERP e fontes coletadas, aguarda consolidação
  "aprovado", // usuário aprovou, pronto pra redator
  "em_producao", // redator rodou, conteudo_ref preenchido
  "publicado", // artigo finalizado
  "arquivado",
]);

export const BriefingAcaoSchema = z.enum([
  "criar",
  "atualizar",
  "otimizar",
  "refresh",
  "nao_criar",
]);

const ArtigoExistenteSchema = z
  .object({
    posicao: z.number().int().positive(),
    url: z.string().url(),
    nota: z.string().optional(),
  })
  .strict();

const ClienteAnalysisSchema = z
  .object({
    dominio: z.string().min(1),
    rankeia: z.boolean(),
    artigo_existente: ArtigoExistenteSchema.nullable().optional(),
    justificativa: z.string().optional(),
  })
  .strict();

const SkyscraperPlanSchema = z
  .object({
    benchmark_words: z.number().int().nonnegative().optional(),
    target_words: z.number().int().nonnegative().optional(),
    target_h2s: z.number().int().nonnegative().optional(),
    gaps: z.array(z.string()).default([]),
    differentiation: z.array(z.string()).default([]),
  })
  .strict();

const BriefingReferencesSchema = z
  .object({
    serp: SlugSchema.optional(),
    fontes: z.array(SlugSchema).default([]),
    conteudo: SlugSchema.optional(),
    cluster: SlugSchema.optional(),
  })
  .strict();

const BriefingFactcheckSchema = z
  .object({
    mode: z.enum(["off", "advisory", "enforced"]).default("off"),
    ledger_seed_path: z.string().min(1).max(512).optional(),
  })
  .strict();

export const BriefingFrontmatterSchema = z
  .object({
    type: z.literal(BRIEFING_TYPE),
    slug: SlugSchema,
    title: z.string().min(1).max(300),
    status: BriefingStatusSchema,
    created_at: IsoDateTimeSchema,
    updated_at: IsoDateTimeSchema,

    // user input
    keyword: z.string().min(1).max(200),
    topico: z.string().min(1).max(500).optional(),
    acao: BriefingAcaoSchema,

    cliente: ClienteAnalysisSchema.optional(),
    skyscraper: SkyscraperPlanSchema.optional(),
    references: BriefingReferencesSchema.optional(),
    factcheck: BriefingFactcheckSchema.optional(),

    tags: TagsSchema.optional(),
  })
  .strict();

export type BriefingFrontmatter = z.infer<typeof BriefingFrontmatterSchema>;
