/**
 * `factcheck_dossier` collection — human review dossier produced by
 * `/conversion-agent:factcheck`.
 *
 * The machine ledger can live beside it as YAML, but the dossier is the
 * projected markdown artifact reviewers open in the web app.
 */

import { z } from "zod";

import { IsoDateTimeSchema, SlugSchema } from "./_common.js";

export const FACTCHECK_DOSSIER_TYPE = "factcheck_dossier" as const;
export const FACTCHECK_DOSSIER_CONVENTIONAL_PATH =
  "deliverables/factcheck/" as const;

export const FactcheckModeSchema = z.enum(["off", "advisory", "enforced"]);

export const FactcheckDossierStatusSchema = z.enum([
  "ok",
  "needs_review",
  "blocked",
]);

export const FactcheckTargetTypeSchema = z.enum(["artigo", "briefing"]);

const FactcheckVerdictCountsSchema = z
  .object({
    correto: z.number().int().nonnegative().default(0),
    incorreto_desatualizado: z.number().int().nonnegative().default(0),
    nao_confirmado: z.number().int().nonnegative().default(0),
  })
  .strict();

const FactcheckRiskCountsSchema = z
  .object({
    legal: z.number().int().nonnegative().default(0),
    alto: z.number().int().nonnegative().default(0),
    medio: z.number().int().nonnegative().default(0),
    baixo: z.number().int().nonnegative().default(0),
  })
  .strict();

export const FactcheckDossierFrontmatterSchema = z
  .object({
    slug: SlugSchema,
    title: z.string().min(1).max(300),
    type: z.literal(FACTCHECK_DOSSIER_TYPE),
    status: FactcheckDossierStatusSchema,
    mode: FactcheckModeSchema,
    target_type: FactcheckTargetTypeSchema,
    target_slug: SlugSchema,
    ledger_path: z.string().min(1).max(512).optional(),
    created_at: IsoDateTimeSchema,
    updated_at: IsoDateTimeSchema,
    verdict_counts: FactcheckVerdictCountsSchema.default({
      correto: 0,
      incorreto_desatualizado: 0,
      nao_confirmado: 0,
    }),
    risk_counts: FactcheckRiskCountsSchema.default({
      legal: 0,
      alto: 0,
      medio: 0,
      baixo: 0,
    }),
    reviewer_signed_by: z.string().min(1).max(200).optional(),
    proof_required: z.boolean().default(false),
  })
  .strict();

export type FactcheckMode = z.infer<typeof FactcheckModeSchema>;
export type FactcheckDossierFrontmatter = z.infer<
  typeof FactcheckDossierFrontmatterSchema
>;
