/**
 * `links_internos` collection — internal-link recommendations produced by
 * the `/links-internos` skill.
 *
 * Two cardinalities (Opção C híbrida — rodada doha):
 *   - `single`: exactly one URL is the focus (alvo if modo=receive,
 *     origem if modo=send). Path: `deliverables/links-internos/url-<slug>.md`.
 *     Re-running the skill on the same URL appends to `historico[]`.
 *   - `batch`: bulk run with N URLs. Path:
 *     `deliverables/links-internos/<YYYY-MM-DD>-<slug>.md`. Snapshot of one
 *     execution; not cumulative.
 *
 * Modes:
 *   - `receive`: each URL in `urls` (role=alvo) collects suggestions of
 *     origens that should link TO it. Default mode.
 *   - `send`: each URL in `urls` (role=origem) gets suggestions of destinos
 *     it should link OUT to.
 *
 * Suggestions carry:
 *   - status (proposto | aprovado | rejeitado | aplicado).
 *   - confidence of the duplicate-check (alta | media), recording WHICH
 *     verification ran (project-only inventory, sub-agent webfetch, both).
 *   - recommended anchor variants + reasoning.
 *
 * Hallucination guard: every suggested URL/origem must have come from a
 * `WebSearch site:` result OR from the project inventory — never from
 * memory. The schema does not encode this rule, but the methodology and
 * QA gates do.
 */

import { z } from "zod";

import { IsoDateTimeSchema, SlugSchema } from "./_common.js";

export const LINKS_INTERNOS_TYPE = "links_internos" as const;
export const LINKS_INTERNOS_CONVENTIONAL_PATH =
  "deliverables/links-internos/" as const;

export const LinksInternosCardinalitySchema = z.enum(["single", "batch"]);

export const LinksInternosModoSchema = z.enum(["receive", "send"]);

export const LinksInternosUrlRoleSchema = z.enum(["alvo", "origem"]);

export const LinksInternosSugestaoStatusSchema = z.enum([
  "proposto",
  "aprovado",
  "rejeitado",
  "aplicado",
]);

export const LinksInternosVerificacaoMetodoSchema = z.enum([
  "project_inventory", // extractForwardLinks no project — best-effort
  "subagent_webfetch", // sub-agent paralelo lendo HTML — alta confiança
  "subagent_webfetch+project_inventory",
  "nao_verificado", // fallback explícito quando nenhuma verificação rodou
]);

export const LinksInternosVerificacaoConfiancaSchema = z.enum([
  "alta",
  "media",
  "baixa",
]);

const VerificacaoSchema = z
  .object({
    metodo: LinksInternosVerificacaoMetodoSchema,
    confianca: LinksInternosVerificacaoConfiancaSchema,
    nota: z.string().max(500).optional(),
  })
  .strict()
  .refine(
    (v) => {
      // Invariante: confianca=baixa só é válida com metodo=nao_verificado
      // (e nesse caso é OBRIGATÓRIA — webfetch confirmado/inventário não
      // emitem confianca baixa).
      if (v.metodo === "nao_verificado") return v.confianca === "baixa";
      return v.confianca !== "baixa";
    },
    {
      message:
        "confianca=baixa requires metodo=nao_verificado (and vice-versa)",
    },
  )
  .refine(
    (v) => {
      // nao_verificado precisa de nota explicando o motivo (timeout, robots,
      // 4xx/5xx). Sem nota, humano não consegue agir.
      if (v.metodo === "nao_verificado") return Boolean(v.nota && v.nota.length > 0);
      return true;
    },
    {
      message: "metodo=nao_verificado requires a nota explaining why",
    },
  );

/**
 * One suggestion. In `receive` mode, `origem` is the candidate page that
 * should link TO the alvo. In `send` mode, `destino` is the candidate page
 * the origem should link to. Exactly one of `origem`/`destino` is filled
 * per suggestion, depending on the parent `modo`.
 */
const SugestaoSchema = z
  .object({
    // Quem é o "outro lado" do link. URL absoluta sempre (nunca slug puro,
    // pra a sugestão ser auditável fora do project).
    url: z.string().url(),
    // Slug do project quando aplicável (origem/destino é um artigo do project).
    slug: SlugSchema.optional(),
    // Title da página descoberto via WebSearch ou WebFetch.
    title: z.string().min(1).max(300).optional(),
    // Anchor sugerida — primeira variante é a recomendada.
    anchors_sugeridas: z.array(z.string().min(1).max(120)).min(1).max(5),
    // Trecho previsto onde o link entra (parágrafo curto, com a anchor
    // marcada por **anchor**).
    trecho_previsto: z.string().min(1).max(2000).optional(),
    // 0..100 — score interno (relevância semântica + reduz click-depth +
    // diversifica anchor — heurística, não modelo treinado).
    score: z.number().int().min(0).max(100),
    // Justificativa em prosa curta (por que esse par faz sentido).
    justificativa: z.string().min(1).max(800),
    // Resultado da checagem de duplicata.
    verificacao_sem_link: VerificacaoSchema,
    status: LinksInternosSugestaoStatusSchema,
    // Quando aplicada (`status: aplicado`), onde foi aplicada.
    aplicado_em: z.string().url().optional(),
    aplicado_at: IsoDateTimeSchema.optional(),
  })
  .strict();

/**
 * One URL processed in this artifact. Multiple `urls[]` only appear in
 * `cardinality: batch`; in `single`, urls has length 1.
 */
/**
 * Manual URL parser used by the `.refine()` invariants below.
 *
 * Manual parsing because `shared/` doesn't depend on `@types/node` and the
 * base lib (ES2022) doesn't include the DOM URL constructor. Conservative:
 * false negatives are OK (sub-agent webfetch catches them in FASE 4); false
 * positives (blocking a legit suggestion) are not.
 */
const URL_RE = /^([a-z][a-z0-9+.-]*):\/\/([^/?#]+)([^?#]*)(\?[^#]*)?(#.*)?$/iu;

function parseUrl(
  raw: string,
): { scheme: string; host: string; path: string; query: string } | null {
  const m = URL_RE.exec(raw);
  if (!m) return null;
  return {
    scheme: m[1]!.toLowerCase(),
    host: m[2]!.toLowerCase(),
    path: m[3] ?? "",
    query: m[4] ?? "",
  };
}

/**
 * Normalize a URL for auto-link comparison: strip trailing slash, drop
 * fragment, lowercase host. Query strings are preserved (different ?utm
 * could legitimately refer to different content, though most sites
 * canonicalize).
 */
function normalizeForAutoLinkCompare(raw: string): string {
  const u = parseUrl(raw);
  if (!u) return raw;
  let path = u.path;
  if (path.length > 1 && path.endsWith("/")) path = path.slice(0, -1);
  if (path.length === 0) path = "/";
  return `${u.scheme}://${u.host}${path}${u.query}`;
}

/**
 * Returns true when the URL's host equals `dominio` exactly OR is a
 * subdomain of it (e.g., `blog.cliente.com.br` matches `cliente.com.br`).
 *
 * Normalizes the URL host before comparing:
 *   - Strips an explicit port (`:8080`) — `cliente.com.br:8080` should
 *     count as `cliente.com.br`.
 *   - Strips a leading `www.` since `dominio` is bare.
 */
function urlBelongsToDominio(rawUrl: string, dominio: string): boolean {
  const u = parseUrl(rawUrl);
  if (!u) return false;
  const hostNoPort = u.host.replace(/:\d+$/u, "");
  const host = hostNoPort.startsWith("www.")
    ? hostNoPort.slice(4)
    : hostNoPort;
  const dom = dominio.toLowerCase();
  return host === dom || host.endsWith(`.${dom}`);
}

const UrlEntrySchema = z
  .object({
    url: z.string().url(),
    role: LinksInternosUrlRoleSchema,
    slug: SlugSchema.optional(),
    title: z.string().min(1).max(300).optional(),
    // Termos usados no `WebSearch [termo] site:<dominio>` para esta URL.
    keywords_buscadas: z.array(z.string().min(1).max(200)).default([]),
    sugestoes: z.array(SugestaoSchema).default([]),
  })
  .strict()
  .refine(
    (entry) => {
      // Bloqueante: nenhuma sugestão pode apontar para a própria URL
      // (auto-link). Defesa em profundidade — FASE 3 do methodology já
      // filtra na descoberta, mas aqui o schema enforça para qualquer
      // origem de input.
      const self = normalizeForAutoLinkCompare(entry.url);
      return entry.sugestoes.every(
        (s) => normalizeForAutoLinkCompare(s.url) !== self,
      );
    },
    {
      message: "auto-link rejected: sugestoes[].url cannot equal the parent url",
    },
  );

/**
 * One execution snapshot — present in `historico[]` for `single`
 * cardinality, used for cumulative state.
 */
const HistoricoEntrySchema = z
  .object({
    data: IsoDateTimeSchema,
    sugestoes_geradas: z.number().int().nonnegative(),
    aprovadas: z.number().int().nonnegative().default(0),
    rejeitadas: z.number().int().nonnegative().default(0),
    aplicadas: z.number().int().nonnegative().default(0),
    nota: z.string().max(500).optional(),
  })
  .strict();

export const LinksInternosFrontmatterSchema = z
  .object({
    type: z.literal(LINKS_INTERNOS_TYPE),
    slug: SlugSchema,
    title: z.string().min(1).max(300),
    cardinality: LinksInternosCardinalitySchema,
    modo: LinksInternosModoSchema,
    created_at: IsoDateTimeSchema,
    updated_at: IsoDateTimeSchema,
    // Dominio canônico da execução (ex: `cliente.com.br`). Todas as URLs
    // (urls[].url e sugestoes[].url) devem pertencer a esse domínio ou
    // subdomínio — enforçado via .refine() abaixo.
    dominio: z
      .string()
      .min(3)
      .max(253)
      .regex(/^[a-z0-9.-]+\.[a-z]{2,}$/u, {
        message: "dominio must be a bare host (no scheme, no path)",
      }),
    urls: z.array(UrlEntrySchema).min(1).max(50),
    historico: z.array(HistoricoEntrySchema).default([]),
    // Slug do briefing quando esta execução foi disparada como sub-skill
    // por `/briefing` na FASE 2.4.
    briefing_ref: SlugSchema.optional(),
  })
  .strict()
  .refine(
    (fm) => fm.cardinality !== "single" || fm.urls.length === 1,
    {
      message: "cardinality=single requires exactly 1 entry in urls[]",
      path: ["urls"],
    },
  )
  .refine(
    (fm) => fm.cardinality !== "batch" || fm.urls.length >= 2,
    {
      message: "cardinality=batch requires at least 2 entries in urls[]",
      path: ["urls"],
    },
  )
  .refine(
    (fm) =>
      fm.modo !== "receive" || fm.urls.every((u) => u.role === "alvo"),
    {
      message: "modo=receive requires every urls[].role to be 'alvo'",
      path: ["urls"],
    },
  )
  .refine(
    (fm) =>
      fm.modo !== "send" || fm.urls.every((u) => u.role === "origem"),
    {
      message: "modo=send requires every urls[].role to be 'origem'",
      path: ["urls"],
    },
  )
  .refine(
    (fm) => {
      // Coleção é "internal-links" — todas as URLs (entries + sugestoes)
      // precisam pertencer ao dominio declarado (ou subdominio dele).
      // Sem essa checagem, uma URL externa passa silenciosamente.
      for (const entry of fm.urls) {
        if (!urlBelongsToDominio(entry.url, fm.dominio)) return false;
        for (const s of entry.sugestoes) {
          if (!urlBelongsToDominio(s.url, fm.dominio)) return false;
        }
      }
      return true;
    },
    {
      message:
        "all urls[].url and sugestoes[].url must belong to the declared dominio (or a subdomain)",
      path: ["dominio"],
    },
  );

export type LinksInternosFrontmatter = z.infer<
  typeof LinksInternosFrontmatterSchema
>;
