/**
 * Shared pieces for the 9 collection schemas.
 *
 * Keep these primitives in one place so the individual schemas stay tiny
 * and visually consistent. Any new rule (e.g. stricter slug regex) is applied
 * automatically to every collection that imports from here.
 */

import { z } from "zod";

/**
 * Slug regex used everywhere collections identify a document.
 * Lowercase kebab-case, length 2-80 — mirrors the guidance in ADR-011 §4.
 */
export const SLUG_REGEX = /^[a-z0-9]+(?:-[a-z0-9]+)*$/u;

export const SlugSchema = z
  .string()
  .min(2)
  .max(80)
  .regex(SLUG_REGEX, {
    message: "slug must be lowercase kebab-case (a-z, 0-9, hyphen)",
  });

/**
 * ISO 8601 datetime (UTC with Z suffix is the preferred form but we accept
 * any TZ offset). Validated by Zod's built-in `datetime`.
 */
export const IsoDateTimeSchema = z.string().datetime({ offset: true });

/** YYYY-MM-DD calendar date, no timezone. */
export const IsoDateSchema = z.string().regex(/^\d{4}-\d{2}-\d{2}$/u, {
  message: "date must be YYYY-MM-DD",
});

/** Optional UUID v4-ish (we don't enforce version — validates shape only). */
export const UuidSchema = z
  .string()
  .regex(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/iu, {
    message: "expected uuid",
  });

export const TagsSchema = z.array(z.string().min(1).max(64));
