/**
 * Credential reader for the MCP server.
 *
 * Plugin-first auth reads `${CLAUDE_PLUGIN_DATA}/auth.json` before falling
 * back to the OS keychain entries created by older CLI flows. Renewal writes
 * go to plugin data; keychain is migration/fallback only.
 *
 * When multiple accounts exist on the same machine (e.g. a developer who
 * logs in with both personal and shared credentials), we pick one with
 * this priority:
 *
 *   1. `CONVERSION_EMAIL` env var (exact match).
 *   2. The first credential returned by keytar, with a stderr warning.
 *
 * stderr is safe to log to — Claude Code's stdio transport only parses
 * stdout. See https://modelcontextprotocol.io/specification (transports).
 */
import { mkdir, readFile, rename, writeFile, chmod } from "node:fs/promises";
import { homedir } from "node:os";
import { dirname, join } from "node:path";

import {
  EMAIL_SELECTOR,
  KEYCHAIN_SERVICE,
  KEYCHAIN_SERVICE_LEGACY,
  PLUGIN_DATA_DIR,
} from "./config.js";

const CANONICAL_PLUGIN_DATA_DIR =
  process.env["CONVERSION_PLUGIN_DATA_DIR"] ??
  join(homedir(), ".conversion", "plugin-data");

/** Shape returned by {@link getToken}. */
export interface StoredCredential {
  email: string;
  token: string;
  expiresAt?: string;
  source?: "plugin-data" | "keychain";
}

interface AuthFile {
  email: string;
  access_token: string;
  expires_at?: string;
}

function pluginDataDir(): string {
  return PLUGIN_DATA_DIR ?? join(homedir(), ".conversion", "plugin-data");
}

export function pluginAuthPath(): string {
  return join(pluginDataDir(), "auth.json");
}

function canonicalPluginAuthPath(): string {
  return join(CANONICAL_PLUGIN_DATA_DIR, "auth.json");
}

function authPaths(): string[] {
  return [...new Set([pluginAuthPath(), canonicalPluginAuthPath()])];
}

function isAuthFile(value: unknown): value is AuthFile {
  if (!value || typeof value !== "object") return false;
  const obj = value as Record<string, unknown>;
  return (
    typeof obj["email"] === "string" &&
    typeof obj["access_token"] === "string" &&
    (obj["expires_at"] === undefined || typeof obj["expires_at"] === "string")
  );
}

export async function readPluginAuth(): Promise<StoredCredential | null> {
  for (const path of authPaths()) {
    try {
      const parsed = JSON.parse(await readFile(path, "utf8")) as unknown;
      if (!isAuthFile(parsed)) continue;
      return {
        email: parsed.email,
        token: parsed.access_token,
        expiresAt: parsed.expires_at,
        source: "plugin-data",
      };
    } catch {
      // Try the next auth source.
    }
  }
  return null;
}

export async function savePluginAuth(input: {
  email: string;
  token: string;
  expiresAt?: string;
}): Promise<void> {
  const [primary, ...fallbacks] = authPaths();
  if (primary) await savePluginAuthAt(primary, input);
  for (const path of fallbacks) {
    await savePluginAuthAt(path, input).catch(() => undefined);
  }
}

async function savePluginAuthAt(
  path: string,
  input: { email: string; token: string; expiresAt?: string },
): Promise<void> {
  await mkdir(dirname(path), { recursive: true, mode: 0o700 });
  await chmod(dirname(path), 0o700).catch(() => undefined);
  const tmp = `${path}.${process.pid}.tmp`;
  await writeFile(
    tmp,
    `${JSON.stringify(
      {
        email: input.email,
        access_token: input.token,
        expires_at: input.expiresAt,
        updated_at: new Date().toISOString(),
      },
      null,
      2,
    )}\n`,
    { encoding: "utf8", mode: 0o600 },
  );
  await chmod(tmp, 0o600).catch(() => undefined);
  await rename(tmp, path);
}

async function findKeychainCredentials(): Promise<
  Array<{ account: string; password: string }>
> {
  type KeytarApi = {
    findCredentials(service: string): Promise<Array<{ account: string; password: string }>>;
  };
  let keytar: KeytarApi | null = null;
  try {
    const mod = (await import("keytar")) as unknown as
      | KeytarApi
      | { default: KeytarApi };
    keytar = "default" in mod ? mod.default : mod;
  } catch {
    return [];
  }
  const fromNew = await keytar.findCredentials(KEYCHAIN_SERVICE);
  const fromLegacy = await keytar.findCredentials(KEYCHAIN_SERVICE_LEGACY);
  return [...fromNew, ...fromLegacy];
}

/**
 * Return the JWT for the currently-active Conversion account, or `null`
 * when no credential is stored.
 *
 * Never throws on "no credential" — only on OS-level keychain failures
 * (e.g. Linux libsecret missing). Those bubble up so the tool handler can
 * surface a dedicated `keychain_error` code.
 */
export async function getToken(): Promise<StoredCredential | null> {
  const pluginAuth = await readPluginAuth();
  if (pluginAuth) return pluginAuth;

  const keychainCredentials = await findKeychainCredentials();
  const seen = new Set<string>();
  const all: { account: string; password: string }[] = [];
  for (const cred of keychainCredentials) {
    const key = cred.account.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    all.push(cred);
  }
  if (all.length === 0) return null;

  const selector = EMAIL_SELECTOR;
  if (selector) {
    const needle = selector.toLowerCase();
    const match = all.find((c) => c.account.toLowerCase() === needle);
    if (!match) {
      process.stderr.write(
        `[conversion-mcp] CONVERSION_EMAIL='${selector}' not found in keychain. ` +
          `Available accounts: ${all.map((c) => c.account).join(", ")}\n`,
      );
      return null;
    }
    return { email: match.account, token: match.password, source: "keychain" };
  }

  const first = all[0];
  if (!first) return null;
  if (all.length > 1) {
    process.stderr.write(
      `[conversion-mcp] Multiple accounts in keychain (${all.length}); using '${first.account}'. ` +
        `Set CONVERSION_EMAIL to disambiguate.\n`,
    );
  }
  return { email: first.account, token: first.password, source: "keychain" };
}
