/**
 * `brain.pending` collection — pending proposals awaiting human approval.
 *
 * Lives at `brain/_pending.md`. The `/brain-update` skill writes here after
 * consolidating approved deliverables. A human reviews via the web editor
 * and either moves each proposal into the appropriate brain file
 * (tom-voz.md, glossario.md, etc.) or discards it.
 *
 * The proposals list is intentionally minimal — each proposal is a small,
 * atomic change (e.g. "add term X to glossary"). The skill is responsible
 * for atomizing its suggestions before writing.
 */

import { z } from "zod";

import { IsoDateTimeSchema } from "./_common.js";

export const BRAIN_PENDING_TYPE = "brain.pending" as const;
export const BRAIN_PENDING_CONVENTIONAL_PATH = "brain/_pending.md" as const;

const BRAIN_TARGETS = [
  "brain.tom_voz",
  "brain.glossario",
  "brain.decisoes",
  "brain.aprendizados",
  "brain.personas",
  "brain.provas",
  "brain.fontes",
] as const;

export const BrainPendingProposalSchema = z
  .object({
    target: z.enum(BRAIN_TARGETS),
    summary: z.string().min(4).max(300),
    rationale: z.string().min(4).max(2000),
    source_slugs: z.array(z.string().min(1).max(120)).optional(),
  })
  .strict();

export type BrainPendingProposal = z.infer<typeof BrainPendingProposalSchema>;

export const BrainPendingFrontmatterSchema = z
  .object({
    title: z.string().min(1).max(300).default("Propostas de atualização"),
    type: z.literal(BRAIN_PENDING_TYPE),
    updated_at: IsoDateTimeSchema,
    proposals: z.array(BrainPendingProposalSchema).min(0).max(50),
  })
  .strict();

export type BrainPendingFrontmatter = z.infer<
  typeof BrainPendingFrontmatterSchema
>;
