import { createHash } from "node:crypto";

export type RedlinePriority = "P0" | "P1" | "P2";

export const ON_PAGE_RUN_SLUG_PATTERN_SOURCE =
  "^\\d{4}-\\d{2}-\\d{2}-[a-z0-9]+(?:-[a-z0-9]+)*-[0-9a-f]{8}$" as const;
export const ON_PAGE_RUN_SLUG_PATTERN = new RegExp(ON_PAGE_RUN_SLUG_PATTERN_SOURCE, "u");

export type RedlineSegment =
  | { kind: "keep"; text: string }
  | {
      kind: "insert" | "delete";
      text: string;
      reason: string;
      priority: RedlinePriority;
    };

export type RedlineBlock =
  | { kind: "heading"; level: 1 | 2 | 3; segments: RedlineSegment[] }
  | { kind: "paragraph"; segments: RedlineSegment[] };

export interface RedlineDocument {
  blocks: RedlineBlock[];
}

const compare = (left: string, right: string): number => (left < right ? -1 : left > right ? 1 : 0);

export function isValidOnPageRunSlug(value: unknown): value is string {
  if (typeof value !== "string") return false;
  const match = ON_PAGE_RUN_SLUG_PATTERN.exec(value);
  if (!match) return false;
  const date = new Date(`${value.slice(0, 10)}T00:00:00.000Z`);
  return (
    !Number.isNaN(date.getTime()) &&
    date.getUTCFullYear() === Number(value.slice(0, 4)) &&
    date.getUTCMonth() + 1 === Number(value.slice(5, 7)) &&
    date.getUTCDate() === Number(value.slice(8, 10))
  );
}

export function canonicalizeOnPageUrl(raw: string): string {
  const url = new URL(raw);
  if (!(["http:", "https:"] as string[]).includes(url.protocol)) {
    throw new Error("unsupported_url_protocol");
  }
  url.hash = "";
  for (const key of [...url.searchParams.keys()]) {
    if (/^utm_/iu.test(key) || /^(gclid|fbclid)$/iu.test(key)) {
      url.searchParams.delete(key);
    }
  }
  const pairs = [...url.searchParams.entries()].sort(
    ([leftKey, leftValue], [rightKey, rightValue]) =>
      compare(leftKey, rightKey) || compare(leftValue, rightValue),
  );
  url.search = "";
  for (const [key, value] of pairs) url.searchParams.append(key, value);
  url.hostname = url.hostname.toLowerCase();
  if (
    (url.protocol === "http:" && url.port === "80") ||
    (url.protocol === "https:" && url.port === "443")
  ) {
    url.port = "";
  }
  if (url.pathname !== "/") url.pathname = url.pathname.replace(/\/+$/u, "");
  return url.toString();
}

export function expectedOnPageRunSlug(canonicalUrl: string, isoDate: string): string {
  const dateMatch = /^(\d{4})-(\d{2})-(\d{2})$/u.exec(isoDate);
  const date = new Date(`${isoDate}T00:00:00.000Z`);
  if (
    !dateMatch ||
    Number.isNaN(date.getTime()) ||
    date.getUTCFullYear() !== Number(dateMatch[1]) ||
    date.getUTCMonth() + 1 !== Number(dateMatch[2]) ||
    date.getUTCDate() !== Number(dateMatch[3])
  ) {
    throw new Error("invalid_run_date");
  }

  let lastSegment: string;
  try {
    if (canonicalizeOnPageUrl(canonicalUrl) !== canonicalUrl) {
      throw new Error("noncanonical");
    }
    const url = new URL(canonicalUrl);
    lastSegment = decodeURIComponent(url.pathname.split("/").filter(Boolean).at(-1) ?? "home");
  } catch {
    throw new Error("invalid_canonical_url");
  }
  const pageSlug =
    lastSegment
      .normalize("NFD")
      .replace(/\p{M}+/gu, "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/gu, "-")
      .replace(/^-|-$/gu, "")
      .slice(0, 60) || "home";
  const inputHash = createHash("sha256").update(canonicalUrl, "utf8").digest("hex");
  return `${isoDate}-${pageSlug}-${inputHash.slice(0, 8)}`;
}

export function assertOnPageRunSlug(runSlug: string, canonicalUrl: string): void {
  try {
    if (!isValidOnPageRunSlug(runSlug)) throw new Error("invalid");
    const date = /^(\d{4}-\d{2}-\d{2})-/u.exec(runSlug)?.[1];
    if (!date || expectedOnPageRunSlug(canonicalUrl, date) !== runSlug) {
      throw new Error("mismatch");
    }
  } catch {
    throw new Error("invalid_run_slug");
  }
}
