import { randomUUID } from "node:crypto";
import { access, mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";

import {
  acquireSyncLock,
  deterministicCommitId,
  type SyncLock,
} from "@agenciaconversion/local-sync";

import { BACKEND_URL, backendProtectionHeaders } from "./config.js";
import { getToken, savePluginAuth, type StoredCredential } from "./keychain.js";
import {
  assertValidProjectPath,
  canonicalTreeJson,
  canonicalizeText,
  findProjectPathCaseCollision,
  inferMime,
  InvalidProjectPathError,
  isTextMime,
  normalizeManifestMime,
  sha256Hex,
  type Manifest,
} from "./project-save-helpers.js";

const MANIFEST_FILE = ".conversion/manifest.json";
const TRANSACTIONS_DIRECTORY = ".conversion/transactions";
const MAX_FILES = 20;
const MIME_PATTERN = /^[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]*\/[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]*$/u;
const SHA256_PATTERN = /^[0-9a-f]{64}$/u;

interface BlobPutResponse {
  blob: {
    sha256: string;
    storage: "pg" | "blob";
    sizeBytes: number;
    mime: string;
  };
}

interface CommitResponse {
  commit: {
    id: string;
    treeHash: string;
    parentId: string | null;
    createdAt: string;
  };
  idempotent?: boolean;
}

export interface ProjectFileBytes {
  path: string;
  bytes: Uint8Array;
  mime?: string;
}

export interface CommitProjectFilesInput {
  files: readonly ProjectFileBytes[];
  message?: string;
  syncClientId: string;
}

export interface ProjectCommitContext {
  wsId: string;
  projId: string;
  absoluteProjectRoot: string;
  backendUrl?: string;
  wsSlug?: string;
  projSlug?: string;
  backendTarget?: "legacy" | "searchhub";
  expectedManifest?: ProjectManifestSnapshot;
  /** An outer operation that already owns this project's sync lock. */
  syncLock?: SyncLock;
}

export interface ProjectManifestSnapshot {
  manifest: Manifest;
  rawSha256: string;
}

export interface ProjectManifestScope {
  wsId: string;
  projId: string;
  wsSlug?: string;
  projSlug?: string;
  backendTarget?: "legacy" | "searchhub";
}

export type ProjectFilesCommitOutput =
  | {
      ok: true;
      url: string;
      commit_id: string;
      tree_hash: string;
      warning?: string;
      files: Array<{
        path: string;
        sha256: string;
        size: number;
        mime: string;
      }>;
    }
  | {
      ok: false;
      error:
        | "not_authenticated"
        | "session_expired"
        | "rate_limited"
        | "invalid_path"
        | "duplicate_path"
        | "invalid_manifest"
        | "conflict"
        | "backend_error"
        | "network_error"
        | "fs_error"
        | "bad_input";
      hint?: string;
      retry_after_sec?: number;
      server_head?: { commitId: string; treeHash: string } | null;
    };

interface ValidatedFile {
  path: string;
  bytes: Uint8Array;
  mime: string;
}

interface ProcessedFile extends ValidatedFile {
  canonical: Buffer;
  sha256: string;
}

function validateInput(input: CommitProjectFilesInput): ProjectFilesCommitOutput | ValidatedFile[] {
  if (
    !input ||
    !Array.isArray(input.files) ||
    input.files.length === 0 ||
    input.files.length > MAX_FILES ||
    typeof input.syncClientId !== "string" ||
    input.syncClientId.length === 0 ||
    (input.message !== undefined && typeof input.message !== "string")
  ) {
    return {
      ok: false,
      error: "bad_input",
      hint: "Provide 1-20 files and a non-empty syncClientId.",
    };
  }

  const paths = new Set<string>();
  const validated: ValidatedFile[] = [];
  for (const file of input.files) {
    if (!file || typeof file.path !== "string" || !(file.bytes instanceof Uint8Array)) {
      return {
        ok: false,
        error: "bad_input",
        hint: "Every file must have a string path and Uint8Array bytes.",
      };
    }

    try {
      assertValidProjectPath(file.path);
    } catch (error) {
      if (error instanceof InvalidProjectPathError) {
        return {
          ok: false,
          error: "invalid_path",
          hint: `Path rejected: ${error.reason}`,
        };
      }
      return { ok: false, error: "invalid_path", hint: String(error) };
    }

    if (paths.has(file.path)) {
      return {
        ok: false,
        error: "duplicate_path",
        hint: `Path appears more than once: ${file.path}`,
      };
    }
    paths.add(file.path);

    if (file.mime !== undefined && typeof file.mime !== "string") {
      return {
        ok: false,
        error: "bad_input",
        hint: `Invalid MIME for path ${file.path}.`,
      };
    }
    const mime = file.mime ?? inferMime(file.path);
    if (!MIME_PATTERN.test(mime)) {
      return {
        ok: false,
        error: "bad_input",
        hint: `Invalid MIME for path ${file.path}.`,
      };
    }
    validated.push({ path: file.path, bytes: file.bytes, mime });
  }
  const collision = findProjectPathCaseCollision(validated.map((file) => file.path));
  if (collision) {
    return {
      ok: false,
      error: "duplicate_path",
      hint: `Paths collide on case-insensitive filesystems: ${collision.paths.join(", ")}`,
    };
  }
  return validated;
}

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function normalizeManifestFiles(value: unknown): Manifest["files"] | null {
  if (!isPlainRecord(value)) return null;
  const paths = Object.keys(value);
  if (findProjectPathCaseCollision(paths)) return null;
  const normalized: Manifest["files"] = {};
  for (const [path, rawMetadata] of Object.entries(value)) {
    try {
      assertValidProjectPath(path);
    } catch {
      return null;
    }
    if (!isPlainRecord(rawMetadata)) return null;
    if (
      typeof rawMetadata.sha256 !== "string" ||
      !SHA256_PATTERN.test(rawMetadata.sha256) ||
      typeof rawMetadata.size !== "number" ||
      !Number.isInteger(rawMetadata.size) ||
      rawMetadata.size < 0 ||
      typeof rawMetadata.mime !== "string"
    ) {
      return null;
    }
    const mime = normalizeManifestMime(rawMetadata.mime);
    if (!mime) return null;
    normalized[path] = { sha256: rawMetadata.sha256, size: rawMetadata.size, mime };
  }
  return normalized;
}

export async function readProjectManifestSnapshot(
  projectRoot: string,
): Promise<ProjectManifestSnapshot | null> {
  let raw: Buffer;
  try {
    raw = await readFile(join(projectRoot, MANIFEST_FILE));
  } catch {
    return null;
  }
  try {
    const parsed = JSON.parse(raw.toString("utf8")) as unknown;
    if (!parsed || typeof parsed !== "object") return null;
    const manifest = parsed as Partial<Manifest>;
    if (typeof manifest.projectId !== "string") return null;
    if (typeof manifest.workspaceId !== "string") return null;
    if (typeof manifest.workspaceSlug !== "string") return null;
    if (typeof manifest.projectSlug !== "string") return null;
    if (typeof manifest.treeHash !== "string") return null;
    if (manifest.commitId !== null && typeof manifest.commitId !== "string") {
      return null;
    }
    if (typeof manifest.updatedAt !== "string") return null;
    const files = normalizeManifestFiles(manifest.files);
    if (!files) return null;
    return { manifest: { ...manifest, files } as Manifest, rawSha256: sha256Hex(raw) };
  } catch {
    return null;
  }
}

/**
 * Legacy manifests created before backendTarget was introduced remain valid
 * only for the legacy backend. Search Hub manifests must always opt in with an
 * explicit `backendTarget: "searchhub"` marker.
 */
export function manifestMatchesProjectScope(
  manifest: Manifest,
  scope: ProjectManifestScope,
): boolean {
  if (manifest.workspaceId !== scope.wsId || manifest.projectId !== scope.projId) return false;
  if (scope.wsSlug !== undefined && manifest.workspaceSlug !== scope.wsSlug) return false;
  if (scope.projSlug !== undefined && manifest.projectSlug !== scope.projSlug) return false;
  if (scope.backendTarget === "searchhub") return manifest.backendTarget === "searchhub";
  if (scope.backendTarget === "legacy") {
    return manifest.backendTarget === undefined || manifest.backendTarget === "legacy";
  }
  return true;
}

function materializeTool(target: ProjectCommitContext["backendTarget"]): string {
  return target === "searchhub" ? "searchhub_materialize_project" : "materialize_project";
}

function manifestConflictHint(target: ProjectCommitContext["backendTarget"]): string {
  const tool = materializeTool(target);
  return `The local project snapshot is stale or belongs to another scope; use the \`${tool}\` MCP tool and try again.`;
}

async function authedFetch(
  credential: StoredCredential,
  url: string,
  init: RequestInit,
): Promise<Response> {
  const headers = {
    authorization: `Bearer ${credential.token}`,
    accept: "application/json",
    ...backendProtectionHeaders(),
    ...(init.headers as Record<string, string> | undefined),
  };
  const response = await fetch(url, { ...init, headers });
  const renewed = response.headers.get("x-renewed-token");
  if (renewed) {
    await savePluginAuth({ email: credential.email, token: renewed });
  }
  return response;
}

function backendError(hint: string): ProjectFilesCommitOutput {
  return { ok: false, error: "backend_error", hint };
}

async function failedResponse(
  response: Response,
  operation: string,
): Promise<ProjectFilesCommitOutput> {
  if (response.status === 401 || response.status === 403) {
    return {
      ok: false,
      error: "session_expired",
      hint: "Use the `auth_login_start` MCP tool (then `auth_login_poll`) to renew your session.",
    };
  }
  if (response.status === 429) {
    const rawRetryAfter = response.headers.get("retry-after");
    const parsedRetryAfter = rawRetryAfter ? Number.parseInt(rawRetryAfter, 10) : Number.NaN;
    const retryAfterSec =
      Number.isFinite(parsedRetryAfter) && parsedRetryAfter > 0 ? parsedRetryAfter : 60;
    return {
      ok: false,
      error: "rate_limited",
      hint: `Rate limit reached; retry after ${retryAfterSec}s.`,
      retry_after_sec: retryAfterSec,
    };
  }
  const text = await response.text().catch(() => "");
  return backendError(`${operation} failed (HTTP ${response.status}): ${text.slice(0, 200)}`);
}

function isValidCommitResponse(value: unknown): value is CommitResponse {
  if (!isPlainRecord(value) || !isPlainRecord(value.commit)) return false;
  const commit = value.commit;
  return (
    typeof commit.id === "string" &&
    commit.id.length > 0 &&
    typeof commit.treeHash === "string" &&
    SHA256_PATTERN.test(commit.treeHash) &&
    (commit.parentId === null || typeof commit.parentId === "string") &&
    typeof commit.createdAt === "string" &&
    commit.createdAt.length > 0 &&
    (value.idempotent === undefined || typeof value.idempotent === "boolean")
  );
}

interface LocalPromotion {
  destination: string;
  staged: string;
  backup: string;
  bytes: Uint8Array | string;
  hadOriginal: boolean;
  backupCreated: boolean;
}

type MaterializeResult =
  | { ok: true; warning?: string }
  | {
      ok: false;
      rollbackComplete: boolean;
      cleanupComplete: boolean;
      cause: string;
    };

function transactionFileName(index: number, identity: string, kind: "stage" | "backup"): string {
  const encoded = Buffer.from(identity, "utf8").toString("base64url").slice(0, 48);
  return `${String(index).padStart(3, "0")}-${encoded}.${kind}`;
}

async function cleanupTransaction(transactionRoot: string): Promise<boolean> {
  try {
    await rm(transactionRoot, { recursive: true, force: true });
    return true;
  } catch {
    return false;
  }
}

async function materializeCommit(
  projectRoot: string,
  processed: readonly ProcessedFile[],
  nextManifest: Manifest,
  recoveryTool: string,
): Promise<MaterializeResult> {
  const token = randomUUID();
  const transactionRoot = join(projectRoot, TRANSACTIONS_DIRECTORY, token);
  const manifestDestination = join(projectRoot, MANIFEST_FILE);
  const promotions: LocalPromotion[] = [
    ...processed.map((file, index) => {
      const destination = join(projectRoot, file.path);
      return {
        destination,
        staged: join(transactionRoot, transactionFileName(index, file.path, "stage")),
        backup: join(transactionRoot, transactionFileName(index, file.path, "backup")),
        bytes: file.canonical,
        hadOriginal: false,
        backupCreated: false,
      };
    }),
    {
      destination: manifestDestination,
      staged: join(transactionRoot, transactionFileName(processed.length, MANIFEST_FILE, "stage")),
      backup: join(transactionRoot, transactionFileName(processed.length, MANIFEST_FILE, "backup")),
      bytes: JSON.stringify(nextManifest, null, 2) + "\n",
      hadOriginal: false,
      backupCreated: false,
    },
  ];

  try {
    await mkdir(transactionRoot, { recursive: true });
    for (const promotion of promotions) {
      await writeFile(promotion.staged, promotion.bytes);
    }
    for (const promotion of promotions) {
      await mkdir(dirname(promotion.destination), { recursive: true });
      promotion.hadOriginal = await access(promotion.destination).then(
        () => true,
        () => false,
      );
    }
  } catch (error) {
    const cleanupComplete = await cleanupTransaction(transactionRoot);
    return {
      ok: false,
      rollbackComplete: true,
      cleanupComplete,
      cause: error instanceof Error ? error.message : String(error),
    };
  }

  try {
    for (const promotion of promotions) {
      if (promotion.hadOriginal) {
        await rename(promotion.destination, promotion.backup);
        promotion.backupCreated = true;
      }
      await rename(promotion.staged, promotion.destination);
    }
  } catch (error) {
    let rollbackComplete = true;
    for (const promotion of [...promotions].reverse()) {
      try {
        if (promotion.hadOriginal) {
          if (promotion.backupCreated) {
            await rm(promotion.destination, { force: true });
            await rename(promotion.backup, promotion.destination);
            promotion.backupCreated = false;
          }
        } else {
          await rm(promotion.destination, { force: true });
        }
      } catch {
        rollbackComplete = false;
      }
    }
    const cleanupComplete = rollbackComplete ? await cleanupTransaction(transactionRoot) : false;
    return {
      ok: false,
      rollbackComplete,
      cleanupComplete,
      cause: error instanceof Error ? error.message : String(error),
    };
  }

  const cleanupComplete = await cleanupTransaction(transactionRoot);
  return cleanupComplete
    ? { ok: true }
    : {
        ok: true,
        warning: `Local commit succeeded, but cleanup under .conversion/transactions failed. Use ${recoveryTool} to verify local state before removing recovery artifacts.`,
      };
}

async function commitProjectFilesWhileLocked(
  input: CommitProjectFilesInput,
  context: ProjectCommitContext,
  validation: readonly ValidatedFile[],
): Promise<ProjectFilesCommitOutput> {
  const currentSnapshot = await readProjectManifestSnapshot(context.absoluteProjectRoot);
  if (!currentSnapshot) {
    if (context.expectedManifest !== undefined) {
      return {
        ok: false,
        error: "conflict",
        hint: manifestConflictHint(context.backendTarget),
      };
    }
    return {
      ok: false,
      error: "invalid_manifest",
      hint: `\`.conversion/manifest.json\` is missing or malformed. Use the \`${context.backendTarget === "searchhub" ? "searchhub_materialize_project" : "materialize_project"}\` MCP tool again.`,
    };
  }
  const manifest = currentSnapshot.manifest;
  if (
    !manifestMatchesProjectScope(manifest, context) ||
    (context.expectedManifest !== undefined &&
      (!manifestMatchesProjectScope(context.expectedManifest.manifest, context) ||
        currentSnapshot.rawSha256 !== context.expectedManifest.rawSha256))
  ) {
    return {
      ok: false,
      error: "conflict",
      hint: manifestConflictHint(context.backendTarget),
    };
  }

  const credential = await getToken();
  if (!credential) {
    return {
      ok: false,
      error: "not_authenticated",
      hint: "Use the `auth_login_start` MCP tool (then `auth_login_poll`) first.",
    };
  }

  const mergedCollision = findProjectPathCaseCollision([
    ...Object.keys(manifest.files),
    ...validation.map((file) => file.path),
  ]);
  if (mergedCollision) {
    return {
      ok: false,
      error: "duplicate_path",
      hint: `Paths collide on case-insensitive filesystems: ${mergedCollision.paths.join(", ")}`,
    };
  }

  const backendUrl = context.backendUrl ?? BACKEND_URL;
  const processed: ProcessedFile[] = validation.map((file) => {
    const canonical = isTextMime(file.mime)
      ? Buffer.from(canonicalizeText(file.bytes, file.mime))
      : Buffer.from(file.bytes);
    return {
      ...file,
      canonical,
      sha256: sha256Hex(canonical),
    };
  });

  for (const file of processed) {
    let response: Response;
    try {
      response = await authedFetch(credential, `${backendUrl}/api/v1/ws/${context.wsId}/blobs`, {
        method: "POST",
        headers: {
          "content-type": file.mime,
          "content-length": String(file.canonical.length),
        },
        body: new Uint8Array(file.canonical),
      });
    } catch (error) {
      return {
        ok: false,
        error: "network_error",
        hint: error instanceof Error ? error.message : String(error),
      };
    }
    if (!response.ok) {
      return failedResponse(response, "Blob upload");
    }

    let blob: BlobPutResponse["blob"];
    try {
      const parsed = (await response.json()) as BlobPutResponse;
      blob = parsed.blob;
    } catch (error) {
      return backendError(error instanceof Error ? error.message : String(error));
    }
    if (!blob || blob.sha256 !== file.sha256) {
      return backendError(
        `Blob hash mismatch: local=${file.sha256} server=${blob?.sha256 ?? "missing"}`,
      );
    }
  }

  const tree: Record<string, string> = {};
  for (const [path, metadata] of Object.entries(manifest.files)) {
    tree[path] = metadata.sha256;
  }
  for (const file of processed) tree[file.path] = file.sha256;
  const treeHash = sha256Hex(Buffer.from(canonicalTreeJson(tree), "utf8"));
  const parentTreeHash = manifest.commitId ? manifest.treeHash : null;
  const clientCommitId = deterministicCommitId({
    projectId: manifest.projectId,
    actorUserId: credential.email,
    syncClientId: input.syncClientId,
    parentCommitId: manifest.commitId,
    parentTreeHash,
    treeHash,
    message: input.message ?? null,
  });
  const commitBody = {
    parent_tree_hash: parentTreeHash,
    parent_commit_id: manifest.commitId ?? null,
    client_commit_id: clientCommitId,
    tree,
    ...(input.message ? { message: input.message } : {}),
  };

  let commitResponse: Response;
  try {
    commitResponse = await authedFetch(
      credential,
      `${backendUrl}/api/v1/ws/${context.wsId}/projects/${context.projId}/commits`,
      {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(commitBody),
      },
    );
  } catch (error) {
    return {
      ok: false,
      error: "network_error",
      hint: error instanceof Error ? error.message : String(error),
    };
  }

  if (commitResponse.status === 409) {
    let serverHead: { commitId: string; treeHash: string } | null = null;
    try {
      const conflict = (await commitResponse.json()) as {
        server_head?: { commitId: string; treeHash: string } | null;
      };
      serverHead = conflict.server_head ?? null;
    } catch {
      // Keep a stable conflict result even when the backend body is malformed.
    }
    return {
      ok: false,
      error: "conflict",
      hint: manifestConflictHint(context.backendTarget),
      server_head: serverHead,
    };
  }
  if (commitResponse.status !== 201 && commitResponse.status !== 200) {
    return failedResponse(commitResponse, "Commit");
  }

  let parsedCommit: unknown;
  try {
    parsedCommit = await commitResponse.json();
  } catch (error) {
    return backendError(error instanceof Error ? error.message : String(error));
  }
  if (!isValidCommitResponse(parsedCommit)) {
    return backendError("Commit response is malformed.");
  }
  if (commitResponse.status === 200 && parsedCommit.idempotent !== true) {
    return backendError("HTTP 200 commit response is not marked idempotent.");
  }
  const commit = parsedCommit.commit;

  if (treeHash !== commit.treeHash) {
    return backendError(`Commit tree hash mismatch: local=${treeHash} server=${commit.treeHash}`);
  }
  if (
    commitResponse.status === 200 &&
    (commit.id !== clientCommitId || commit.parentId !== (manifest.commitId ?? null))
  ) {
    return backendError("Idempotent commit response does not match the requested commit identity.");
  }

  const nextFiles: Manifest["files"] = { ...manifest.files };
  for (const file of processed) {
    nextFiles[file.path] = {
      sha256: file.sha256,
      size: file.canonical.length,
      mime: file.mime,
    };
  }
  const nextManifest: Manifest = {
    ...manifest,
    treeHash: commit.treeHash,
    commitId: commit.id,
    updatedAt: new Date().toISOString(),
    files: nextFiles,
  };
  const materialized = await materializeCommit(
    context.absoluteProjectRoot,
    processed,
    nextManifest,
    materializeTool(context.backendTarget),
  );
  if (!materialized.ok) {
    return {
      ok: false,
      error: "fs_error",
      hint: !materialized.rollbackComplete
        ? `Local rollback was incomplete after the remote commit. Recovery artifacts were preserved under .conversion/transactions. Stop local edits and use ${materializeTool(context.backendTarget)} immediately. Cause: ${materialized.cause}`
        : !materialized.cleanupComplete
          ? `Local materialization failed after the remote commit and was rolled back, but transaction cleanup failed under .conversion/transactions. Recovery artifacts were preserved; use ${materializeTool(context.backendTarget)} to reconcile. Cause: ${materialized.cause}`
          : `Local materialization failed after the remote commit and was rolled back. Use ${materializeTool(context.backendTarget)} to reconcile. Cause: ${materialized.cause}`,
    };
  }

  const url = `${backendUrl}/p/${context.wsId}/${context.projId}/file/${processed[0]!.path}`;
  return {
    ok: true,
    url,
    commit_id: commit.id,
    tree_hash: commit.treeHash,
    ...(materialized.warning ? { warning: materialized.warning } : {}),
    files: processed.map((file) => ({
      path: file.path,
      sha256: file.sha256,
      size: file.canonical.length,
      mime: file.mime,
    })),
  };
}

export async function commitProjectFiles(
  input: CommitProjectFilesInput,
  context: ProjectCommitContext,
): Promise<ProjectFilesCommitOutput> {
  const validation = validateInput(input);
  if (!Array.isArray(validation)) return validation;

  let acquiredLock: SyncLock | undefined;
  if (!context.syncLock) {
    let lock: SyncLock | null;
    try {
      lock = await acquireSyncLock({
        projectRoot: context.absoluteProjectRoot,
        owner: input.syncClientId,
      });
    } catch {
      return {
        ok: false,
        error: "fs_error",
        hint: "Could not acquire the project sync lock.",
      };
    }
    if (!lock) {
      return {
        ok: false,
        error: "conflict",
        hint: "Project sync is busy; retry after the active operation releases its project lock.",
      };
    }
    acquiredLock = lock;
  }

  let result: ProjectFilesCommitOutput;
  let releaseWarning: string | undefined;
  try {
    result = await commitProjectFilesWhileLocked(input, context, validation);
  } finally {
    if (acquiredLock) {
      try {
        await acquiredLock.release();
      } catch {
        releaseWarning =
          "Project lock release failed after the save; inspect the stale lock before retrying.";
      }
    }
  }
  if (releaseWarning && result.ok) {
    return {
      ...result,
      warning: [result.warning, releaseWarning].filter(Boolean).join(" "),
    };
  }
  return result;
}
