/**
 * Conversion Agent — MCP stdio server.
 *
 * Spawned by Claude Code when the `conversion-agent` plugin is enabled (see
 * `.claude-plugin/plugin.json`). Communicates over stdio (JSON-RPC 2.0 per
 * the MCP spec) and exposes the tools listed below.
 *
 * Fase 4 (initial tools):
 *   • `get_skill_context`     — pulls the server-watermarked context for a skill.
 *   • `proxy_serper`          — Google SERP via Serper.dev.
 *   • `proxy_semrush`         — keyword metrics via Semrush.
 *   • `proxy_firecrawl`       — scrape / crawl via Firecrawl.
 *   • `project_save_and_url`  — save file into the current project + return web URL (Fase 17.5).
 *
 * Rodada 21B (ADR-011 + ADR-012) adds five tools for content discovery +
 * atomic multi-file commits:
 *   • `search_project`        — list/filter projected content (type, status, FTS).
 *   • `get_backlinks`         — inbound wikilinks + typed references for a slug.
 *   • `read_brain`            — read brain/*.md files of the current project.
 *   • `get_content`           — single projected content entity by slug.
 *   • `project_save_batch`    — atomic multi-file commit (cluster + satellites, etc.).
 *
 * All IP-sensitive logic (watermark, audit, rate-limit) lives server-side
 * (ADR-005). This process is a thin, authenticated passthrough that reads the
 * JWT from the OS keychain — the same one the CLI writes to.
 *
 * NEVER log to stdout: stdio is reserved for JSON-RPC frames. Diagnostics
 * go to stderr.
 */
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { CallToolRequestSchema, ListToolsRequestSchema } from "@modelcontextprotocol/sdk/types.js";

import { SEARCHHUB_BACKEND_URL, toolsetMode } from "./lib/config.js";
import { SEARCHHUB_HUB_FILE } from "./lib/hub.js";
import { isToolEnabled } from "./lib/toolset.js";

import {
  AUTH_LOGIN_POLL_INPUT_SCHEMA,
  AUTH_LOGIN_START_INPUT_SCHEMA,
  AUTH_STATUS_INPUT_SCHEMA,
  runAuthLoginPoll,
  runAuthLoginStart,
  runAuthStatus,
  type AuthLoginPollInput,
  type AuthLoginStartInput,
  type AuthStatusInput,
} from "./tools/auth.js";
import {
  GET_ACTIVE_PROJECT_INPUT_SCHEMA,
  runGetActiveProject,
  type GetActiveProjectInput,
} from "./tools/get-active-project.js";
import {
  GET_BACKLINKS_INPUT_SCHEMA,
  runGetBacklinks,
  type GetBacklinksInput,
} from "./tools/get-backlinks.js";
import {
  GET_CONTENT_INPUT_SCHEMA,
  runGetContent,
  type GetContentInput,
} from "./tools/get-content.js";
import {
  GET_SKILL_CONTEXT_INPUT_SCHEMA,
  runGetSkillContext,
  type GetSkillContextInput,
} from "./tools/get-skill-context.js";
import {
  PROJECT_SAVE_AND_URL_INPUT_SCHEMA,
  runProjectSaveAndUrl,
  type ProjectSaveAndUrlInput,
} from "./tools/project-save-and-url.js";
import {
  PROJECT_SAVE_BATCH_INPUT_SCHEMA,
  runProjectSaveBatch,
  type ProjectSaveBatchInput,
} from "./tools/project-save-batch.js";
import {
  PACKAGE_ON_PAGE_OPTIMIZATION_INPUT_SCHEMA,
  runPackageOnPageOptimization,
  type PackageOnPageOptimizationInput,
} from "./tools/package-on-page-optimization.js";
import {
  PROXY_FIRECRAWL_INPUT_SCHEMA,
  runProxyFirecrawl,
  type ProxyFirecrawlInput,
} from "./tools/proxy-firecrawl.js";
import {
  PROXY_SEMRUSH_INPUT_SCHEMA,
  runProxySemrush,
  type ProxySemrushInput,
} from "./tools/proxy-semrush.js";
import {
  PROXY_SERPER_INPUT_SCHEMA,
  runProxySerper,
  type ProxySerperInput,
} from "./tools/proxy-serper.js";
import {
  ENSURE_BRAIN_VAULT_INPUT_SCHEMA,
  runEnsureBrainVault,
  type EnsureBrainVaultInput,
} from "./tools/ensure-brain-vault.js";
import { READ_BRAIN_INPUT_SCHEMA, runReadBrain, type ReadBrainInput } from "./tools/read-brain.js";
import {
  SEARCH_PROJECT_INPUT_SCHEMA,
  runSearchProject,
  type SearchProjectInput,
} from "./tools/search-project.js";
import {
  SET_ACTIVE_PROJECT_INPUT_SCHEMA,
  runSetActiveProject,
  type SetActiveProjectInput,
} from "./tools/set-active-project.js";
import {
  LIST_WORKSPACES_PROJECTS_INPUT_SCHEMA,
  MATERIALIZE_PROJECT_INPUT_SCHEMA,
  SYNC_DOCTOR_INPUT_SCHEMA,
  SYNC_PAUSE_INPUT_SCHEMA,
  SYNC_REPAIR_INPUT_SCHEMA,
  SYNC_RESUME_INPUT_SCHEMA,
  SYNC_STATUS_INPUT_SCHEMA,
  runListWorkspacesProjects,
  runMaterializeProject,
  runSyncDoctor,
  runSyncPause,
  runSyncRepair,
  runSyncResume,
  runSyncStatus,
  runSearchHubListWorkspacesProjects,
  runSearchHubMaterializeProject,
  runSearchHubSyncDoctor,
  runSearchHubSyncPause,
  runSearchHubSyncRepair,
  runSearchHubSyncResume,
  runSearchHubSyncStatus,
  type MaterializeProjectInput,
  type ProjectScopeOptionalInput,
  type SyncDoctorInput,
} from "./tools/sync.js";
import {
  runSearchHubEnsureBrainVault,
  runSearchHubGetActiveProject,
  runSearchHubProjectSaveAndUrl,
  runSearchHubProjectSaveBatch,
  runSearchHubPackageOnPageOptimization,
  runSearchHubSetActiveProject,
} from "./tools/searchhub-projects.js";

const SERVER_NAME = "conversion-context";
const SERVER_VERSION = "0.1.0";

function sharedReadTarget() {
  return toolsetMode() === "searchhub"
    ? {
        backendUrl: SEARCHHUB_BACKEND_URL ?? "http://searchhub-backend-not-configured.invalid",
        hubFile: SEARCHHUB_HUB_FILE,
        materializeTool: "searchhub_materialize_project",
      }
    : {};
}

/** Build a fresh server + register handlers. Exported for integration tests. */
export function buildServer(): Server {
  const server = new Server(
    { name: SERVER_NAME, version: SERVER_VERSION },
    { capabilities: { tools: {} } },
  );

  server.setRequestHandler(ListToolsRequestSchema, async () => {
    const tools = [
      {
        name: "get_skill_context",
        description:
          "Fetches the Conversion-proprietary context (methodology, prompts, " +
          "quality gates, guardrails) for a named skill. Call this FIRST when " +
          "the user invokes a Conversion skill.",
        inputSchema: GET_SKILL_CONTEXT_INPUT_SCHEMA,
      },
      {
        name: "auth_status",
        description:
          "Returns whether the plugin has a Conversion session in plugin data or fallback keychain.",
        inputSchema: AUTH_STATUS_INPUT_SCHEMA,
      },
      {
        name: "auth_login_start",
        description:
          "Starts plugin-first magic-link auth and returns the polling state. The token is stored in plugin data after auth_login_poll succeeds.",
        inputSchema: AUTH_LOGIN_START_INPUT_SCHEMA,
      },
      {
        name: "auth_login_poll",
        description:
          "Polls magic-link auth and stores the returned token in the Claude plugin data directory.",
        inputSchema: AUTH_LOGIN_POLL_INPUT_SCHEMA,
      },
      {
        name: "proxy_serper",
        description:
          "Performs a Google SERP search via Serper.dev. Defaults: gl='br', " +
          "hl='pt-br'. Use while applying a Conversion skill to ground the " +
          "output in real search results.",
        inputSchema: PROXY_SERPER_INPUT_SCHEMA,
      },
      {
        name: "proxy_semrush",
        description:
          "Queries Semrush for keyword volume, difficulty and related terms. " +
          "Returns CSV wrapped in `{csv: '...'}`.",
        inputSchema: PROXY_SEMRUSH_INPUT_SCHEMA,
      },
      {
        name: "proxy_firecrawl",
        description:
          "Scrapes or crawls a URL via Firecrawl. Use mode='scrape' for a " +
          "single page, mode='crawl' for multi-page extraction.",
        inputSchema: PROXY_FIRECRAWL_INPUT_SCHEMA,
      },
      {
        name: "project_save_and_url",
        description:
          "Saves a file within the current Conversion project, pushes a " +
          "commit to the backend, and returns a web URL where the file can " +
          "be viewed or edited. Use this instead of the Write tool when the " +
          "skill output needs to be shared with collaborators.",
        inputSchema: PROJECT_SAVE_AND_URL_INPUT_SCHEMA,
      },
      {
        name: "search_project",
        description:
          "Lists content items of the current project (artigos, clusters, " +
          "newsletters, brain files). Filter by `type`, `status`, or full-text " +
          "`query`. Returns a paginated envelope `{items, total}`.",
        inputSchema: SEARCH_PROJECT_INPUT_SCHEMA,
      },
      {
        name: "get_backlinks",
        description:
          "Returns every inbound wikilink or typed reference pointing to the " +
          "given slug inside the current project. Use to detect orphan links " +
          "or to find which clusters reference an article.",
        inputSchema: GET_BACKLINKS_INPUT_SCHEMA,
      },
      {
        name: "ensure_brain_vault",
        description:
          "Idempotently bootstraps the brain proof vault (`brain/provas.md` + " +
          "`brain/fontes.md`) for a project. Reads the backend brain and " +
          "commits only the missing vault files in one atomic commit; if both " +
          "already exist it is a no-op. Seeding NEVER enables fact-checking. " +
          "Call once when a project becomes active so the AI starts work with " +
          "the proof vault wired.",
        inputSchema: ENSURE_BRAIN_VAULT_INPUT_SCHEMA,
      },
      {
        name: "read_brain",
        description:
          "Reads the `brain/` files of the current project (core voice files " +
          "plus optional proof/source files). Call FIRST in every content " +
          "skill to ground outputs in the client's voice. Pass `collection` " +
          "to restrict to one type.",
        inputSchema: READ_BRAIN_INPUT_SCHEMA,
      },
      {
        name: "get_content",
        description:
          "Fetches a single projected content entity by slug. Returns " +
          "frontmatter + a 500-char body preview.",
        inputSchema: GET_CONTENT_INPUT_SCHEMA,
      },
      {
        name: "project_save_batch",
        description:
          "Atomic multi-file commit — use when a skill must update several " +
          "files at once (e.g. writing a satellite article AND updating the " +
          "cluster's `references.satelites`). Returns the new commit id + the " +
          "web URL of the first file in the batch.",
        inputSchema: PROJECT_SAVE_BATCH_INPUT_SCHEMA,
      },
      {
        name: "package_on_page_optimization",
        description:
          "Validates and packages an approved on-page optimization run from canonical project files, then commits all generated artifacts atomically. It reads only ws_slug, proj_slug and run_slug and cannot accept arbitrary content or bytes.",
        inputSchema: PACKAGE_ON_PAGE_OPTIMIZATION_INPUT_SCHEMA,
      },
      {
        name: "get_active_project",
        description:
          "Reads the project pinned as 'active' inside the current hub " +
          "(`<hub>/.conversion-hub.json#active`). Call this FIRST before " +
          "asking the user which project to work on — when one has " +
          "already been pinned via `set_active_project`, follow it without " +
          "asking. Returns `{active: {ws_slug, proj_slug, ws_id, proj_id}}` " +
          "or `{active: null}`.",
        inputSchema: GET_ACTIVE_PROJECT_INPUT_SCHEMA,
      },
      {
        name: "set_active_project",
        description:
          "Pins a project as active inside the current hub. The pair " +
          "`(ws_slug, proj_slug)` must already be materialized — if not, " +
          "returns `project_not_in_hub` with a hint to use the " +
          "`materialize_project` MCP tool. Use when the user explicitly " +
          "switches projects mid-session.",
        inputSchema: SET_ACTIVE_PROJECT_INPUT_SCHEMA,
      },
      {
        name: "list_workspaces_projects",
        description:
          "Lists workspaces and projects visible to the authenticated user for explicit materialization.",
        inputSchema: LIST_WORKSPACES_PROJECTS_INPUT_SCHEMA,
      },
      {
        name: "materialize_project",
        description:
          "Materializes a remote project into the current hub by downloading canonical sync blobs and writing the local manifest.",
        inputSchema: MATERIALIZE_PROJECT_INPUT_SCHEMA,
      },
      {
        name: "sync_status",
        description: "Reads local sync status for the active or specified materialized project.",
        inputSchema: SYNC_STATUS_INPUT_SCHEMA,
      },
      {
        name: "sync_doctor",
        description:
          "Diagnoses the plugin sync monitor: selected projects, auth source, plugin version freshness, remote mode, locks, status files, and recent logs.",
        inputSchema: SYNC_DOCTOR_INPUT_SCHEMA,
      },
      {
        name: "sync_pause",
        description: "Pauses local sync for the active or specified materialized project.",
        inputSchema: SYNC_PAUSE_INPUT_SCHEMA,
      },
      {
        name: "sync_resume",
        description: "Resumes local sync for the active or specified materialized project.",
        inputSchema: SYNC_RESUME_INPUT_SCHEMA,
      },
      {
        name: "sync_repair",
        description:
          "Reports sync repair status or resumes sync after the user resolves conflict snapshots locally.",
        inputSchema: SYNC_REPAIR_INPUT_SCHEMA,
      },
    ];
    const searchHubTools = tools
      .filter((tool) =>
        [
          "project_save_and_url",
          "project_save_batch",
          "package_on_page_optimization",
          "ensure_brain_vault",
          "list_workspaces_projects",
          "materialize_project",
          "get_active_project",
          "set_active_project",
          "sync_status",
          "sync_doctor",
          "sync_pause",
          "sync_resume",
          "sync_repair",
        ].includes(tool.name),
      )
      .map((tool) => ({
        ...tool,
        name: `searchhub_${tool.name}`,
        description: `SearchHub-only: ${tool.description}`,
      }));
    const mode = toolsetMode();
    return {
      tools: [...tools, ...searchHubTools].filter((tool) => isToolEnabled(tool.name, mode)),
    };
  });

  server.setRequestHandler(CallToolRequestSchema, async (request) => {
    const { name, arguments: args } = request.params;
    const safeArgs = (args ?? {}) as Record<string, unknown>;

    if (!isToolEnabled(name, toolsetMode())) {
      return {
        isError: true,
        content: [
          {
            type: "text",
            text: JSON.stringify({
              ok: false,
              error: "unknown_tool",
              hint: `No such tool: ${name}`,
            }),
          },
        ],
      };
    }

    let result: unknown;
    switch (name) {
      case "get_skill_context":
        result = await runGetSkillContext(safeArgs as unknown as GetSkillContextInput);
        break;
      case "auth_status":
        result = await runAuthStatus(safeArgs as unknown as AuthStatusInput);
        break;
      case "auth_login_start":
        result = await runAuthLoginStart(safeArgs as unknown as AuthLoginStartInput);
        break;
      case "auth_login_poll":
        result = await runAuthLoginPoll(safeArgs as unknown as AuthLoginPollInput);
        break;
      case "proxy_serper":
        result = await runProxySerper(safeArgs as unknown as ProxySerperInput);
        break;
      case "proxy_semrush":
        result = await runProxySemrush(safeArgs as unknown as ProxySemrushInput);
        break;
      case "proxy_firecrawl":
        result = await runProxyFirecrawl(safeArgs as unknown as ProxyFirecrawlInput);
        break;
      case "project_save_and_url":
        result = await runProjectSaveAndUrl(safeArgs as unknown as ProjectSaveAndUrlInput);
        break;
      case "search_project":
        result = await runSearchProject(
          safeArgs as unknown as SearchProjectInput,
          process.cwd(),
          sharedReadTarget(),
        );
        break;
      case "get_backlinks":
        result = await runGetBacklinks(
          safeArgs as unknown as GetBacklinksInput,
          process.cwd(),
          sharedReadTarget(),
        );
        break;
      case "ensure_brain_vault":
        result = await runEnsureBrainVault(safeArgs as unknown as EnsureBrainVaultInput);
        break;
      case "read_brain":
        result = await runReadBrain(
          safeArgs as unknown as ReadBrainInput,
          process.cwd(),
          sharedReadTarget(),
        );
        break;
      case "get_content":
        result = await runGetContent(
          safeArgs as unknown as GetContentInput,
          process.cwd(),
          sharedReadTarget(),
        );
        break;
      case "project_save_batch":
        result = await runProjectSaveBatch(safeArgs as unknown as ProjectSaveBatchInput);
        break;
      case "package_on_page_optimization":
        result = await runPackageOnPageOptimization(
          safeArgs as unknown as PackageOnPageOptimizationInput,
        );
        break;
      case "get_active_project":
        result = await runGetActiveProject(safeArgs as unknown as GetActiveProjectInput);
        break;
      case "set_active_project":
        result = await runSetActiveProject(safeArgs as unknown as SetActiveProjectInput);
        break;
      case "list_workspaces_projects":
        result = await runListWorkspacesProjects();
        break;
      case "materialize_project":
        result = await runMaterializeProject(safeArgs as unknown as MaterializeProjectInput);
        break;
      case "sync_status":
        result = await runSyncStatus(safeArgs as unknown as ProjectScopeOptionalInput);
        break;
      case "sync_doctor":
        result = await runSyncDoctor(safeArgs as unknown as SyncDoctorInput);
        break;
      case "sync_pause":
        result = await runSyncPause(
          safeArgs as unknown as ProjectScopeOptionalInput & { reason?: string },
        );
        break;
      case "sync_resume":
        result = await runSyncResume(safeArgs as unknown as ProjectScopeOptionalInput);
        break;
      case "sync_repair":
        result = await runSyncRepair(
          safeArgs as unknown as ProjectScopeOptionalInput & {
            action?: "status" | "resume";
          },
        );
        break;
      case "searchhub_project_save_and_url":
        result = await runSearchHubProjectSaveAndUrl(safeArgs as unknown as ProjectSaveAndUrlInput);
        break;
      case "searchhub_project_save_batch":
        result = await runSearchHubProjectSaveBatch(safeArgs as unknown as ProjectSaveBatchInput);
        break;
      case "searchhub_package_on_page_optimization":
        result = await runSearchHubPackageOnPageOptimization(
          safeArgs as unknown as PackageOnPageOptimizationInput,
        );
        break;
      case "searchhub_ensure_brain_vault":
        result = await runSearchHubEnsureBrainVault(safeArgs as unknown as EnsureBrainVaultInput);
        break;
      case "searchhub_get_active_project":
        result = await runSearchHubGetActiveProject(safeArgs as unknown as GetActiveProjectInput);
        break;
      case "searchhub_set_active_project":
        result = await runSearchHubSetActiveProject(safeArgs as unknown as SetActiveProjectInput);
        break;
      case "searchhub_list_workspaces_projects":
        result = await runSearchHubListWorkspacesProjects();
        break;
      case "searchhub_materialize_project":
        result = await runSearchHubMaterializeProject(
          safeArgs as unknown as MaterializeProjectInput,
        );
        break;
      case "searchhub_sync_status":
        result = await runSearchHubSyncStatus(safeArgs as unknown as ProjectScopeOptionalInput);
        break;
      case "searchhub_sync_doctor":
        result = await runSearchHubSyncDoctor(safeArgs as unknown as SyncDoctorInput);
        break;
      case "searchhub_sync_pause":
        result = await runSearchHubSyncPause(
          safeArgs as unknown as ProjectScopeOptionalInput & { reason?: string },
        );
        break;
      case "searchhub_sync_resume":
        result = await runSearchHubSyncResume(safeArgs as unknown as ProjectScopeOptionalInput);
        break;
      case "searchhub_sync_repair":
        result = await runSearchHubSyncRepair(
          safeArgs as unknown as ProjectScopeOptionalInput & {
            action?: "status" | "resume";
          },
        );
        break;
      default:
        return {
          isError: true,
          content: [
            {
              type: "text",
              text: JSON.stringify({
                ok: false,
                error: "unknown_tool",
                hint: `No such tool: ${name}`,
              }),
            },
          ],
        };
    }

    const envelope = result as { ok: boolean };
    return {
      isError: envelope.ok === false,
      content: [{ type: "text", text: JSON.stringify(result) }],
    };
  });

  return server;
}

export async function main(): Promise<void> {
  const server = buildServer();
  const transport = new StdioServerTransport();
  await server.connect(transport);

  const shutdown = (signal: string): void => {
    process.stderr.write(`[conversion-mcp] received ${signal}, shutting down.\n`);
    transport
      .close()
      .catch(() => undefined)
      .finally(() => process.exit(0));
  };
  process.once("SIGINT", () => shutdown("SIGINT"));
  process.once("SIGTERM", () => shutdown("SIGTERM"));
}

// Only auto-start when executed as the entry point, not when imported by tests.
// Accept either the bundled dist entry or the bin.js wrapper used by the npm
// published package. Tests import buildServer directly and therefore never
// trigger this branch.
const invokedDirectly =
  typeof process.argv[1] === "string" &&
  (process.argv[1].endsWith("/dist/index.js") ||
    process.argv[1].endsWith("\\dist\\index.js") ||
    process.argv[1].endsWith("/bin.js") ||
    process.argv[1].endsWith("\\bin.js"));

if (invokedDirectly) {
  main().catch((err) => {
    process.stderr.write(
      `[conversion-mcp] fatal: ${err instanceof Error ? err.message : String(err)}\n`,
    );
    process.exit(1);
  });
}
