/** Core logic for the public text-only `project_save_and_url` MCP tool. */
import { commitProjectFiles, type ProjectCommitContext } from "./project-commit.js";

/** Tool input shape as declared in the JSON Schema. */
export interface ProjectSaveInput {
  path: string;
  content: string;
  message?: string;
}

/** Resolved coordinates passed in by the tool handler. */
export type ProjectSaveContext = ProjectCommitContext;

/** Public output contract retained for `project_save_and_url`. */
export type ProjectSaveOutput =
  | {
      ok: true;
      url: string;
      sha256: string;
      commit_id: string;
    }
  | {
      ok: false;
      error:
        | "not_authenticated"
        | "session_expired"
        | "rate_limited"
        | "invalid_path"
        | "invalid_manifest"
        | "conflict"
        | "backend_error"
        | "network_error"
        | "fs_error"
        | "bad_input";
      hint?: string;
      retry_after_sec?: number;
      server_head?: { commitId: string; treeHash: string } | null;
    };

export async function runProjectSave(
  input: ProjectSaveInput,
  context: ProjectSaveContext,
): Promise<ProjectSaveOutput> {
  if (!input || typeof input.path !== "string" || typeof input.content !== "string") {
    return {
      ok: false,
      error: "bad_input",
      hint: "Fields 'path' (string) and 'content' (string) are required.",
    };
  }

  const result = await commitProjectFiles(
    {
      files: [{ path: input.path, bytes: Buffer.from(input.content, "utf8") }],
      message: input.message,
      syncClientId: "mcp-project-save",
    },
    context,
  );
  if (!result.ok) {
    if (result.error === "duplicate_path") {
      return { ok: false, error: "bad_input", hint: result.hint };
    }
    return {
      ok: false,
      error: result.error,
      hint: result.hint,
      retry_after_sec: result.retry_after_sec,
      server_head: result.server_head,
    };
  }

  return {
    ok: true,
    url: result.url,
    sha256: result.files[0]!.sha256,
    commit_id: result.commit_id,
  };
}
