import { acquireSyncLock, type SyncLock } from "@agenciaconversion/local-sync";

import { BACKEND_URL } from "../lib/config.js";
import {
  commitProjectFiles,
  manifestMatchesProjectScope,
  readProjectManifestSnapshot,
} from "../lib/project-commit.js";
import { PROJECT_SCOPE_SCHEMA_FRAGMENT, resolveProjectScope } from "../lib/project-scope.js";
import { isValidOnPageRunSlug, ON_PAGE_RUN_SLUG_PATTERN_SOURCE } from "../on-page/contracts.js";
import { buildOnPagePackage } from "../on-page/package.js";

export interface PackageOnPageOptimizationInput {
  ws_slug: string;
  proj_slug: string;
  run_slug: string;
}

type PackageOnPageOptimizationError =
  | "bad_input"
  | "invalid_run"
  | "missing_source"
  | "qa_blocked"
  | "invalid_redline"
  | "render_error"
  | "not_authenticated"
  | "session_expired"
  | "rate_limited"
  | "not_in_hub"
  | "project_not_in_hub"
  | "conflict"
  | "backend_error"
  | "network_error"
  | "fs_error";

export type PackageOnPageOptimizationOutput =
  | {
      ok: true;
      run_slug: string;
      url: string;
      commit_id: string;
      tree_hash: string;
      artifacts: Array<{
        path: string;
        sha256: string;
        size: number;
        mime: string;
      }>;
      warning?: string;
    }
  | {
      ok: false;
      error: PackageOnPageOptimizationError;
      hint?: string;
      retry_after_sec?: number;
      server_head?: { commitId: string; treeHash: string } | null;
    };

export interface PackageOnPageOptimizationTarget {
  backendUrl?: string | (() => string);
  hubFile?: string;
  materializeTool?: string;
  backendTarget?: "legacy" | "searchhub";
}

export const PACKAGE_ON_PAGE_OPTIMIZATION_INPUT_SCHEMA = {
  type: "object",
  properties: {
    ...PROJECT_SCOPE_SCHEMA_FRAGMENT,
    run_slug: {
      type: "string",
      description:
        "Canonical resumable run slug under deliverables/otimizacoes. The tool reads the run files itself.",
      pattern: ON_PAGE_RUN_SLUG_PATTERN_SOURCE,
    },
  },
  required: ["ws_slug", "proj_slug", "run_slug"],
  additionalProperties: false,
} as const;

const INPUT_KEYS = new Set(["ws_slug", "proj_slug", "run_slug"]);

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function validateInput(input: unknown): PackageOnPageOptimizationOutput | null {
  if (!isPlainRecord(input)) return { ok: false, error: "bad_input" };
  if (Object.keys(input).some((key) => !INPUT_KEYS.has(key))) {
    return { ok: false, error: "bad_input" };
  }
  if (!isValidOnPageRunSlug(input.run_slug)) return { ok: false, error: "invalid_run" };
  if (
    typeof input.ws_slug !== "string" ||
    input.ws_slug.length === 0 ||
    typeof input.proj_slug !== "string" ||
    input.proj_slug.length === 0
  ) {
    return { ok: false, error: "bad_input" };
  }
  return null;
}

function snapshotConflict(materializeTool: string): PackageOnPageOptimizationOutput {
  return {
    ok: false,
    error: "conflict",
    hint: `The local project snapshot is stale or belongs to another scope; use the \`${materializeTool}\` MCP tool and try again.`,
  };
}

function mapPackageError(error: unknown, materializeTool: string): PackageOnPageOptimizationOutput {
  const message = error instanceof Error ? error.message : "";
  if (message === "snapshot_conflict") return snapshotConflict(materializeTool);
  if (message === "qa_blocked") return { ok: false, error: "qa_blocked" };
  if (message === "invalid_redline") return { ok: false, error: "invalid_redline" };
  if (message === "invalid_run_slug" || message === "invalid_manifest") {
    return { ok: false, error: "invalid_run" };
  }
  if (message.startsWith("missing_source:")) {
    return { ok: false, error: "missing_source" };
  }
  return { ok: false, error: "render_error" };
}

const HEARTBEAT_INTERVAL_MS = 15_000;

async function acquirePackageLock(
  projectRoot: string,
): Promise<SyncLock | PackageOnPageOptimizationOutput> {
  try {
    const lock = await acquireSyncLock({ projectRoot, owner: "mcp-on-page-package" });
    if (lock) return lock;
    return {
      ok: false,
      error: "conflict",
      hint: "Project sync is busy; retry after the active operation releases its project lock.",
    };
  } catch {
    return { ok: false, error: "fs_error", hint: "Could not acquire the project sync lock." };
  }
}

function isPackageOutput(
  value: SyncLock | PackageOnPageOptimizationOutput,
): value is PackageOnPageOptimizationOutput {
  return "ok" in value;
}

export async function runPackageOnPageOptimization(
  input: PackageOnPageOptimizationInput,
  cwd = process.cwd(),
  target: PackageOnPageOptimizationTarget = {},
): Promise<PackageOnPageOptimizationOutput> {
  const invalid = validateInput(input);
  if (invalid) return invalid;

  const scope = await resolveProjectScope(input, cwd, target.hubFile, target.materializeTool);
  if (!scope.ok) return scope;
  const backendTarget = target.backendTarget ?? "legacy";
  const materializeTool =
    target.materializeTool ??
    (backendTarget === "searchhub" ? "searchhub_materialize_project" : "materialize_project");
  const acquired = await acquirePackageLock(scope.project_root);
  if (isPackageOutput(acquired)) return acquired;

  const lock = acquired;
  const inFlightHeartbeats = new Set<Promise<void>>();
  const trackHeartbeat = (): Promise<void> => {
    let pending!: Promise<void>;
    pending = lock.heartbeat().finally(() => {
      inFlightHeartbeats.delete(pending);
    });
    inFlightHeartbeats.add(pending);
    return pending;
  };
  const heartbeat = setInterval(() => {
    void trackHeartbeat().catch(() => undefined);
  }, HEARTBEAT_INTERVAL_MS);
  heartbeat.unref();

  let result: PackageOnPageOptimizationOutput;
  try {
    await trackHeartbeat();
    const snapshot = await readProjectManifestSnapshot(scope.project_root);
    if (
      !snapshot ||
      !manifestMatchesProjectScope(snapshot.manifest, {
        wsId: scope.ws_id,
        projId: scope.proj_id,
        wsSlug: input.ws_slug,
        projSlug: input.proj_slug,
        backendTarget,
      })
    ) {
      result = snapshotConflict(materializeTool);
    } else {
      let backendUrl: string;
      try {
        backendUrl =
          typeof target.backendUrl === "function"
            ? target.backendUrl()
            : (target.backendUrl ?? BACKEND_URL);
      } catch {
        result = { ok: false, error: "backend_error" };
        backendUrl = "";
      }

      if (!backendUrl) {
        result = { ok: false, error: "backend_error" };
      } else {
        let built: Awaited<ReturnType<typeof buildOnPagePackage>> | null = null;
        try {
          built = await buildOnPagePackage(scope.project_root, input.run_slug, snapshot);
        } catch (error) {
          result = mapPackageError(error, materializeTool);
        }

        if (built) {
          await trackHeartbeat();
          const committed = await commitProjectFiles(
            {
              files: built.files,
              message: `feat(on-page): package ${input.run_slug}`,
              syncClientId: "mcp-on-page-package",
            },
            {
              wsId: scope.ws_id,
              projId: scope.proj_id,
              wsSlug: input.ws_slug,
              projSlug: input.proj_slug,
              absoluteProjectRoot: scope.project_root,
              backendUrl,
              backendTarget,
              expectedManifest: snapshot,
              syncLock: lock,
            },
          );
          if (!committed.ok) {
            switch (committed.error) {
              case "not_authenticated":
              case "session_expired":
              case "rate_limited":
              case "conflict":
              case "backend_error":
              case "network_error":
              case "fs_error":
                result = {
                  ok: false,
                  error: committed.error,
                  ...(committed.hint ? { hint: committed.hint } : {}),
                  ...(committed.retry_after_sec !== undefined
                    ? { retry_after_sec: committed.retry_after_sec }
                    : {}),
                  ...(committed.server_head !== undefined
                    ? { server_head: committed.server_head }
                    : {}),
                };
                break;
              default:
                result = { ok: false, error: "backend_error" };
            }
          } else {
            const artifactPaths = new Set(Object.values(built.manifest.artifacts));
            result = {
              ok: true,
              run_slug: input.run_slug,
              url: committed.url,
              commit_id: committed.commit_id,
              tree_hash: committed.tree_hash,
              artifacts: committed.files.filter((file) => artifactPaths.has(file.path)),
              ...(committed.warning ? { warning: committed.warning } : {}),
            };
          }
        }
      }
    }
  } catch {
    result = { ok: false, error: "fs_error", hint: "Project lock heartbeat failed." };
  } finally {
    clearInterval(heartbeat);
    await Promise.allSettled([...inFlightHeartbeats]);
  }

  try {
    await lock.release();
  } catch {
    if (result!.ok) {
      return {
        ...result!,
        warning: [
          result!.warning,
          "Project lock release failed after the package commit succeeded; inspect the stale lock and do not retry the package.",
        ]
          .filter(Boolean)
          .join(" "),
      };
    }
    return { ok: false, error: "fs_error", hint: "Could not release the project sync lock." };
  }
  return result!;
}
