/**
 * Tool: `set_active_project` (Rodada 22N).
 *
 * Pina um project como ativo no `<hubRoot>/.conversion-hub.json`. O
 * Consultor pode invocar esta tool quando usuário troca de project mid-
 * sessão (skill `/projeto` ou solicitação direta) — sem precisar de
 * nenhum passo manual.
 *
 * Validação dura: o pair `(ws_slug, proj_slug)` PRECISA estar em
 * `projects[]`. Se não está, retornamos `project_not_in_hub` com hint
 * pedindo para usar a ferramenta `materialize_project`. Não materializamos
 * automaticamente aqui — a materialização é responsabilidade da ferramenta
 * `materialize_project` (escreve arquivos, pode levar tempo, etc.).
 */
import {
  HUB_FILE,
  ProjectNotMaterializedError,
  findHubRoot,
  setActiveProject,
} from "../lib/hub.js";

export interface SetActiveProjectInput {
  ws_slug: string;
  proj_slug: string;
}

export type SetActiveProjectOutput =
  | {
      ok: true;
      active: { ws_slug: string; proj_slug: string };
      hub_root: string;
    }
  | {
      ok: false;
      error:
        | "bad_input"
        | "not_in_hub"
        | "project_not_in_hub"
        | "unknown_error";
      hint: string;
    };

export const SET_ACTIVE_PROJECT_INPUT_SCHEMA = {
  type: "object",
  properties: {
    ws_slug: {
      type: "string",
      description:
        "Workspace slug do project a ativar (ex: 'acme'). Deve já estar materializado neste hub.",
      minLength: 1,
    },
    proj_slug: {
      type: "string",
      description:
        "Project slug do project a ativar (ex: 'site'). Deve já estar materializado neste hub.",
      minLength: 1,
    },
  },
  required: ["ws_slug", "proj_slug"],
  additionalProperties: false,
} as const;

export async function runSetActiveProject(
  input: SetActiveProjectInput,
  cwd: string = process.cwd(),
  hubFile: string = HUB_FILE,
  materializeTool = "materialize_project",
): Promise<SetActiveProjectOutput> {
  if (!input || typeof input !== "object") {
    return {
      ok: false,
      error: "bad_input",
      hint: "Input deve ser objeto com 'ws_slug' e 'proj_slug'.",
    };
  }
  const ws = input.ws_slug;
  const proj = input.proj_slug;
  if (typeof ws !== "string" || ws.length === 0) {
    return {
      ok: false,
      error: "bad_input",
      hint: "Campo 'ws_slug' (string) é obrigatório.",
    };
  }
  if (typeof proj !== "string" || proj.length === 0) {
    return {
      ok: false,
      error: "bad_input",
      hint: "Campo 'proj_slug' (string) é obrigatório.",
    };
  }

  const hubRoot = await findHubRoot(cwd, hubFile);
  if (!hubRoot) {
    return {
      ok: false,
      error: "not_in_hub",
      hint: `Não encontrei ${hubFile}. Use a ferramenta \`${materializeTool}\` primeiro.`,
    };
  }

  try {
    await setActiveProject(hubRoot, ws, proj, hubFile);
    return {
      ok: true,
      active: { ws_slug: ws, proj_slug: proj },
      hub_root: hubRoot,
    };
  } catch (err) {
    if (err instanceof ProjectNotMaterializedError) {
      return {
        ok: false,
        error: "project_not_in_hub",
        hint: `Project '${ws}/${proj}' não está materializado neste hub. Use a ferramenta \`materialize_project\` primeiro.`,
      };
    }
    const detail = err instanceof Error ? err.message : String(err);
    return { ok: false, error: "unknown_error", hint: detail };
  }
}
