/**
 * Tool: `proxy_firecrawl` — Firecrawl scrape/crawl.
 *
 * Passthrough to `POST /api/v1/apis/firecrawl`. Mode selects which upstream
 * endpoint the backend calls. Validation happens server-side; we only
 * check the two required fields up front so we can fail fast.
 */
import { authenticatedJson } from "../lib/api.js";

import { mapProxyError } from "./proxy-serper.js";

export const PROXY_FIRECRAWL_INPUT_SCHEMA = {
  type: "object",
  properties: {
    url: { type: "string", description: "Target URL to scrape or crawl." },
    mode: {
      type: "string",
      description: "'scrape' for one page, 'crawl' for multiple.",
      enum: ["scrape", "crawl"],
    },
  },
  required: ["url", "mode"],
  additionalProperties: true,
} as const;

export interface ProxyFirecrawlInput {
  url: string;
  mode: "scrape" | "crawl";
  [k: string]: unknown;
}

export type ProxyFirecrawlOutput =
  | { ok: true; data: unknown }
  | { ok: false; error: string; hint?: string; retry_after_sec?: number };

export async function runProxyFirecrawl(
  input: ProxyFirecrawlInput,
): Promise<ProxyFirecrawlOutput> {
  if (typeof input.url !== "string" || input.url.length === 0) {
    return { ok: false, error: "bad_input", hint: "Field 'url' is required." };
  }
  if (input.mode !== "scrape" && input.mode !== "crawl") {
    return {
      ok: false,
      error: "bad_input",
      hint: "Field 'mode' must be 'scrape' or 'crawl'.",
    };
  }
  try {
    const data = await authenticatedJson<unknown>("/api/v1/apis/firecrawl", {
      method: "POST",
      body: JSON.stringify(input),
    });
    return { ok: true, data };
  } catch (err) {
    return mapProxyError(err);
  }
}
