/**
 * MCP-server-wide configuration constants.
 *
 * Every knob a developer might want to override at runtime lives here. Kept
 * dependency-free so any other module can import without cycles.
 *
 * The MCP server owns these runtime constants in the plugin-first world.
 */

/**
 * Base URL of the Conversion Agent backend. Override by setting
 * `CONVERSION_BACKEND_URL` in the environment inherited by the plugin
 * process. The manifest intentionally does not pin this value so canary
 * cohorts can target another compatible backend without rebuilding the
 * plugin.
 */
export const BACKEND_URL: string = (
  process.env["CONVERSION_BACKEND_URL"] ?? "https://agent.conversion.com.br"
).replace(/\/+$/u, "");

/** SearchHub never inherits the legacy URL. Its tools fail closed when unset. */
export const SEARCHHUB_BACKEND_URL: string | null = process.env[
  "CONVERSION_SEARCHHUB_BACKEND_URL"
]
  ? process.env["CONVERSION_SEARCHHUB_BACKEND_URL"]!.replace(/\/+$/u, "")
  : null;

export type ToolsetMode = "legacy" | "parallel" | "searchhub";

export function toolsetMode(): ToolsetMode {
  const value = process.env["CONVERSION_TOOLSET_MODE"]?.trim().toLowerCase();
  return value === "legacy" || value === "searchhub" || value === "parallel"
    ? value
    : "parallel";
}

export function requireSearchHubBackendUrl(): string {
  if (!SEARCHHUB_BACKEND_URL) {
    throw new Error(
      "CONVERSION_SEARCHHUB_BACKEND_URL is required for searchhub_* tools.",
    );
  }
  return SEARCHHUB_BACKEND_URL;
}

/**
 * Headers required only when the selected backend is protected by Vercel
 * Deployment Protection. The standard Vercel variable keeps the secret out
 * of manifests, URLs and the distributed plugin.
 */
export function backendProtectionHeaders(): Record<string, string> {
  const secret = process.env["VERCEL_AUTOMATION_BYPASS_SECRET"]?.trim();
  return secret ? { "x-vercel-protection-bypass": secret } : {};
}

/**
 * Slot canônico do keychain onde o login (`auth_login_start` / `auth_login_poll`) grava o JWT.
 *
 * Rebrand 22ax: o slot foi movido de `conversion-skills` para `conversion-agent`.
 * O MCP server lê de ambos durante a janela de migração e escreve apenas no
 * canônico (renovações de token). Remover `KEYCHAIN_SERVICE_LEGACY` após
 * 2026-05-28 (30 dias).
 */
export const KEYCHAIN_SERVICE = "conversion-agent" as const;
export const KEYCHAIN_SERVICE_LEGACY = "conversion-skills" as const;

/**
 * Optional email selector. When multiple accounts exist in the keychain,
 * set `CONVERSION_EMAIL` in the plugin env block to pick a specific one.
 */
export const EMAIL_SELECTOR: string | undefined = process.env["CONVERSION_EMAIL"];

/**
 * Claude Code plugin data directory. Auth broker state lives here so normal
 * plugin-first usage does not require the global CLI or OS keychain.
 */
export const PLUGIN_DATA_DIR: string | undefined = process.env["CLAUDE_PLUGIN_DATA"];

/** TTL for cached skill-context responses. 5 min matches the server-side hint. */
export const CACHE_TTL_MS = 5 * 60 * 1000;

/**
 * Network timeout for backend calls. Backend itself runs on Vercel so the
 * request bounds are generous; we cap at 30s to avoid hanging a Claude Code
 * tool call forever when the network is unreachable.
 */
export const FETCH_TIMEOUT_MS = 30_000;
