/**
 * @agenciaconversion/shared — types, constants and utils shared across the monorepo.
 *
 * This package is the single source of truth for wire-format contracts
 * (e.g. `SkillContextV1`, mirrored from
 * `docs/wiki/api-contracts/skill-context-v1.md §Response Shape`) and for the
 * very small set of cross-cutting constants (e.g. the email whitelist domain).
 *
 * Fase 16b additions: path validation, canonicalization, sync/commit wire
 * contracts and manifest shape. These MUST stay byte-identical to the
 * backend implementations in `apps/backend/src/lib/{paths,blobs,commits}/*`
 * — CLI and backend share these definitions to guarantee the same hashes.
 */

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Email domain whitelisted for magic-link auth (see ADR-003). */
export const WHITELIST_DOMAIN = "conversion.com.br";

/** Current major version of the skill-context wire contract. */
export const SKILL_CONTEXT_VERSION = "v1" as const;

// ---------------------------------------------------------------------------
// Types — mirrored 1:1 from docs/wiki/api-contracts/skill-context-v1.md
// ---------------------------------------------------------------------------

/**
 * Hint about a proxy tool that the Claude Code agent can invoke while running
 * the skill. The concrete implementation lives in the backend as a REST proxy
 * (see `/v1/apis/*`).
 */
export interface SkillToolHint {
  name: string;
  description: string;
  invocation_example?: string;
}

/**
 * One quality gate that the skill output must satisfy before being delivered
 * to the user.
 */
export interface SkillQualityGate {
  id: string;
  description: string;
  check: string;
}

/**
 * Debug payload — present only when `?dev=true` and the backend is in
 * staging mode. Never exposed in production responses.
 */
export interface SkillContextDebug {
  watermark_layers_applied: string[];
  canaries_included: string[];
  rate_limit_remaining: number;
}

/**
 * Response shape of `GET /v1/skills/:name/context`.
 *
 * @see docs/wiki/api-contracts/skill-context-v1.md
 */
export interface SkillContextV1 {
  version: "v1";
  skill: string;
  request_id: string;
  issued_at: string;
  expires_at: string;
  watermark_id: string;
  guardrail: string;
  methodology: string;
  prompts: Record<string, string>;
  tools_available: SkillToolHint[];
  quality_gates: SkillQualityGate[];
  output_schema?: Record<string, unknown>;
  _debug?: SkillContextDebug;
}

// ---------------------------------------------------------------------------
// Utilities
// ---------------------------------------------------------------------------

/**
 * Returns `true` iff `email` is a syntactically plausible address whose domain
 * matches the Conversion whitelist (case-insensitive).
 *
 * The regex is intentionally conservative — server-side we also validate with
 * a proper email parser before issuing a magic link.
 */
export function isValidConversionEmail(email: string): boolean {
  if (typeof email !== "string") return false;
  const trimmed = email.trim().toLowerCase();
  // Minimal RFC-5322-ish sanity: one `@`, non-empty local/domain parts.
  const match = /^([a-z0-9._%+-]+)@([a-z0-9.-]+\.[a-z]{2,})$/.exec(trimmed);
  if (!match) return false;
  const domain = match[2];
  return domain === WHITELIST_DOMAIN;
}

// ---------------------------------------------------------------------------
// Path validation — mirror of apps/backend/src/lib/paths.ts (ADR-010 §5)
// ---------------------------------------------------------------------------

/**
 * Upper bound for the total length of a project-relative path.
 * Same limit the backend uses in `assertValidPath`.
 */
export const PATH_MAX_LENGTH = 512 as const;

/**
 * Maximum number of `/`-separated segments in a project-relative path.
 * Mirrors the backend limit (ADR-010 §5).
 */
export const PATH_MAX_DEPTH = 16 as const;

/**
 * Each individual path segment must match this regex. Mirrors the backend.
 * No spaces, no unicode — the corpus is text files authored by the team.
 */
export const PROJECT_PATH_SEGMENT_REGEX = /^[A-Za-z0-9._-]+$/u;

/**
 * Basenames reserved by Windows, matched case-insensitively and before any
 * extension (`CON.md`, `aux.txt`, etc.). Blocking these in the shared contract
 * keeps project materialization portable across macOS, Linux and Windows.
 */
export const PROJECT_PATH_WINDOWS_RESERVED_NAMES = new Set([
  "con",
  "prn",
  "aux",
  "nul",
  "com1",
  "com2",
  "com3",
  "com4",
  "com5",
  "com6",
  "com7",
  "com8",
  "com9",
  "lpt1",
  "lpt2",
  "lpt3",
  "lpt4",
  "lpt5",
  "lpt6",
  "lpt7",
  "lpt8",
  "lpt9",
]);

/**
 * Full-path regex accepted by the backend. Matches any string composed of
 * one-or-more `PROJECT_PATH_SEGMENT_REGEX` segments separated by `/`, with
 * no leading/trailing slash, no empty segment, and no traversal sequences.
 *
 * Callers should prefer {@link isValidProjectPath} / {@link assertValidProjectPath}
 * because the regex alone does NOT enforce depth/length/dot-segment bans.
 */
export const PROJECT_PATH_REGEX = /^[A-Za-z0-9._-]+(?:\/[A-Za-z0-9._-]+)*$/u;

/** Error thrown when a path fails validation. */
export class InvalidProjectPathError extends Error {
  public readonly path: string;
  public readonly reason: string;
  constructor(path: string, reason: string) {
    super(`invalid path: ${reason} (${JSON.stringify(path)})`);
    this.name = "InvalidProjectPathError";
    this.path = path;
    this.reason = reason;
  }
}

/** Machine-readable result for case-insensitive path collisions. */
export interface ProjectPathCaseCollision {
  folded: string;
  paths: string[];
}

/**
 * Return the first validation failure reason, or `null` when the path is safe
 * to store and materialize on Linux, macOS and Windows.
 */
export function validateProjectPathReason(p: unknown): string | null {
  if (typeof p !== "string") return "not_a_string";
  if (p.length === 0) return "empty";
  if (p.length > PATH_MAX_LENGTH) return "too_long";
  if (p.includes("\0")) return "null_byte";
  if (p.includes("\\")) return "backslash";
  if (p.startsWith("/")) return "absolute";
  if (/^[A-Za-z]:/u.test(p)) return "windows_drive";
  if (p.endsWith("/")) return "trailing_slash";
  if (p.includes("//")) return "empty_segment";

  const segments = p.split("/");
  if (segments.length > PATH_MAX_DEPTH) return "too_deep";
  for (const seg of segments) {
    if (seg === "." || seg === "..") return "dot_segment";
    if (seg.endsWith(".") || seg.endsWith(" ")) {
      return "windows_trailing_dot_or_space";
    }
    const stem = seg.split(".")[0]!.toLowerCase();
    if (PROJECT_PATH_WINDOWS_RESERVED_NAMES.has(stem)) {
      return "windows_reserved_name";
    }
    if (!PROJECT_PATH_SEGMENT_REGEX.test(seg)) return "invalid_segment";
  }
  return null;
}

/**
 * Finds path pairs that would alias on case-insensitive filesystems. The
 * backend uses this before accepting a full tree; local-sync uses the same
 * folded form for conflict reporting.
 */
export function findProjectPathCaseCollision(
  paths: Iterable<string>,
): ProjectPathCaseCollision | null {
  const byFolded = new Map<string, string[]>();
  for (const path of paths) {
    const folded = path.normalize("NFC").toLocaleLowerCase("en-US");
    const list = byFolded.get(folded) ?? [];
    list.push(path);
    byFolded.set(folded, list);
  }
  for (const [folded, list] of byFolded) {
    const unique = Array.from(new Set(list));
    if (unique.length > 1) {
      return { folded, paths: unique.sort((a, b) => a.localeCompare(b)) };
    }
  }
  return null;
}

/**
 * Validate a project-relative path against the same rules the backend
 * enforces in `assertValidPath`. Throws {@link InvalidProjectPathError}
 * with `reason` when invalid.
 */
export function assertValidProjectPath(p: string): void {
  const reason = validateProjectPathReason(p);
  if (reason) {
    throw new InvalidProjectPathError(String(p), reason);
  }
}

/** Boolean convenience wrapper around {@link assertValidProjectPath}. */
export function isValidProjectPath(p: string): boolean {
  try {
    assertValidProjectPath(p);
    return true;
  } catch {
    return false;
  }
}

// ---------------------------------------------------------------------------
// Workspace and project slugs — single source of truth (Lane A refactor).
//
// Historically the same regex was duplicated inline across 6+ sites
// (4 backend route handlers + 2 admin UI components, plus other consumers
// that re-export from here).
// Centralizing the rule means future system slugs (like `_skill-library`,
// reserved for the squad-skills design) only need to be added in one place.
//
// Two shapes coexist intentionally:
//   - Workspace slugs accept ONLY the regex (no whitelist): user-facing.
//   - Project slugs accept the regex OR a system-reserved slug from
//     `SYSTEM_PROJECT_SLUGS`: enables synthetic system projects with
//     a leading underscore (forbidden by the regex itself).
// ---------------------------------------------------------------------------

/**
 * Lowercase kebab-case identifier for workspaces and (regular) projects.
 * Min 2 chars (start + end alphanumeric), middle may include hyphens.
 * Examples: `acme`, `cliente-acme`, `squad-editorial`.
 *
 * NOTE: this is intentionally *different* from `SLUG_REGEX` in
 * `collections/_common.ts`, which uses `[a-z0-9]+(?:-[a-z0-9]+)*` and
 * accepts single-char slugs. Collections and entities have different
 * historical rules; do not unify without a migration plan.
 */
export const WORKSPACE_PROJECT_SLUG_REGEX =
  /^[a-z0-9][a-z0-9-]*[a-z0-9]$/u;

/** Human-readable description for error messages. */
export const WORKSPACE_PROJECT_SLUG_DESCRIPTION =
  "slug must be lowercase kebab-case";

/**
 * Reserved slugs for system projects. Always begin with `_` so they cannot
 * collide with user-defined projects (the regex above forbids underscores).
 *
 * Used by the squad-skills design (Approach A) to materialize the squad
 * library as a synthetic project at `<hub>/<ws-slug>/_skill-library/`.
 * Bootstrapped by `conversion skill publish` on first publish.
 */
export const SYSTEM_PROJECT_SLUGS: ReadonlySet<string> = new Set([
  "_skill-library",
]);

/**
 * Returns `true` iff `slug` is a valid workspace slug.
 * Workspaces have NO system-reserved variants — the regex is authoritative.
 */
export function isValidWorkspaceSlug(slug: unknown): boolean {
  if (typeof slug !== "string") return false;
  return WORKSPACE_PROJECT_SLUG_REGEX.test(slug);
}

/**
 * Returns `true` iff `slug` is a valid project slug — either a regular
 * kebab-case name or a reserved system slug from {@link SYSTEM_PROJECT_SLUGS}.
 *
 * Use this in zod schemas via `.refine(isValidProjectSlug, { message })`
 * because the union of regex + whitelist cannot be expressed as a single
 * `.regex()` without losing the system-slug branch.
 */
export function isValidProjectSlug(slug: unknown): boolean {
  if (typeof slug !== "string") return false;
  if (SYSTEM_PROJECT_SLUGS.has(slug)) return true;
  return WORKSPACE_PROJECT_SLUG_REGEX.test(slug);
}

// ---------------------------------------------------------------------------
// Content canonicalization — mirror of apps/backend/src/lib/blobs/canonicalize.ts
// ---------------------------------------------------------------------------

const UTF8_BOM = new Uint8Array([0xef, 0xbb, 0xbf]);

/**
 * Application/* mime types that we treat as text for canonicalization
 * purposes. Anything else (including `application/octet-stream`) falls
 * through to the "pass through" branch. Mirror of the backend set.
 */
const TEXT_APPLICATION_MIMES: ReadonlySet<string> = new Set<string>([
  "application/json",
  "application/yaml",
  "application/x-yaml",
]);

/**
 * Returns `true` iff `mime` is one of the text-style mimes that we canonicalize
 * (`text/*`, `application/json`, `application/yaml`, `application/x-yaml`).
 * Trailing parameters (`; charset=...`) are stripped before comparison.
 */
export function isTextMime(mime: string): boolean {
  if (typeof mime !== "string" || mime.length === 0) return false;
  const first = mime.toLowerCase().split(";")[0];
  if (!first) return false;
  const lower = first.trim();
  if (lower.startsWith("text/")) return true;
  return TEXT_APPLICATION_MIMES.has(lower);
}

/**
 * Produce the canonical byte representation for hashing.
 *
 * Text mimes:
 *   - Strip UTF-8 BOM (`EF BB BF`) if present.
 *   - Normalize line endings: `\r\n` → `\n`, lone `\r` → `\n`.
 *   - Ensure a single trailing `\n` on non-empty content.
 *
 * Binary mimes: returned as-is (no canonicalization).
 *
 * Accepts either a `Buffer` (Node) or a `Uint8Array` / `ArrayBuffer` for
 * cross-environment use. Returns a `Uint8Array` — the caller wraps it into
 * whatever runtime type it needs (Node `Buffer.from(...)` is free).
 */
export function canonicalizeText(
  input: Uint8Array | ArrayBuffer | string,
  mime: string,
): Uint8Array {
  const raw = toUint8Array(input);

  if (!isTextMime(mime)) {
    return raw;
  }

  // Strip BOM if present.
  const withoutBom = hasBom(raw) ? raw.subarray(3) : raw;

  // Decode UTF-8. TextDecoder is available in every Node 20+ and modern
  // browser runtime. Invalid sequences are replaced with U+FFFD.
  const decoded = new TD("utf-8").decode(withoutBom);

  // Normalize line endings.
  const lfOnly = decoded.replace(/\r\n?/g, "\n");

  // Guarantee a single trailing newline on non-empty content.
  let normalized = lfOnly;
  if (normalized.length > 0) {
    normalized = normalized.replace(/\n+$/g, "") + "\n";
  }

  return new TE().encode(normalized);
}

function hasBom(buf: Uint8Array): boolean {
  if (buf.length < 3) return false;
  return (
    buf[0] === UTF8_BOM[0] && buf[1] === UTF8_BOM[1] && buf[2] === UTF8_BOM[2]
  );
}

function toUint8Array(input: Uint8Array | ArrayBuffer | string): Uint8Array {
  if (typeof input === "string") {
    return new TE().encode(input);
  }
  if (input instanceof Uint8Array) {
    return input;
  }
  return new Uint8Array(input);
}

// ---------------------------------------------------------------------------
// Ambient declarations for text-coder globals.
//
// TextEncoder/TextDecoder are available in every Node ≥ 12 and every modern
// browser runtime, but the `@agenciaconversion/shared` tsconfig only loads
// the ES2022 lib (no DOM, no Node types). To stay runtime-portable without
// forcing every consumer to add @types/node, we declare a minimal subset of
// the shapes we need.
// ---------------------------------------------------------------------------

interface TextEncoderLike {
  encode(input?: string): Uint8Array;
}
interface TextDecoderLike {
  decode(input: Uint8Array): string;
}

declare const TextEncoder: { new (): TextEncoderLike };
declare const TextDecoder: { new (label?: string): TextDecoderLike };

const TE: { new (): TextEncoderLike } = TextEncoder;
const TD: { new (label?: string): TextDecoderLike } = TextDecoder;

// ---------------------------------------------------------------------------
// Sync wire contracts — ADR-010 §1, §2, §5
// ---------------------------------------------------------------------------

/**
 * Blob metadata as returned by the backend `POST /blobs` and inlined in
 * `blob.*` responses. The `sha256` is always the hash of the canonical
 * bytes, not of what the client uploaded.
 */
export interface BlobRef {
  /** 64-char lowercase hex sha256 of the canonical content. */
  sha256: string;
  /** Backing store. 'pg' for text ≤ 256 KB, 'blob' for the rest. */
  storage: "pg" | "blob";
  /** Stored (canonical) size in bytes. */
  sizeBytes: number;
  /** Mime recorded at upload time. */
  mime: string;
}

/** Response to `POST /api/v1/ws/:wsId/blobs`. */
export interface BlobPutResponse {
  blob: BlobRef;
}

/**
 * Local manifest — the CLI's view of the server's current head.
 *
 * Stored at `<project-root>/.conversion/manifest.json`. `treeHash` must be
 * in sync with `files` (i.e. `computeTreeHash({path→sha256})` over `files`
 * yields `treeHash`). `commitId` is `null` for projects that have never
 * been committed to server-side.
 */
export interface Manifest {
  /** UUID v7 — project id from backend. */
  projectId: string;
  /** UUID — workspace id. */
  workspaceId: string;
  workspaceSlug: string;
  projectSlug: string;
  /** sha256 of canonical tree; matches server's tree_hash. */
  treeHash: string;
  /** Commit id this manifest is pinned to; null if project has no commit yet. */
  commitId: string | null;
  /** Timestamp manifest was written (ISO 8601). */
  updatedAt: string;
  /** { path → { sha256, size, mime } }. */
  files: Record<string, { sha256: string; size: number; mime: string }>;
}

/**
 * Request body for `POST /api/v1/ws/:wsId/projects/:projectId/commits`.
 */
export interface CommitRequest {
  /** Client's view of the server's current tree hash (null if no head). */
  parent_tree_hash: string | null;
  /** Client's view of the server's current commit id (null if no head). */
  parent_commit_id?: string | null;
  /** Optional client-chosen UUID used as the commit idempotency key. */
  client_commit_id?: string;
  /** Full snapshot of the new tree: `{path → blob_sha256}`. */
  tree: Record<string, string>;
  /** Optional commit message (max 2000 chars server-side). */
  message?: string;
}

/** 201 response of the commits endpoint. */
export interface CommitResponse {
  commit: {
    id: string;
    treeHash: string;
    parentId: string | null;
    createdAt: string;
  };
  /** True when the server returned a previous commit for the same client id. */
  idempotent?: boolean;
}

/** 409 response of the commits endpoint (optimistic-lock mismatch). */
export interface ConflictResponse {
  error: "conflict";
  /** Null when the project had no head (very unlikely at the conflict site). */
  server_head: { commitId: string; treeHash: string } | null;
}

/** Response of `GET /api/v1/ws/:wsId/projects/:projectId/head`. */
export interface HeadResponse {
  project: { id: string; slug: string; name: string };
  head: {
    commitId: string;
    treeHash: string;
    treeJson: Record<string, string>;
    createdAt: string;
  } | null;
}

/** Response of `GET /api/v1/user/workspaces`. */
export interface UserWorkspacesResponse {
  workspaces: Array<{
    id: string;
    slug: string;
    name: string;
    role: string;
  }>;
}

/** Response of `GET /api/v1/ws/:wsId/projects`. */
export interface ProjectsListResponse {
  projects: Array<{ id: string; slug: string; name: string }>;
}

/** Response of `POST /api/v1/ws/:wsId/projects`. */
export interface CreateProjectResponse {
  project: { id: string; slug: string; name: string };
}

