/**
 * `otimizacao_on_page` collection — a staged, auditable on-page optimization run.
 *
 * A run manifest lives at `index.md`; every stage checkpoint is a sibling
 * artifact whose `artifact_kind` determines the required stage.
 */

import { z } from "zod";

import { IsoDateTimeSchema, SlugSchema } from "./_common.js";

export const ON_PAGE_OPTIMIZATION_TYPE = "otimizacao_on_page" as const;
export const ON_PAGE_OPTIMIZATION_CONVENTIONAL_PATH = "deliverables/otimizacoes/" as const;

export const OnPageOptimizationStatusSchema = z.enum([
  "rascunho",
  "em_execucao",
  "aguardando_aprovacao",
  "bloqueado",
  "aprovado",
  "empacotado",
  "arquivado",
]);

export const OnPageOptimizationStageSchema = z.enum([
  "roteamento",
  "snapshot",
  "serp",
  "diagnostico",
  "campo_semantico",
  "brief",
  "estrutura",
  "redline",
  "seo",
  "qa",
  "empacotamento",
]);

export const ON_PAGE_ARTIFACT_STAGE = {
  route: "roteamento",
  snapshot: "snapshot",
  serp: "serp",
  diagnostico: "diagnostico",
  campo_semantico: "campo_semantico",
  brief: "brief",
  estrutura: "estrutura",
  redline: "redline",
  seo: "seo",
  qa: "qa",
} as const;

const OnPageOptimizationReferencesSchema = z
  .object({
    route: SlugSchema.optional(),
    snapshot: SlugSchema.optional(),
    serp: SlugSchema.optional(),
    diagnostico: SlugSchema.optional(),
    campo_semantico: SlugSchema.optional(),
    brief: SlugSchema.optional(),
    estrutura: SlugSchema.optional(),
    redline: SlugSchema.optional(),
    seo: SlugSchema.optional(),
    qa: SlugSchema.optional(),
  })
  .strict();

const OnPageOptimizationDecisionSchema = z
  .object({
    id: z.string().regex(/^D[1-9]\d*$/u, { message: "decision id must be a D-ID" }),
    stage: OnPageOptimizationStageSchema,
    summary: z.string().min(1).max(2_000),
    approved_at: IsoDateTimeSchema,
  })
  .strict();

const OnPageOptimizationSourcesSchema = z
  .object({
    used_gsc: z.boolean(),
    gsc_path: z.string().min(1).max(512).optional(),
  })
  .strict();

const OnPageOptimizationManifestObjectSchema = z
  .object({
    type: z.literal(ON_PAGE_OPTIMIZATION_TYPE),
    slug: SlugSchema,
    title: z.string().min(1).max(300),
    artifact_kind: z.literal("index"),
    run_slug: SlugSchema,
    url: z.string().url(),
    canonical_url: z.string().url(),
    keyword: z.string().min(1).max(200),
    archetype: z.literal("blog"),
    current_stage: OnPageOptimizationStageSchema,
    status: OnPageOptimizationStatusSchema,
    created_at: IsoDateTimeSchema,
    updated_at: IsoDateTimeSchema,
    references: OnPageOptimizationReferencesSchema,
    artifacts: z.record(z.string(), z.string().min(1).max(512)),
    decisions: z.array(OnPageOptimizationDecisionSchema),
    sources: OnPageOptimizationSourcesSchema,
  })
  .strict();

export const OnPageOptimizationManifestSchema = OnPageOptimizationManifestObjectSchema.superRefine(
  (manifest, ctx) => {
    if (manifest.slug !== manifest.run_slug) {
      ctx.addIssue({
        code: "custom",
        path: ["run_slug"],
        message: "run_slug must match slug for the run manifest",
      });
    }

    const decisionIds = new Set<string>();
    for (const [index, decision] of manifest.decisions.entries()) {
      if (decisionIds.has(decision.id)) {
        ctx.addIssue({
          code: "custom",
          path: ["decisions", index, "id"],
          message: "decision IDs must be unique",
        });
      }
      if (decision.id !== `D${index + 1}`) {
        ctx.addIssue({
          code: "custom",
          path: ["decisions", index, "id"],
          message: "decision IDs must be contiguous D1 through Dn in array order",
        });
      }
      decisionIds.add(decision.id);
    }

    if (manifest.sources.used_gsc && !manifest.sources.gsc_path) {
      ctx.addIssue({
        code: "custom",
        path: ["sources", "gsc_path"],
        message: "gsc_path is required when used_gsc is true",
      });
    }
  },
);

const OnPageOptimizationCheckpointBaseSchema = z
  .object({
    type: z.literal(ON_PAGE_OPTIMIZATION_TYPE),
    slug: SlugSchema,
    title: z.string().min(1).max(300),
    optimization_ref: SlugSchema,
    stage: OnPageOptimizationStageSchema,
    status: OnPageOptimizationStatusSchema,
    created_at: IsoDateTimeSchema,
    updated_at: IsoDateTimeSchema,
  })
  .strict();

const OnPageOptimizationCheckpointSchemaBase = z.discriminatedUnion("artifact_kind", [
  OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("route") }),
  OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("snapshot") }),
  OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("serp") }),
  OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("diagnostico") }),
  OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("campo_semantico") }),
  OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("brief") }),
  OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("estrutura") }),
  OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("redline") }),
  OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("seo") }),
  OnPageOptimizationCheckpointBaseSchema.extend({
    artifact_kind: z.literal("qa"),
    qa_result: z.enum(["aprovado", "reprovado", "aprovado_com_ressalvas"]),
    open_p0: z.number().int().nonnegative(),
    open_p1: z.number().int().nonnegative(),
    open_p2: z.number().int().nonnegative(),
  }),
]);

export const OnPageOptimizationCheckpointSchema =
  OnPageOptimizationCheckpointSchemaBase.superRefine((checkpoint, ctx) => {
    if (checkpoint.stage !== ON_PAGE_ARTIFACT_STAGE[checkpoint.artifact_kind]) {
      ctx.addIssue({
        code: "custom",
        path: ["stage"],
        message: "stage must match artifact_kind",
      });
    }
  });

export const OnPageOptimizationFrontmatterSchema = z
  .discriminatedUnion("artifact_kind", [
    OnPageOptimizationManifestObjectSchema,
    OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("route") }),
    OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("snapshot") }),
    OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("serp") }),
    OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("diagnostico") }),
    OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("campo_semantico") }),
    OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("brief") }),
    OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("estrutura") }),
    OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("redline") }),
    OnPageOptimizationCheckpointBaseSchema.extend({ artifact_kind: z.literal("seo") }),
    OnPageOptimizationCheckpointBaseSchema.extend({
      artifact_kind: z.literal("qa"),
      qa_result: z.enum(["aprovado", "reprovado", "aprovado_com_ressalvas"]),
      open_p0: z.number().int().nonnegative(),
      open_p1: z.number().int().nonnegative(),
      open_p2: z.number().int().nonnegative(),
    }),
  ])
  .superRefine((frontmatter, ctx) => {
    if (frontmatter.artifact_kind === "index") {
      if (frontmatter.slug !== frontmatter.run_slug) {
        ctx.addIssue({
          code: "custom",
          path: ["run_slug"],
          message: "run_slug must match slug for the run manifest",
        });
      }
      if (
        new Set(frontmatter.decisions.map((decision) => decision.id)).size !==
        frontmatter.decisions.length
      ) {
        ctx.addIssue({
          code: "custom",
          path: ["decisions"],
          message: "decision IDs must be unique",
        });
      }
      for (const [index, decision] of frontmatter.decisions.entries()) {
        if (decision.id !== `D${index + 1}`) {
          ctx.addIssue({
            code: "custom",
            path: ["decisions", index, "id"],
            message: "decision IDs must be contiguous D1 through Dn in array order",
          });
        }
      }
      if (frontmatter.sources.used_gsc && !frontmatter.sources.gsc_path) {
        ctx.addIssue({
          code: "custom",
          path: ["sources", "gsc_path"],
          message: "gsc_path is required when used_gsc is true",
        });
      }
      return;
    }

    if (frontmatter.stage !== ON_PAGE_ARTIFACT_STAGE[frontmatter.artifact_kind]) {
      ctx.addIssue({
        code: "custom",
        path: ["stage"],
        message: "stage must match artifact_kind",
      });
    }
  });

export type OnPageOptimizationManifest = z.infer<typeof OnPageOptimizationManifestSchema>;
export type OnPageOptimizationCheckpoint = z.infer<typeof OnPageOptimizationCheckpointSchema>;
export type OnPageOptimizationFrontmatter = z.infer<typeof OnPageOptimizationFrontmatterSchema>;
export type OnPageOptimizationStatus = z.infer<typeof OnPageOptimizationStatusSchema>;
export type OnPageOptimizationStage = z.infer<typeof OnPageOptimizationStageSchema>;
