/**
 * `cluster` collection — topical aggregator of artigos.
 *
 * `references` points to a pillar (`pilar`), N sibling articles (`satelites`)
 * and a backlog of planned ideas (`planejados`). Nothing is embedded — the
 * cluster is a thin pointer structure (ADR-011 §3).
 */

import { z } from "zod";

import { IsoDateTimeSchema, SlugSchema } from "./_common.js";

export const CLUSTER_TYPE = "cluster" as const;
export const CLUSTER_CONVENTIONAL_PATH = "deliverables/clusters/" as const;

export const ClusterStatusSchema = z.enum([
  "active",
  "paused",
  "completed",
  "archived",
]);

const PlanejadoSchema = z
  .object({
    keyword: z.string().min(1).max(200),
    title_sugerido: z.string().min(1).max(300),
  })
  .strict();

const ReferencesSchema = z
  .object({
    pilar: SlugSchema,
    satelites: z.array(SlugSchema),
    planejados: z.array(PlanejadoSchema),
  })
  .strict();

export const ClusterFrontmatterSchema = z
  .object({
    slug: SlugSchema,
    title: z.string().min(1).max(300),
    type: z.literal(CLUSTER_TYPE),
    status: ClusterStatusSchema,
    created_at: IsoDateTimeSchema,
    updated_at: IsoDateTimeSchema,
    references: ReferencesSchema,
  })
  .strict();

export type ClusterFrontmatter = z.infer<typeof ClusterFrontmatterSchema>;
